local config = {
  ui_story_5045_50450101_1_dialog_content = "<color=#737378>Hora: 17:00</color>",
  ui_story_5045_50450101_2_dialog_content = "<color=#737378>Ubicación: Sala de Justicia de Lumo</color>",
  ui_story_5045_50450101_3_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450101_4_dialog_content = "Ejem... Silencio por favor, todos.",
  ui_story_5045_50450101_5_dialog_content = "Un robo despreciable de la peor clase ha ocurrido hoy dentro del Salón de Justicia.",
  ui_story_5045_50450101_6_dialog_content = "Presidiré como juez en este vil caso.",
  ui_story_5045_50450101_7_dialog_content = "¡Juro honrar a mis superiores respetando la ley y emitiendo juicios justos e imparciales lo mejor que pueda!",
  ui_story_5045_50450101_8_dialog_content = "<size=45>Noche Blanca en lo alto. ¡La corte está ahora en sesión!</size>",
  ui_story_5045_50450101_9_dialog_content = "Empezar...",
  ui_story_5045_50450101_10_dialog_content = "<size=32>¿Quién debe ser el primero en hablar? Estaba tan nervioso ahora que mi mente se ha quedado completamente en blanco...</size>",
  ui_story_5045_50450101_11_dialog_content = "(Wow, ya hicieron Angel un juez de pleno derecho!)",
  ui_story_5045_50450101_12_dialog_content = "(Uh... ¿Por qué está mirando en mi dirección?)",
  ui_story_5045_50450101_13_dialog_content = "(Supongo que no importa. Como su amiga, ¡debería hacer todo lo posible para animarla!)",
  ui_story_5045_50450101_14_option_content = "¡Saluda a ella!",
  ui_story_5045_50450101_15_option_content = "¡Sonríele a ella!",
  ui_story_5045_50450101_16_dialog_content = "PlayerName...?",
  ui_story_5045_50450101_17_dialog_content = "Correcto!",
  ui_story_5045_50450101_18_dialog_content = "Comencemos invitando PlayerName, el <color=#1875ad>sospechar</color> en este caso, para comparecer ante el tribunal!",
  ui_story_5045_50450101_19_dialog_content = "¿Eh? ¡¿Q-cuándo me convertí en sospechoso?!",
  ui_story_5045_50450101_20_dialog_content = "Solo vine al Lumo Hall of Justice porque fui invitado aquí...",
  ui_story_5045_50450101_21_dialog_content = "<color=#737378>¡Bang, bang, bang!</color>",
  ui_story_5045_50450101_22_dialog_content = "¡Silencio!",
  ui_story_5045_50450101_23_dialog_content = "Por favor observe las reglas de la corte y responda mis preguntas con honestidad y lo mejor que sepa.",
  ui_story_5045_50450101_24_dialog_content = "(Angel se ve tan serio, sentado en el centro del banco del juez. Su ala blanca se mezcla perfectamente contra ese fondo de aspecto sagrado.)",
  ui_story_5045_50450101_25_dialog_content = "(Ya es bastante malo que me empujen al banquillo de los testigos, pero esa mirada que me está dando... ¡Realmente cree que soy un sospechoso!)",
  ui_story_5045_50450101_26_dialog_content = "(¡Tengo que decirle algo! Quiero gritarlo desde el fondo de mi corazón—)",
  ui_story_5045_50450101_27_option_content = "¡Todo fue un montaje!",
  ui_story_5045_50450101_28_dialog_content = "¿Oh?",
  ui_story_5045_50450101_29_dialog_content = "Tratando de poner excusas por su crimen incluso antes de que comience el interrogatorio, ¿entiendo?",
  ui_story_5045_50450101_30_option_content = "¡Objeción!",
  ui_story_5045_50450101_31_dialog_content = "¡Anulado!",
  ui_story_5045_50450101_32_dialog_content = "¡Tu objeción es denegada porque ni siquiera he comenzado a interrogarte todavía!",
  ui_story_5045_50450101_33_dialog_content = "¿Qué demonios está pasando aquí?",
  ui_story_5045_50450101_34_dialog_content = "Dios mío... ¿Otro humilde plebeyo que quiere ser juez?",
  ui_story_5045_50450101_35_dialog_content = "Toda una afrenta al proceso judicial, ¿no crees?",
  ui_story_5045_50450101_36_dialog_content = "Mantenerla baja, Matthieu.",
  ui_story_5045_50450101_37_dialog_content = "Se supone que no debemos hacer ningún tipo de comentarios en este momento. No le faltes el respeto al Salón de la Justicia de esa manera.",
  ui_story_5045_50450101_38_dialog_content = "Zzz...",
  ui_story_5045_50450101_39_dialog_content = "¡¿No crees que está siendo mucho más irrespetuosa con el Salón en este momento?!",
  ui_story_5045_50450101_40_dialog_content = "Tina, ¡despertar!",
  ui_story_5045_50450101_41_dialog_content = "Yaaaawn... ¿Eh? ¿Por qué? PlayerName tomar el estrado? Es un sospechoso, ¿no?",
  ui_story_5045_50450101_42_dialog_content = "¡Ay! ¡Oh mierda, oh mierda!",
  ui_story_5045_50450101_43_dialog_content = "¡¿No me digas que me perdí las declaraciones iniciales del juicio?!",
  ui_story_5045_50450101_44_dialog_content = "Shhhh!!!",
  ui_story_5045_50450101_45_dialog_content = "Er, ejem... Sólo estábamos confirmando eso. PlayerName está presente hoy.",
  ui_story_5045_50450101_46_dialog_content = "El sospechoso puede regresar a su asiento ahora.",
  ui_story_5045_50450101_47_dialog_content = "(¿Significa esto que tengo que seguir adelante con esto?)",
  ui_story_5045_50450101_48_dialog_content = "Y ahora, le pedimos al querellante, Juez Irridon, hace su declaración de apertura.",
  ui_story_5045_50450101_49_dialog_content = "Muy bien.",
  ui_story_5045_50450101_50_dialog_content = "A las dos de la tarde recibí un aviso del Señor de la Ciudad para asistir a una reunión de última hora.",
  ui_story_5045_50450101_51_dialog_content = "Después de recibir este aviso, cerré la puerta de mi oficina y me fui.",
  ui_story_5045_50450101_52_dialog_content = "Pero cuando regresé a mi oficina a las cuatro en punto, noté que había desaparecido una cantidad sustancial de Nightium.",
  ui_story_5045_50450101_53_dialog_content = "¿Notaste algo inusual en la escena del crimen?",
  ui_story_5045_50450101_54_dialog_content = "La puerta y las ventanas de mi oficina no mostraban signos de entrada forzada, y la puerta todavía estaba cerrada cuando regresé.",
  ui_story_5045_50450101_55_dialog_content = "Aparte de mis propias huellas dactilares, el pomo de la puerta no tenía otros rastros.",
  ui_story_5045_50450101_55X1_dialog_content = "(Realmente no entiendo lo que está pasando aquí, pero Irridon parece estar hablando de algo importante.)",
  ui_story_5045_50450101_55X2_dialog_content = "(¡Será mejor que escriba estos detalles, por si acaso!)",
  ui_story_5045_50450101_56_dialog_content = "¡Esto parece ser un robo bastante misterioso!",
  ui_story_5045_50450101_57_dialog_content = "¿Puede decirle al tribunal por qué sospecha PlayerName de robar el Nightium?",
  ui_story_5045_50450101_58_dialog_content = "Porque encontré una carta en mi oficina, una invitación que había enviado personalmente a PlayerName.",
  ui_story_5045_50450101_59_dialog_content = "Esa invitación debería haber estado en PlayerNamela posesión de...",
  ui_story_5045_50450101_60_dialog_content = "Entonces, ¿qué estaba haciendo dentro de mi oficina cerrada?",
  ui_story_5045_50450101_61_dialog_content = "¡¿Qué?!",
  ui_story_5045_50450101_62_dialog_content = "No solo eso... Alguien atestiguó haber visto PlayerName en las inmediaciones de mi oficina en ese momento.",
  ui_story_5045_50450101_63_dialog_content = "Eso fue porque—",
  ui_story_5045_50450101_64_dialog_content = "<color=#737378>¡Bang, bang, bang!</color>",
  ui_story_5045_50450101_65_dialog_content = "<size=45>¡Silencio! ¡Orden en la corte!</size>",
  ui_story_5045_50450101_66_dialog_content = "Hmm, ¿ahora qué sigue de nuevo? ¡Ah, sí! Ahora escucharemos el testimonio del testigo, el Sr. Pittman!",
  ui_story_5045_50450101_67_dialog_content = "A las dos de la tarde fui a ver al juez Irridon para hacer una serie de preguntas relacionadas con el trabajo...",
  ui_story_5045_50450101_68_dialog_content = "Pero rápidamente me dijo que tenía que irse a una reunión urgente y me pidió que regresara más tarde.",
  ui_story_5045_50450101_69_dialog_content = "Aproximadamente a las tres, caminé de regreso a su oficina para ver si había regresado.",
  ui_story_5045_50450101_70_dialog_content = "Pero cuando me acerqué a su puerta, noté la imagen fugaz de una figura saliendo del mismo lugar.",
  ui_story_5045_50450101_71_dialog_content = "Así que pensé para mí mismo, eso debe haber sido PlayerName.",
  ui_story_5045_50450101_72_dialog_content = "¡Excelente! Y ahora es el momento de juzgar al testigo... ¿Estás listo? PlayerName?",
  ui_story_5045_50450101_73_dialog_content = "¡E-Espere, Su Señoría! ¡Dame la oportunidad de explicarte!",
  ui_story_5045_50450101_74_dialog_content = "Dios mío, no otra vez. Olvidé que se suponía que debía escuchar su refutación primero...",
  ui_story_5045_50450101_75_dialog_content = "A-Ejem, ¡muy bien entonces! Puede ofrecer su refutación ahora.",
  ui_story_5045_50450101_76_dialog_content = "Pero primero, preséntese ante el tribunal.",
  ui_story_5045_50450101_77_dialog_content = "Mi nombre es PlayerName. Soy Caelestita.",
  ui_story_5045_50450101_78_dialog_content = "Por favor, preséntanos tu <color=#1875ad>ocupación</color> también.",
  ui_story_5045_50450101_79_dialog_content = "yo, eh...",
  ui_story_5045_50450101_80_option_content = "Soy la mascota más adorable de Astra.",
  ui_story_5045_50450101_81_option_content = "Soy el pescador Dragonwave.",
  ui_story_5045_50450101_82_option_content = "Soy escalador de torres profesional.",
  ui_story_5045_50450101_83_dialog_content = "Soy el piloto designado de Soroz.",
  ui_story_5045_50450101_84_dialog_content = "¿Podría por favor elaborar?",
  ui_story_5045_50450101_85_dialog_content = "Para decirlo de otra manera, mi trabajo es—",
  ui_story_5045_50450101_86_option_content = "¡Para derrocar a Lumopolis y su tiranía!",
  ui_story_5045_50450101_87_dialog_content = "¡¿Q-Qué?! ¡Lumópolis está prosperando bajo el gobierno justo y equitativo del Señor de la Ciudad! ¡¿Cómo te atreves a revelarnos tus ambiciones impulsadas por el terror?!",
  ui_story_5045_50450101_88_dialog_content = "Te haré saber que aquellos que amenacen la paz de Lumopolis o su gente... ¡pasarán el resto de sus vidas en prisión!",
  ui_story_5045_50450101_89_dialog_content = "(Solo estaba bromeando, pero ella se ve muy seria acerca de sentenciarme...)",
  ui_story_5045_50450101_90_dialog_content = "¡Oh, vamos! ¡Sabes que siempre estoy diciendo locuras como esa!",
  ui_story_5045_50450101_91_option_content = "Para difundir un mensaje de paz y amor!",
  ui_story_5045_50450101_92_option_content = "¡Para salvar al mundo!",
  ui_story_5045_50450101_93_dialog_content = "Comprendido. Deje que los registros muestren que el sospechoso no solo está desempleado sino que también tiene delirios adolescentes.",
  ui_story_5045_50450101_94_dialog_content = "Díganos con sinceridad: ¿dónde estuvo entre las dos y las cuatro de la tarde de esta tarde?",
  ui_story_5045_50450101_95_dialog_content = "He estado en el Salón de la Justicia todo este tiempo.",
  ui_story_5045_50450101_96_dialog_content = "Como Caelestite, ¿por qué has venido al Salón de Justicia de Lumopolis?",
  ui_story_5045_50450101_96X1_dialog_content = "(Eh, ¿p-por qué vine al Salón de la Justicia otra vez?)",
  ui_story_5045_50450101_96X2_dialog_content = "(¡De hecho, parado aquí ahora mismo, mi mente se ha quedado totalmente en blanco!)",
  ui_story_5045_50450101_96X3_dialog_content = "(Afortunadamente, acabo de escribir algunas notas. Tal vez pueda recordar algo de ellas...)",
  ui_story_5045_50450101_97_dialog_content = "¡Noche Blanca en lo alto, deja de intentar descarrilar el proceso!",
  ui_story_5045_50450101_98_dialog_content = "M-Mi culpa...",
  ui_story_5045_50450101_99_dialog_content = "Bien, ahora déjame preguntarte una vez más.",
  ui_story_5045_50450101_100_dialog_content = "Recibí un <color=#1875ad>invitación</color> de Irridon.",
  ui_story_5045_50450101_101_dialog_content = "Me pidió que fuera al Salón de Justicia y la visitara en su oficina.",
  ui_story_5045_50450101_102_dialog_content = "Dijo que quería mostrarme cómo es un juicio adecuado y que tenía un trabajo para mí.",
  ui_story_5045_50450101_103_dialog_content = "Llegué aquí a las dos en punto, pero no había nadie para mostrarme el camino a su oficina.",
  ui_story_5045_50450101_104_dialog_content = "Después de deambular hasta las tres de la tarde, finalmente encontré su oficina. Sólo que... ella no estaba allí en ese momento.",
  ui_story_5045_50450101_105_dialog_content = "Fue entonces cuando decidí irme.",
  ui_story_5045_50450101_106_dialog_content = "Después de eso, pasé el resto de la tarde disfrutando del sol en los escalones del Palacio de Justicia. Es decir, hasta que alguien me trajo a esta pequeña sala del tribunal.",
  ui_story_5045_50450101_107_dialog_content = "¿Oh? ¿Significa esto que admite haber entrado en la oficina del juez Irridon?",
  ui_story_5045_50450101_108_dialog_content = "¡Yo no irrumpí en su oficina! ¡La puerta estaba abierta, así que entré!",
  ui_story_5045_50450101_109_dialog_content = "Imposible. Juez Irridon ella misma dijo que solo se fue después de cerrar la puerta de su oficina.",
  ui_story_5045_50450101_110_dialog_content = "Su refutación fue una completa y absoluta decepción, PlayerName.",
  ui_story_5045_50450101_111_dialog_content = "Su falta de empleo lo hizo desesperado por obtener dinero rápido, por lo que decidió aprovechar la confianza del juez Irridon.",
  ui_story_5045_50450101_112_dialog_content = "Desafortunadamente, olvidaste una cosa importante...",
  ui_story_5045_50450101_113_dialog_content = "¡Este es el Palacio de Justicia de Lumopolis, donde ningún criminal queda impune!",
  ui_story_5045_50450101_114_dialog_content = "Como juez, por la presente declaro:",
  ui_story_5045_50450101_115_dialog_content = "<size=45>Eso PlayerName es <color=#1875ad>culpable</color>!</size>",
  ui_story_5045_50450201_1_dialog_content = "<size=45>Eso PlayerName es <color=#1875ad>culpable</color>!</size>",
  ui_story_5045_50450201_2_dialog_content = "E-Espera, te juro que no soy...",
  ui_story_5045_50450201_3_dialog_content = "¿Eh? PlayerName es culpable?",
  ui_story_5045_50450201_4_dialog_content = "Despertarse justo a tiempo para la mejor parte, ya veo. Madre mía, qué conveniente.",
  ui_story_5045_50450201_5_dialog_content = "Este no es el nivel habitual de rendimiento de Ángel. Ella debe estar muy nerviosa hoy.",
  ui_story_5045_50450201_6_dialog_content = "Como dije, los plebeyos no tienen por qué convertirse en jueces de Lumopolis. La carga es simplemente demasiado grande para que la soporten.",
  ui_story_5045_50450201_7_dialog_content = "Juez Irridon, fallé mi <color=#1875ad>simulacro de juicio</color> de nuevo, ¿no es así?...",
  ui_story_5045_50450201_8_dialog_content = "Espera, esto fue un <color=#1875ad>simulacro de juicio</color> ¡¿todo el tiempo?!",
  ui_story_5045_50450201_9_dialog_content = "Usted es el juez en este momento, Angel.",
  ui_story_5045_50450201_10_dialog_content = "No olvides que todavía no has llamado a la corte para que termine.",
  ui_story_5045_50450201_11_dialog_content = "No estés tan nervioso, Angel!",
  ui_story_5045_50450201_12_dialog_content = "¿Por qué no vas a la sala de descanso y te tomas un tiempo para aclararte la cabeza?",
  ui_story_5045_50450201_13_dialog_content = "No estoy de acuerdo. Debería tomarse unos minutos para ordenar sus pensamientos y ver si hay alguna contradicción en las declaraciones que se dieron hace un momento.",
  ui_story_5045_50450201_14_option_content = "Tina tiene razón.",
  ui_story_5045_50450201_15_dialog_content = "¿En realidad? De hecho, estás de acuerdo conmigo, PlayerName?",
  ui_story_5045_50450201_16_dialog_content = "¡Sí! Ve a tomar un descanso, Angel!",
  ui_story_5045_50450201_17_dialog_content = "A mí también me vendría bien uno, ya que ustedes me acaban de asustar...",
  ui_story_5045_50450201_18_dialog_content = "Gracias por sus amables sugerencias, a todos.",
  ui_story_5045_50450201_19_option_content = "Leyn tiene razón.",
  ui_story_5045_50450201_20_dialog_content = "Tú también lo crees, ¿eh? Gracias, PlayerName.",
  ui_story_5045_50450201_21_dialog_content = "¡Sí! Solo mantén la calma y ordena tus pensamientos, Angel!",
  ui_story_5045_50450201_22_dialog_content = "¡Y aunque es solo un juicio simulado, quiero que todos sepan que NO soy un ladrón! ¿Bueno?",
  ui_story_5045_50450201_23_dialog_content = "Gracias por sus amables sugerencias, a todos.",
  ui_story_5045_50450201_24_option_content = "Sigamos adelante.",
  ui_story_5045_50450201_25_dialog_content = "¿No creen que deberían haberme contado lo de hoy?",
  ui_story_5045_50450201_26_dialog_content = "No tenía idea de lo que estaba pasando, y me declaraste culpable de inmediato... Eso fue un poco complicado, ¿sabes?",
  ui_story_5045_50450201_27_dialog_content = "¿Por qué no lo olvidamos esta vez? Angel? ¡Prometo que actuaré mucho mejor la próxima vez!",
  ui_story_5045_50450201_28_dialog_content = "¡No, eso no funcionará en absoluto!",
  ui_story_5045_50450201_29_dialog_content = "(Whoa. Creo que nunca he visto Angel tan trabajado antes.)",
  ui_story_5045_50450201_30_dialog_content = "(Supongo que debería quedarme al margen...)",
  ui_story_5045_50450201_31_dialog_content = "Ejem... Me siento mucho más compuesto ahora.",
  ui_story_5045_50450201_32_dialog_content = "Estaba tan preocupado por pasar el juicio simulado que me avergoncé delante de todos.",
  ui_story_5045_50450201_33_dialog_content = "Para un juez del Salón de Justicia, las buenas notas nunca serán tan importantes como descubrir la verdad en un caso.",
  ui_story_5045_50450201_34_dialog_content = "Pero incluso si es solo un juicio simulado, ¡nos debemos a nosotros mismos confiar en nuestras decisiones y nunca rendirnos!",
  ui_story_5045_50450201_35_dialog_content = "¡Correcto!",
  ui_story_5045_50450201_36_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450201_37_dialog_content = "Entraremos ahora en el <color=#1875ad>fase de discusión</color> del juicio!",
  ui_story_5045_50450201_38_dialog_content = "La palabra está abierta a cualquier persona que desee hacer preguntas, compartir pensamientos o proporcionar un razonamiento sobre el caso.",
  ui_story_5045_50450201_39_dialog_content = "¡No soy un ladrón!",
  ui_story_5045_50450201_40_dialog_content = "Pero esta invitación prueba que estuviste en mi oficina en algún momento hoy.",
  ui_story_5045_50450201_41_dialog_content = "Más importante aún, tú fuiste quien admitió esto.",
  ui_story_5045_50450201_42_dialog_content = "Es cierto que entré en tu oficina, ¡pero no me llevé nada cuando me fui! ¡Sin mencionar que la puerta estaba abierta cuando llegué allí!",
  ui_story_5045_50450201_43_dialog_content = "Estoy absolutamente seguro de que cerré la puerta con llave antes de irme.",
  ui_story_5045_50450201_44_dialog_content = "Mi conjetura es que usaste tus habilidades psíquicas para abrir la puerta, luego la cerraste una vez más antes de irte.",
  ui_story_5045_50450201_45_dialog_content = "¡Eso no es algo que sea capaz de hacer con mis poderes!",
  ui_story_5045_50450201_46_dialog_content = "Ninguno de nosotros somos Caelestitas, por lo que no podemos estar seguros de si estás mintiendo o no.",
  ui_story_5045_50450201_47_dialog_content = "¡¿Estás tratando de incriminarme, verdad?!",
  ui_story_5045_50450201_48_dialog_content = "¡Objeción! Su Señoría, PlayerName no se le debe permitir realizar ataques personales contra el demandante.",
  ui_story_5045_50450201_49_dialog_content = "Esto no es justo... ¡Ustedes se están uniendo contra mí!",
  ui_story_5045_50450201_50_dialog_content = "PlayerName, tiene derecho a explicar o cuestionar cualquier detalle o evidencia involucrada en este caso.",
  ui_story_5045_50450201_51_dialog_content = "Pero elige tus palabras con cuidado... La honestidad y la integridad son las piedras angulares del Salón de la Justicia.",
  ui_story_5045_50450201_52_dialog_content = "...",
  ui_story_5045_50450201_53_dialog_content = "¿Alguien más en la corte tiene algo que discutir?",
  ui_story_5045_50450201_54_dialog_content = "La situación actual no está nada a tu favor, PlayerName. ¿Tienes algo más que decir?",
  ui_story_5045_50450201_55_dialog_content = "(Algo no esta bien.)",
  ui_story_5045_50450201_56_dialog_content = "(Es cierto que entré en su oficina, pero aparte de esa carta de invitación...)",
  ui_story_5045_50450201_57_dialog_content = "(Debería haber dejado algún otro <color=#1875ad>huellas</color> ¡detrás!)",
  ui_story_5045_50450201_58_dialog_content = "¿Y cuál es exactamente el problema con esto?",
  ui_story_5045_50450201_59_dialog_content = "¿Eh? Supongo que fue algo incorrecto mencionarlo.",
  ui_story_5045_50450201_60_dialog_content = "(¡Vamos, piensa! Aparte de esa carta de invitación...)",
  ui_story_5045_50450201_61_dialog_content = "Irridon Dijo que solo se encontraron sus huellas dactilares en el pomo de la puerta, pero eso no puede ser correcto.",
  ui_story_5045_50450201_62_dialog_content = "¡Porque definitivamente lo giré para entrar en la habitación!",
  ui_story_5045_50450201_63_dialog_content = "¡Lo que significa que mis huellas dactilares también deberían estar en él!",
  ui_story_5045_50450201_64_dialog_content = "¡Estás absolutamente en lo correcto!",
  ui_story_5045_50450201_65_dialog_content = "Creo que el verdadero ladrón debe haber borrado sus propias huellas dactilares para cubrir sus huellas.",
  ui_story_5045_50450201_66_dialog_content = "¡Pero no se dieron cuenta de que también borraron mis huellas dactilares!",
  ui_story_5045_50450201_67_dialog_content = "Hace sentido...",
  ui_story_5045_50450201_68_dialog_content = "¿Cómo podemos estar seguros de que no fuiste tú quien limpió el pomo de la puerta?",
  ui_story_5045_50450201_69_dialog_content = "(Suspiro... Parece que la única forma de limpiar mi nombre es encontrar al verdadero ladrón.)",
  ui_story_5045_50450201_70_dialog_content = "(¡Esperar!)",
  ui_story_5045_50450201_71_dialog_content = "(Yo no soy el ladrón, eso es seguro... Pero <color=#1875ad>el testimonio de esa persona</color> podría darnos una pista!)",
  ui_story_5045_50450201_72_dialog_content = "¿Y cuál es exactamente el problema con esto?",
  ui_story_5045_50450201_73_dialog_content = "L-Lo siento, me hablé mal hace un momento...",
  ui_story_5045_50450201_74_dialog_content = "(Solo cálmate y piensa cuidadosamente...)",
  ui_story_5045_50450201_75_dialog_content = "¿Cuándo exactamente me viste \"escabulléndote\", Pittman?",
  ui_story_5045_50450201_76_dialog_content = "Aproximadamente a las tres.",
  ui_story_5045_50450201_77_dialog_content = "¿Puedes ser más específico sobre el tiempo?",
  ui_story_5045_50450201_78_dialog_content = "Creo... Podría haber sido diez minutos después de la hora más o menos.",
  ui_story_5045_50450201_79_dialog_content = "Eso es extraño, considerando que salí de la oficina poco antes de que el reloj diera las tres, así que, ¿cómo me viste allí exactamente?",
  ui_story_5045_50450201_80_dialog_content = "Debo mencionar que el reloj dio las tres justo después de que salí del Salón de Justicia.",
  ui_story_5045_50450201_81_dialog_content = "Los guardias que estaban estacionados afuera pueden dar fe de esto.",
  ui_story_5045_50450201_82_dialog_content = "E-Esto...",
  ui_story_5045_50450201_83_dialog_content = "No puedo estar seguro, pero es posible que la figura que vi fuera el verdadero ladrón.",
  ui_story_5045_50450201_84_dialog_content = "¡Lo que significaría que fue otra persona y no yo! Bien, Pittman?",
  ui_story_5045_50450201_85_dialog_content = "Ese parece ser el caso, sí.",
  ui_story_5045_50450201_86_dialog_content = "Así que ya ve, Su Señoría, Pittman no tiene forma de confirmar que la figura que vio merodeando fuera en realidad yo.",
  ui_story_5045_50450201_87_dialog_content = "¡Como tal, su acusación debe ser ignorada!",
  ui_story_5045_50450201_88_dialog_content = "Parece que es así...",
  ui_story_5045_50450201_89_dialog_content = "Pero eso no significa que te hayas despejado de sospechas.",
  ui_story_5045_50450201_90_dialog_content = "¿Por qué no tratamos de ver las cosas un poco diferente? Supongamos que no soy el ladrón; al hacer eso, puede ver claramente muchos problemas con el caso.",
  ui_story_5045_50450201_91_dialog_content = "En primer lugar, ¿cómo logró el ladrón abrir la puerta? ¿Es posible que tuvieran una llave extra?",
  ui_story_5045_50450201_92_dialog_content = "...",
  ui_story_5045_50450201_93_dialog_content = "En segundo lugar, ¿por qué el ladrón se tomaría la molestia de borrar sus huellas dactilares?",
  ui_story_5045_50450201_94_dialog_content = "Tendría sentido si se tratara de alguien asociado con el Salón de la Justicia, ya que todo lo que se necesita para exponerlos es una investigación rápida.",
  ui_story_5045_50450201_95_dialog_content = "...",
  ui_story_5045_50450201_96_dialog_content = "Dinos, Pittman, es posible que tu seas el ladron?",
  ui_story_5045_50450201_97_dialog_content = "¿Cómo podría ser eso?",
  ui_story_5045_50450201_98_dialog_content = "Eres el subordinado de mayor confianza de Irridon, después de todo. Si alguien sabe que ella dejó a Nightium en su oficina, eres tú.",
  ui_story_5045_50450201_99_dialog_content = "No solo eso, sino que también viste Irridon salir de su oficina, que habría sido el momento perfecto para sacar una llave de repuesto y entrar.",
  ui_story_5045_50450201_100_dialog_content = "Pero fue solo después de que te fuiste con el Nightium que te diste cuenta. ¡Tus huellas dactilares aún estaban en el pomo de la puerta!",
  ui_story_5045_50450201_101_dialog_content = "Fue entonces cuando te apresuraste a limpiarlos y cerrar la puerta de nuevo, haciendo que pareciera que el dinero desapareció.",
  ui_story_5045_50450201_102_dialog_content = "¡Lo que no sabías es que también me arrastraste a tu crimen!",
  ui_story_5045_50450201_103_dialog_content = "Así que cuando viste eso Irridon sospechaba que yo había robado su Nightium, ¡usted tomó la iniciativa e intentó que yo asumiera la culpa por usted!",
  ui_story_5045_50450201_104_dialog_content = "¡Todo esto es pura especulación salvaje, nada más! ¡¿Tienes alguna prueba?!",
  ui_story_5045_50450201_105_dialog_content = "Es cierto que estoy asumiendo muchas cosas aquí. ¡Pero déjame preguntarte algo! Cuando toqué todos esos puntos...",
  ui_story_5045_50450201_106_dialog_content = "¿Por qué de repente empezaste a sudar tanto? Además, ¿por qué sigues buscando tu <color=#1875ad>bolsillo</color> cada pocos segundos?",
  ui_story_5045_50450201_107_dialog_content = "¿Podría ser que realmente tenga una llave de repuesto para la oficina de Irridon allí?",
  ui_story_5045_50450201_108_dialog_content = "Señor. Pittman, muestre al tribunal lo que tiene en el bolsillo.",
  ui_story_5045_50450201_109_dialog_content = "...",
  ui_story_5045_50450201_110_dialog_content = "Supongo que no tengo elección.",
  ui_story_5045_50450201_111_dialog_content = "¡Esta llave es una copia exacta de la llave de mi oficina!",
  ui_story_5045_50450201_112_dialog_content = "Señor. Pittman, está acusado de robar el Nightium del juez Irridon. ¿Tienes algo que decir por ti mismo?",
  ui_story_5045_50450201_113_dialog_content = "Yo... yo no. No tengo nada que decir.",
  ui_story_5045_50450201_114_dialog_content = "Si ese es el caso, por la presente declaro—",
  ui_story_5045_50450201_115_dialog_content = "<size=45>Pittman es <color=#1875ad>culpable</color> de este crimen!</size>",
  ui_story_5045_50450201_116_dialog_content = "Vaya... Me alegro de que haya terminado.",
  ui_story_5045_50450201_117_dialog_content = "Sabía que iba a fallar en mi juicio simulado...",
  ui_story_5045_50450201_118_dialog_content = "No hay necesidad de sentirse desanimado, Angel. Habrá más oportunidades en el futuro.",
  ui_story_5045_50450201_119_dialog_content = "Tus mayores aquí no fueron diferentes. Solo se convirtieron en jueces después de someterse a innumerables juicios y evaluaciones simuladas.",
  ui_story_5045_50450201_120_dialog_content = "Es cierto. De hecho, ¡fallé en más juicios simulados que nadie en la historia del Salón de Justicia!",
  ui_story_5045_50450201_121_dialog_content = "No dejes que la emoción de Leyn te engañe, Angel. Eso no es realmente algo de lo que estar orgulloso.",
  ui_story_5045_50450201_122_dialog_content = "Perdóname, juez Irridon, pero lamento discrepar. Si recuerdas correctamente, ¡pasé mi evaluación en mi primer intento!",
  ui_story_5045_50450201_123_dialog_content = "Sí, me parece recordar ahora. Ya que estamos en el tema, Matthieu...",
  ui_story_5045_50450201_124_dialog_content = "Dado que Loewe ha estado de baja recientemente, Angel trabajará con usted como su asistente durante los próximos días. Creo que podría aprender mucho de ti.",
  ui_story_5045_50450201_125_dialog_content = "Con mi inteligencia y talento, no creo que necesite un asistente, juez. Irridon!",
  ui_story_5045_50450201_126_dialog_content = "¿No crees que nuestros mejores jueces tienen la responsabilidad de capacitar a nuestras generaciones futuras para que sean igual de ejemplares?",
  ui_story_5045_50450201_127_dialog_content = "Ya lo veo...",
  ui_story_5045_50450201_128_dialog_content = "No podría tener más razón, juez. Irridon!",
  ui_story_5045_50450201_129_dialog_content = "Como uno de los jueces más grandes que haya honrado el Salón de la Justicia, ¡juro estar a la altura de sus expectativas y transmitirle todo mi conocimiento a mi nuevo aprendiz!",
  ui_story_5045_50450201_130_dialog_content = "Solo trata de no esperar demasiado de ella... ¡Después de todo, no muchos pueden compararse con mi grandeza!",
  ui_story_5045_50450201_131_dialog_content = "<size=32>¡Pero quiero ser el asistente del Sr. Pittman!</size>",
  ui_story_5045_50450301_1_dialog_content = "<color=#737378>Hora: 20:00</color>",
  ui_story_5045_50450301_2_dialog_content = "<color=#737378>Ubicación: Sala de Justicia de Lumo</color>",
  ui_story_5045_50450301_3_dialog_content = "Realmente no tenía idea de que tú, de todas las personas, serías quien finalmente resolvería este caso.",
  ui_story_5045_50450301_4_dialog_content = "Fue pura suerte, de verdad...",
  ui_story_5045_50450301_5_dialog_content = "(Honestamente, la actuación convincente de Pittman es lo que realmente me salvó).",
  ui_story_5045_50450301_6_dialog_content = "Ey, Irridon? Algo me dice que el simulacro de juicio de hoy se basó en un caso real de robo.",
  ui_story_5045_50450301_7_dialog_content = "De hecho fue. Otra suposición astuta, PlayerName.",
  ui_story_5045_50450301_8_dialog_content = "¡También sé que solo me enviaste esa carta para involucrarme en todo este asunto!",
  ui_story_5045_50450301_9_dialog_content = "Sabes, si me hubieras dicho que era para un juicio simulado, podría haber sido más útil.",
  ui_story_5045_50450301_10_dialog_content = "En un juicio real, surgen situaciones inesperadas todo el tiempo.",
  ui_story_5045_50450301_11_dialog_content = "Simplemente queríamos introducir algunas variables independientes al juicio simulado.",
  ui_story_5045_50450301_12_dialog_content = "Sin embargo, fue solo gracias a ti que Angel fue capaz de llevar el juicio a una conclusión satisfactoria.",
  ui_story_5045_50450301_13_dialog_content = "Ya veo... Supongo que eso me convierte en una variable bastante fiable, ¿eh?",
  ui_story_5045_50450301_14_dialog_content = "En efecto. Tus poderes de observación son increíblemente agudos.",
  ui_story_5045_50450301_15_dialog_content = "De hecho, y lo digo sin exagerar, su desempeño de hoy estuvo al mismo nivel que muchos de nuestros jueces en sus evaluaciones.",
  ui_story_5045_50450301_16_dialog_content = "Ojalá tuviéramos más personas como usted aquí en el Salón de la Justicia.",
  ui_story_5045_50450301_17_dialog_content = "Pero basta de eso.",
  ui_story_5045_50450301_18_dialog_content = "Nos gustaría compensarte por tu ayuda hoy. Considéralo una muestra de gratitud de todos nosotros en el Salón de la Justicia.",
  ui_story_5045_50450301_19_dialog_content = "¿compensarme?",
  ui_story_5045_50450301_20_dialog_content = "Aquí tienes: los bienes robados del simulacro de juicio de hoy.",
  ui_story_5045_50450301_21_dialog_content = "Guau, pensé que este Nightium solo se estaba usando como apoyo para el juicio.",
  ui_story_5045_50450301_22_dialog_content = "¿De verdad me estás dando esto?",
  ui_story_5045_50450301_23_dialog_content = "¿Por qué? ¿Es muy poco?",
  ui_story_5045_50450301_24_dialog_content = "NN-¡De nada! ¡Es más que suficiente!",
  ui_story_5045_50450301_25_dialog_content = "De hecho, ¡no dudes en llamarme cuando tengas más trabajos como este!",
  ui_story_5045_50450301_26_dialog_content = "¿En realidad? No tenía idea de que estuvieras tan interesado en trabajar para el Salón de la Justicia, PlayerName...",
  ui_story_5045_50450301_27_dialog_content = "Quiero decir, aparte del shock inicial...",
  ui_story_5045_50450301_28_dialog_content = "¡En realidad encontré el trabajo bastante interesante!",
  ui_story_5045_50450301_29_dialog_content = "Escucharte decir eso me trae mucha alegría.",
  ui_story_5045_50450301_30_dialog_content = "Dime, ¿te gustaría pasar un tiempo aquí y trabajar con nosotros?",
  ui_story_5045_50450301_31_dialog_content = "Verá, recientemente establecí un nuevo departamento dentro del Salón de la Justicia, y nos vendría bien alguien con habilidades interpersonales como las suyas.",
  ui_story_5045_50450301_32_dialog_content = "¿Un nuevo departamento?",
  ui_story_5045_50450301_33_dialog_content = "Parece que estás interesado, después de todo. En ese caso, por favor acepte esto. Lo necesitarás pronto.",
  ui_story_5045_50450301_34_dialog_content = "Esto es un<color=#1875ad> Cuaderno del juez</color>?",
  ui_story_5045_50450301_35_dialog_content = "A partir de este día, eres un <color=#1875ad>juez de prueba</color> de la Sala de Justicia.",
  ui_story_5045_50450301_36_dialog_content = "<color=#737378>Hora: 8:00 AM</color>",
  ui_story_5045_50450301_37_dialog_content = "<color=#737378>Ubicación: Una oficina en el Lumo Hall of Justice</color>",
  ui_story_5045_50450301_38_dialog_content = "¿Es este el lugar donde Irridon me dijo que denunciara?",
  ui_story_5045_50450301_39_dialog_content = "¡Buenos días a todos! Cómo puedo ayudar-",
  ui_story_5045_50450301_40_dialog_content = "¡¿Qué clase de caso es este?!",
  ui_story_5045_50450301_41_dialog_content = "El demandante tiene razón, pero también el demandado...",
  ui_story_5045_50450301_42_dialog_content = "No veo ninguna ley o precedente legal que se aplique a este caso. ¿A quién se supone que debo creer aquí?",
  ui_story_5045_50450301_43_dialog_content = "Zzz...",
  ui_story_5045_50450301_44_dialog_content = "Échale un buen vistazo, Angel.",
  ui_story_5045_50450301_45_dialog_content = "Por eso estás estudiando conmigo, y no con uno de esos dos jueces inútiles.",
  ui_story_5045_50450301_46_dialog_content = "Pero señor, que yo sepa, sus notas no son mucho mejores que las de ellos...",
  ui_story_5045_50450301_47_dialog_content = "<size=32>Esto explicaría por qué te asignaron a un departamento tan pequeño junto con ellos...</size>",
  ui_story_5045_50450301_48_dialog_content = "Dios mío. Eres incluso peor que Loewe, ¿no?",
  ui_story_5045_50450301_49_dialog_content = "Permítanme repetirme: ¡Elegí transferirme a este departamento por puro interés y mi abrumador sentido del deber!",
  ui_story_5045_50450301_50_dialog_content = "Ahora, a menos que quieras seguir fallando en tus evaluaciones, te sugiero que recojas tus cosas y vengas rápido.",
  ui_story_5045_50450301_51_dialog_content = "Sí señor...",
  ui_story_5045_50450301_52_dialog_content = "¿Mmm? ¿Por qué si no es PlayerName! ¿Qué te trae a la puerta de la <color=#1875ad>División de Romance del Salón de la Justicia</color> ¿hoy?",
  ui_story_5045_50450301_53_dialog_content = "Guau, incluso les dieron una oficina tan linda para la División de Romance...",
  ui_story_5045_50450301_54_dialog_content = "¿Agradable, dices? ¡Ja!",
  ui_story_5045_50450301_55_dialog_content = "¡Solo espere hasta que sea el juez principal de la División de Romance, entonces verá una oficina realmente adecuada para un noble como yo!",
  ui_story_5045_50450301_56_dialog_content = "¿Juez jefe de la División de Romance?",
  ui_story_5045_50450301_57_dialog_content = "¡Sí, y harías bien en salir de mi camino ahora!",
  ui_story_5045_50450301_58_dialog_content = "...",
  ui_story_5045_50450301_59_dialog_content = "Suspiro... Desde que se estableció la División de Romance, el puesto de Juez Jefe siguió rotando entre diferentes personas. Mientras tanto, nuestra acumulación de casos solo se hace más y más grande.",
  ui_story_5045_50450301_60_dialog_content = "Tal como está, nadie está dispuesto a servir como juez principal de la División de Romance.",
  ui_story_5045_50450301_61_dialog_content = "... Con la excepción de mis mayores aquí, por supuesto. Están haciendo todo lo que está a su alcance para ser ascendidos a juez principal.",
  ui_story_5045_50450301_62_dialog_content = "<size=45>No me hagas esperar, Angel!!</size>",
  ui_story_5045_50450301_63_dialog_content = "Suspiro... Bueno, la mejor de las suertes, PlayerName!",
  ui_story_5045_50450301_64_dialog_content = "Pensé que el nuevo departamento Irridon mencionado anteriormente fue específicamente para juicios simulados.",
  ui_story_5045_50450301_65_dialog_content = "¿Qué diablos es una División de Romance...?",
  ui_story_5045_50450301_66_dialog_content = "¿PlayerName?",
  ui_story_5045_50450301_67_dialog_content = "Así que eres el miembro más nuevo de la División de Romance, ¿eh?",
  ui_story_5045_50450301_68_option_content = "Creo que ha habido un error.",
  ui_story_5045_50450301_69_dialog_content = "Juez Irridon Te pedí que nos ayudaras, ¿verdad?",
  ui_story_5045_50450301_70_dialog_content = "Así es.",
  ui_story_5045_50450301_71_dialog_content = "Entonces, ¿por qué habría un error? este es el juez Irridon estamos hablando, después de todo.",
  ui_story_5045_50450301_72_dialog_content = "¡Así que eres el miembro más nuevo de la División de Romance!",
  ui_story_5045_50450301_73_option_content = "Espero no empeorar las cosas.",
  ui_story_5045_50450301_74_dialog_content = "Eres demasiado modesto.",
  ui_story_5045_50450301_75_dialog_content = "Juez Irridon lo eligió personalmente como nuestro miembro más nuevo. ¡Seguro que podremos aprender mucho de ti!",
  ui_story_5045_50450301_76_option_content = "Bueno, es bueno que estés aquí.",
  ui_story_5045_50450301_77_dialog_content = "Tener a alguien tan confiable como usted en el equipo realmente me tranquiliza.",
  ui_story_5045_50450301_78_dialog_content = "¡Tengo muchas ganas de aprender de ti!",
  ui_story_5045_50450301_79_dialog_content = "¡N-No esperes demasiado! No he estado trabajando en la División de Romance por mucho tiempo. Todavía soy bastante nuevo en esto también.",
  ui_story_5045_50450301_80_dialog_content = "Zzz...",
  ui_story_5045_50450301_81_dialog_content = "¿Quién está aquí?",
  ui_story_5045_50450301_82_dialog_content = "¡Oye, es nuestro principal sospechoso del simulacro de juicio de ayer! Qué gusto verte de nuevo, PlayerName!",
  ui_story_5045_50450301_83_dialog_content = "Aunque si estás aquí, ¿debe significar que tienes serios problemas de relación?",
  ui_story_5045_50450301_84_dialog_content = "Simplemente envíe una queja formal con todos los detalles de su disputa, ¡y nos pondremos manos a la obra! Bostezo-",
  ui_story_5045_50450301_85_option_content = "¡Yo no tengo ese tipo de problemas!",
  ui_story_5045_50450301_86_dialog_content = "¿Oh? Suenas bastante seguro de ti mismo.",
  ui_story_5045_50450301_87_dialog_content = "¿Es porque en secreto eres un artista del pick-up? ¿O tal vez eres uno de esos nerds con corazón de hierro?",
  ui_story_5045_50450301_88_dialog_content = "¡N-Ninguna de las anteriores! ¡Estoy aquí para ayudarlos!",
  ui_story_5045_50450301_89_dialog_content = "¡Ah, entonces eres el chico nuevo! ¡Bienvenido Bienvenido!",
  ui_story_5045_50450301_90_option_content = "Lo siento por despertarte.",
  ui_story_5045_50450301_91_dialog_content = "Guau. ¡Esta es la primera vez que alguien se disculpa por despertarme! Estoy tan conmovido...",
  ui_story_5045_50450301_92_dialog_content = "Es broma, ¡no me importa en absoluto! Además, debería estar despierto ahora mismo, ya que tenemos un nuevo miembro que se une a nuestro departamento hoy.",
  ui_story_5045_50450301_93_dialog_content = "Ese nuevo miembro... Estoy bastante seguro de que soy yo.",
  ui_story_5045_50450301_94_dialog_content = "¡Ah, entonces eres el chico nuevo! ¡Bienvenido Bienvenido!",
  ui_story_5045_50450301_95_option_content = "Estoy aqui para ayudar.",
  ui_story_5045_50450301_96_dialog_content = "Aunque todavía no tengo ni idea de cómo voy a hacer eso...",
  ui_story_5045_50450301_97_dialog_content = "Guau. ¡Así que eres la nueva y prometedora incorporación a nuestro equipo! ¡No tienes idea de cuánto he estado esperando esto!",
  ui_story_5045_50450301_98_dialog_content = "De hecho, anoche incluso soñé que venías a la División de Romance, PlayerName! ¡Nunca pensé que mi sueño se haría realidad!",
  ui_story_5045_50450301_99_dialog_content = "Siempre le digo a la gente que no tiene nada de malo dormir y soñar un poco más de lo habitual, ¡y precisamente por eso!",
  ui_story_5045_50450301_100_dialog_content = "Y con tu ayuda, PlayerName... ¡Incluso podría ser ascendido a juez principal!",
  ui_story_5045_50450301_101_dialog_content = "¿De qué estás hablando, Tina?",
  ui_story_5045_50450301_102_dialog_content = "¿Eh? Quieres decir que aún no te has dado cuenta, Leyn?",
  ui_story_5045_50450301_103_dialog_content = "Nadie quiere servir como juez principal de un departamento tan incómodo y complicado como el nuestro en este momento...",
  ui_story_5045_50450301_104_dialog_content = "Es por eso que Matthieu tiene tanta prisa por empezar a trabajar en estos casos mientras el puesto aún está vacante.",
  ui_story_5045_50450301_105_dialog_content = "Piensa que al hacerlo, Juez Irridon podría considerar nombrarlo como el jefe de nuestro departamento!",
  ui_story_5045_50450301_106_dialog_content = "Matthieu? ¿Como juez principal de la división de romances?",
  ui_story_5045_50450301_107_dialog_content = "Así es. Puedes imaginar cómo serían nuestras vidas si tuviera éxito, ¿no? ¡Es por eso que estaríamos mejor conmigo a cargo!",
  ui_story_5045_50450301_108_dialog_content = "No me importaría en absoluto que lo eligieran como juez principal, Leyn.",
  ui_story_5045_50450301_109_dialog_content = "Solo me preocupa que contigo a cargo, los otros departamentos puedan menospreciar aún más a la División de Romance.",
  ui_story_5045_50450301_110_dialog_content = "Pueden menospreciarme todo lo que quieran, ¡pero no a la División de Romance!",
  ui_story_5045_50450301_111_dialog_content = "¡Si me nombran juez principal de nuestro departamento, juro que haré todo lo que esté a mi alcance para obtener el respeto que merecemos!",
  ui_story_5045_50450301_112_dialog_content = "Hmm... Parece que también tienes el ojo puesto en la posición, Leyn.",
  ui_story_5045_50450301_113_dialog_content = "¡Bien! ¡Un poco de competencia amistosa nos motivará a trabajar aún más duro!",
  ui_story_5045_50450301_114_dialog_content = "estaré contando contigo, PlayerName!",
  ui_story_5045_50450301_115_dialog_content = "Oye, ¿qué se supone que significa eso? PlayerName está aquí para ayudar a todo nuestro departamento! ¡No puedes tenerlo todo para ti!",
  ui_story_5045_50450301_116_dialog_content = "¿Oh? Pero pensé que no te gustaba trabajar con otros, Leyn?",
  ui_story_5045_50450301_117_dialog_content = "¿O podría ser que te sientes un poco envidioso?",
  ui_story_5045_50450301_118_dialog_content = "Me pregunto, ¿estás celoso de mí porque tengo PlayerName de mi lado, o estás celoso de PlayerName porque se pone a trabajar conmigo?",
  ui_story_5045_50450301_119_dialog_content = "Solo me preocupa que pongas demasiado estrés en PlayerName, eso es todo.",
  ui_story_5045_50450301_120_dialog_content = "Tenemos mucho en nuestro plato, y dado que solo puedes trabajar por un corto período de tiempo... Espera, no estás planeando imponer tu carga de trabajo en PlayerName, ¡¿eres?!",
  ui_story_5045_50450301_121_dialog_content = "Dios mío, no tenía idea de que pudieras ser tan comprensivo con otras personas.",
  ui_story_5045_50450301_122_dialog_content = "De todos modos, deberá encontrar una solución más sostenible para su problema.",
  ui_story_5045_50450301_123_dialog_content = "¡Tengo una idea!",
  ui_story_5045_50450301_124_dialog_content = "¿Por qué no dejamos PlayerName decidir con quién quiere trabajar?",
  ui_story_5045_50450301_125_dialog_content = "Veo. Eso suena bastante justo para mí.",
  ui_story_5045_50450301_126_dialog_content = "¿Qué opinas, nombre del jugador?",
  ui_story_5045_50450301_127_dialog_content = "No creo que pueda hacer ese tipo de elección en este momento.",
  ui_story_5045_50450301_128_dialog_content = "¡Entonces no lo pienses tanto! Estarías mucho mejor como mi asistente, ¿sabes? ¡Incluso puedo pagarle extra, si es necesario!",
  ui_story_5045_50450301_129_dialog_content = "E-Eso no es...",
  ui_story_5045_50450301_130_dialog_content = "Puede que no tenga los fondos para comprar sus servicios como algunas personas, pero le garantizo que su mano de obra no será explotada si elige trabajar para mí.",
  ui_story_5045_50450301_131_dialog_content = "Tomaré la parte del león del trabajo; todo lo que tienes que hacer es ofrecerme una nueva perspectiva de vez en cuando y recordarme que sea justo en todo momento.",
  ui_story_5045_50450301_132_dialog_content = "(Ambos parecen realmente desesperados por mi ayuda...)",
  ui_story_5045_50450301_133_dialog_content = "(¡¿Qué tengo que hacer?!)",
  ui_story_5045_50450301_134_option_content = "Elegir Leyn",
  ui_story_5045_50450301_135_dialog_content = "Para ser honesto, no tengo idea de cómo ayudarlos en el Salón de la Justicia, para el caso.",
  ui_story_5045_50450301_136_dialog_content = "pero si que Leyn dice que es verdad, creo que puedo manejar ese tipo de trabajo.",
  ui_story_5045_50450301_137_dialog_content = "¡Estoy seguro de que lo harás bien!",
  ui_story_5045_50450301_138_option_content = "Elegir Tina",
  ui_story_5045_50450301_139_dialog_content = "Bueno, desde Tina realmente necesita ayuda en este momento, supongo que puedo intentarlo.",
  ui_story_5045_50450301_140_dialog_content = "Sin embargo, ¡una advertencia justa! ¡Tengo casi cero conocimiento de cualquiera de estas cosas!",
  ui_story_5045_50450301_141_dialog_content = "No te preocupes. Me aseguraré de enseñarte todo lo que sé... Bostezo—",
  ui_story_5045_50450301_142_dialog_content = "Pero primero, una siesta rápida.",
  ui_story_5045_50450301_143_option_content = "no elijas ninguno",
  ui_story_5045_50450301_144_dialog_content = "Dijeron que soy el miembro más nuevo de la División de Romance, ¿verdad? Entonces, ¿qué me impide competir con ustedes por el puesto de juez principal?",
  ui_story_5045_50450301_145_dialog_content = "Cuando lo pones de esa manera, ¡supongo que eres libre de hacerlo también! Pero primero tendrás que convertirte en un juez real.",
  ui_story_5045_50450301_146_dialog_content = "Sabes, Tina, si PlayerName tiene la confianza suficiente para decir algo como esto, creo que deberíamos ofrecerle todo nuestro apoyo.",
  ui_story_5045_50450301_147_dialog_content = "¿Quién sabe? Incluso podría volar a través del entrenamiento y convertirse en juez en poco tiempo, al igual que Matthieu!",
  ui_story_5045_50450301_148_dialog_content = "Me parece bien... Bostezo...",
  ui_story_5045_50450401_1_dialog_content = "<color=#737378>Hora: 18:00</color>",
  ui_story_5045_50450401_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50450401_3_dialog_content = "Entonces, ¿hay algo más en lo que pueda ayudar? Leyn?",
  ui_story_5045_50450401_4_dialog_content = "Oh, solo reúna el resto de esas declaraciones y eso debería ser suficiente.",
  ui_story_5045_50450401_5_dialog_content = "Puedo encargarme del resto.",
  ui_story_5045_50450401_6_dialog_content = "Aunque a estas alturas, deberías estar preparándote para ir a casa por el día.",
  ui_story_5045_50450401_7_dialog_content = "¿Y tú?",
  ui_story_5045_50450401_8_dialog_content = "Hoy recibimos otras cien quejas que aún deben revisarse.",
  ui_story_5045_50450401_9_dialog_content = "Una vez hecho esto, debo tomar las quejas que faltan materiales y devolverlas para que se vuelvan a presentar.",
  ui_story_5045_50450401_10_dialog_content = "Pero ya es muy tarde... ¿De verdad te quedas para hacer todo eso?",
  ui_story_5045_50450401_11_dialog_content = "A decir verdad... Los casos que lleva la División de Romance son todos muy difíciles de entender para mí.",
  ui_story_5045_50450401_12_dialog_content = "Necesito tomarme el tiempo para estudiarlos y aprender a juzgarlos lo mejor que pueda.",
  ui_story_5045_50450401_13_dialog_content = "Ya veo... Pero por lo que puedo decir, ya los ha marcado todos para volver a enviarlos. ¿Porque eso?",
  ui_story_5045_50450401_14_dialog_content = "De acuerdo con las disposiciones correspondientes recientemente modificadas de Lumopolis, hasta ahora, todos los casos que he manejado han tenido algunos problemas.",
  ui_story_5045_50450401_15_dialog_content = "Sólo estoy siguiendo las reglas, eso es todo.",
  ui_story_5045_50450401_16_dialog_content = "Pero a este ritmo, ¡nunca podrá cerrar un solo caso!",
  ui_story_5045_50450401_17_dialog_content = "Je... Parece que tienes más prisa que yo.",
  ui_story_5045_50450401_18_dialog_content = "¡Bueno obviamente! Somos socios, ¿no?",
  ui_story_5045_50450401_19_dialog_content = "Socios...?",
  ui_story_5045_50450401_20_dialog_content = "¡Es Correcto!",
  ui_story_5045_50450401_21_dialog_content = "Aprecio tu preocupación, de verdad, pero juré que no me aprovecharía de tu trabajo.",
  ui_story_5045_50450401_22_dialog_content = "Bien... Entonces pasemos el rato un rato, ¿de acuerdo? Parece que te vendría bien un descanso rápido.",
  ui_story_5045_50450401_23_dialog_content = "Seguro. Además, he querido preguntarte algo, PlayerName.",
  ui_story_5045_50450401_24_dialog_content = "¿Sabes lo que es el amor?",
  ui_story_5045_50450401_25_dialog_content = "¿Amo?",
  ui_story_5045_50450401_26_option_content = "Si.",
  ui_story_5045_50450401_27_dialog_content = "Es cuando dos personas se gustan tanto que están dispuestas a pasar el resto de sus vidas juntas, ¿verdad?",
  ui_story_5045_50450401_28_dialog_content = "Debo decir que tu comprensión del mundo realmente me impresiona a veces, PlayerName!",
  ui_story_5045_50450401_29_dialog_content = "Solo estoy suponiendo, de verdad...",
  ui_story_5045_50450401_30_option_content = "Realmente no...",
  ui_story_5045_50450401_31_dialog_content = "¡Pero he leído sobre el amor en muchas historias!",
  ui_story_5045_50450401_32_dialog_content = "A juzgar por sus descripciones, el amor es algo realmente misterioso.",
  ui_story_5045_50450401_33_dialog_content = "Así que eres fan de las historias de amor, PlayerName? Parece que le estoy preguntando a la persona adecuada.",
  ui_story_5045_50450401_34_dialog_content = "No diría que soy un fan ni nada...",
  ui_story_5045_50450401_35_option_content = "¡No lo diré!",
  ui_story_5045_50450401_36_dialog_content = "¡Es un secreto, y no lo diré!",
  ui_story_5045_50450401_37_dialog_content = "Q-Qué misterioso de tu parte...",
  ui_story_5045_50450401_38_dialog_content = "Eres bastante popular, ¿verdad? Leyn?",
  ui_story_5045_50450401_39_dialog_content = "Probablemente sepas más sobre el amor que yo, ¿verdad?",
  ui_story_5045_50450401_40_dialog_content = "Bueno...",
  ui_story_5045_50450401_41_dialog_content = "Supongo que es cierto que he sido objeto del afecto de no pocas damas.",
  ui_story_5045_50450401_42_dialog_content = "Pero desafortunadamente, nunca he sido capaz de devolver sus sentimientos.",
  ui_story_5045_50450401_43_dialog_content = "¿Eh? ¿Por qué eso?",
  ui_story_5045_50450401_44_dialog_content = "No sé. Realmente nunca lo he pensado mucho, para ser honesto.",
  ui_story_5045_50450401_45_dialog_content = "Pero cuando me asignaron a la División de Romance del Salón de Justicia y me encargaron ayudar a las parejas a resolver sus disputas.",
  ui_story_5045_50450401_46_dialog_content = "Fue entonces cuando me di cuenta de que no sé nada sobre el amor.",
  ui_story_5045_50450401_47_dialog_content = "Incluso comencé a dudar si alguna vez había sentido amor antes en mi vida...",
  ui_story_5045_50450401_48_dialog_content = "¿Estoy realmente en condiciones de trabajar como juez en la División de Romance?",
  ui_story_5045_50450401_49_dialog_content = "¡Por supuesto que lo eres!",
  ui_story_5045_50450401_50_dialog_content = "¿Qué te hace estar tan seguro de eso?",
  ui_story_5045_50450401_51_dialog_content = "Un juez no tiene que robar para juzgar a un ladrón, ¿verdad?",
  ui_story_5045_50450401_52_dialog_content = "¡Estoy bastante seguro de que lo mismo ocurre con la resolución de problemas de relación!",
  ui_story_5045_50450401_53_dialog_content = "Eso parece un poco exagerado...",
  ui_story_5045_50450401_54_dialog_content = "Pero en cierto modo, ¡tiene mucho sentido!",
  ui_story_5045_50450401_55_dialog_content = "Mirar estas quejas todo el día no te llevará muy lejos. ¡Lo más importante es aprender a través de la práctica!",
  ui_story_5045_50450401_56_dialog_content = "Debe probar suerte en algunos casos y desarrollar su experiencia primero. ¡El resto debería llegar lo suficientemente rápido!",
  ui_story_5045_50450401_57_dialog_content = "Tienes razón... ¡No puedo creer que haya estado tan indeciso últimamente!",
  ui_story_5045_50450401_58_dialog_content = "¡Debería comenzar con el primer caso frente a mí!",
  ui_story_5045_50450401_59_dialog_content = "\"El demandante, <color=#1875ad>Farrell</color>, exige que el acusado, <color=#1875ad>Sophie</color>, cásate con él de acuerdo con la ley...\"",
  ui_story_5045_50450401_60_dialog_content = "E-Esto es algún tipo de solicitud... ¿Tal vez deberías empezar con algo un poco menos complicado?",
  ui_story_5045_50450401_61_dialog_content = "No hay necesidad.",
  ui_story_5045_50450401_62_dialog_content = "Como juez, es mi responsabilidad abordar cada uno de estos casos lo mejor que pueda.",
  ui_story_5045_50450401_63_dialog_content = "No solo eso...",
  ui_story_5045_50450401_64_dialog_content = "Me doy cuenta de que es un desperdicio de su talento pedirle que me ayude a organizar la denuncia.",
  ui_story_5045_50450401_65_dialog_content = "A partir de mañana, tú y yo escucharemos juntos cada uno de estos casos.",
  ui_story_5045_50450401_66_dialog_content = "¿E-Eh? ¿Está usted seguro de eso?",
  ui_story_5045_50450401_67_dialog_content = "Por supuesto. Tú mismo lo dijiste: somos socios, ¿verdad?",
  ui_story_5045_50450501_1_dialog_content = "<color=#737378>Hora: 9:00 a.m.</color>",
  ui_story_5045_50450501_2_dialog_content = "<color=#737378>Ubicación: Salón de Justicia Lumo, Sala del Tribunal</color>",
  ui_story_5045_50450501_3_dialog_content = "¡Mira allá! Es Leyn!",
  ui_story_5045_50450501_4_dialog_content = "...",
  ui_story_5045_50450501_5_dialog_content = "(Parece que muchas damas en la audiencia vinieron solo para ver Leyn?)",
  ui_story_5045_50450501_6_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450501_7_dialog_content = "<size=45>Noche Blanca en lo alto. ¡La corte está ahora en sesión!</size>",
  ui_story_5045_50450501_8_dialog_content = "¡Noche Blanca en lo alto!",
  ui_story_5045_50450501_9_dialog_content = "...",
  ui_story_5045_50450501_10_dialog_content = "¿Sabe a quién debe dirigirse primero el tribunal, PlayerName?",
  ui_story_5045_50450501_11_dialog_content = "Hmm... Estoy bastante seguro de que se supone que es el demandante...",
  ui_story_5045_50450501_12_option_content = "Farrell",
  ui_story_5045_50450501_13_dialog_content = "¡Así es! ¡Me alegra ver que te acuerdas!",
  ui_story_5045_50450501_14_option_content = "Sophie",
  ui_story_5045_50450501_15_dialog_content = "El demandante es Farrell.",
  ui_story_5045_50450501_16_dialog_content = "Diferenciar entre el demandante y el demandado es una de las partes más básicas del trabajo. Deberías recordar eso en el futuro.",
  ui_story_5045_50450501_17_dialog_content = "(Hombre... ¿Cómo me equivoqué en eso?)",
  ui_story_5045_50450501_18_dialog_content = "(¡Tengo que asegurarme de tomar mejores notas sobre todo la próxima vez!)",
  ui_story_5045_50450501_19_dialog_content = "¿Puede el demandante dirigirse al tribunal?",
  ui_story_5045_50450501_20_dialog_content = "Buen día, Su Señoría. Mi nombre es Farrell.",
  ui_story_5045_50450501_21_dialog_content = "El demandante es un <color=#1875ad>caballero</color> de Lumopolis, ¿eh? Eso es inesperado...",
  ui_story_5045_50450501_22_dialog_content = "Cuidadoso, PlayerName. Como jueces, no podemos permitir que nociones preconcebidas de ningún tipo afecten nuestro juicio.",
  ui_story_5045_50450501_23_dialog_content = "E-Está bien...",
  ui_story_5045_50450501_24_dialog_content = "Farrell, por favor díganos por qué vino al Salón de Justicia hoy.",
  ui_story_5045_50450501_25_dialog_content = "¡Porque el acusado y yo teníamos un acuerdo!",
  ui_story_5045_50450501_26_dialog_content = "Por favor, detalle este acuerdo entre ustedes dos.",
  ui_story_5045_50450501_27_dialog_content = "Nuestro acuerdo fue que nos casaríamos tan pronto como nuestro <color=#1875ad>los recursos financieros eran iguales</color>!",
  ui_story_5045_50450501_28_dialog_content = "Pero eso es normal, ¿no? La gente siempre firma acuerdos de compromiso como ese para proteger sus bienes.",
  ui_story_5045_50450501_29_dialog_content = "Esta tal Sophie no parece particularmente acomodada. Lo más probable es que intentara aprovecharse de la posición económica del caballero.",
  ui_story_5045_50450501_30_dialog_content = "¿Creen honestamente que tales disputas insignificantes son dignas de hacerle perder el tiempo al juez Leyn?",
  ui_story_5045_50450501_31_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450501_32_dialog_content = "¡Silencio! ¡Orden en la corte!",
  ui_story_5045_50450501_33_dialog_content = "Farrell, ¿puedo preguntar si hubo testigos de este acuerdo? ¿O tal vez una prueba de algún tipo?",
  ui_story_5045_50450501_34_dialog_content = "S-Sí, Su Señoría.",
  ui_story_5045_50450501_35_dialog_content = "Aquí está el <color=#1875ad>contrato</color> firmamos. Descubrirá que se hizo de acuerdo con las regulaciones de Lumopolis.",
  ui_story_5045_50450501_36_dialog_content = "Hmm... El contrato parece estar en perfecto orden.",
  ui_story_5045_50450501_37_dialog_content = "¿Podría por favor dar a conocer sus demandas a la corte?",
  ui_story_5045_50450501_38_dialog_content = "¡Dado que nuestras finanzas ahora son iguales, pido que la corte haga cumplir nuestro acuerdo de casarnos!",
  ui_story_5045_50450501_39_dialog_content = "Lo siento, ¿escuché eso correctamente?",
  ui_story_5045_50450501_40_dialog_content = "¿Cómo podrían las finanzas de un plebeyo igualar las de un caballero?",
  ui_story_5045_50450501_41_dialog_content = "El acusado claramente lo estafó con su dinero.",
  ui_story_5045_50450501_42_dialog_content = "Sophie.",
  ui_story_5045_50450501_43_dialog_content = "¡Sí, su señoría!",
  ui_story_5045_50450501_44_dialog_content = "¿Tiene algo que decir sobre este contrato?",
  ui_story_5045_50450501_45_dialog_content = "Lo hago, Su Señoría. Es cierto que firmé ese acuerdo.",
  ui_story_5045_50450501_46_dialog_content = "Pero cuando conocí a Farrell, todavía era joven e inexperto en los caminos del mundo... No tenía idea de lo que significaba el amor en ese momento.",
  ui_story_5045_50450501_47_dialog_content = "En ese entonces, Farrell me cortejó con dulces palabras y grandes promesas. Me hizo creer verdaderamente que él era mi alma gemela.",
  ui_story_5045_50450501_48_dialog_content = "Estaba abrumado por su falso afecto, por eso firmé ese contrato.",
  ui_story_5045_50450501_49_dialog_content = "Pero con el paso del tiempo, me di cuenta de que no estábamos destinados a estar juntos. Incluso sugerí que nos fuéramos por caminos separados en más de una ocasión.",
  ui_story_5045_50450501_50_dialog_content = "Por esta razón, acato nuestro acuerdo de casarnos.",
  ui_story_5045_50450501_51_dialog_content = "En otras palabras, se niega a cumplir con el contenido de este acuerdo firmado. ¿Es eso correcto?",
  ui_story_5045_50450501_52_dialog_content = "Sí, Su Señoría. Preferiría pasar el resto de mi vida en prisión que pasarla con alguien a quien no amo.",
  ui_story_5045_50450501_53_dialog_content = "N-No digas cosas así, Sophie...",
  ui_story_5045_50450501_54_dialog_content = "¡Sabes que romper nuestro compromiso solo dañaría mi reputación como caballero!",
  ui_story_5045_50450501_55_dialog_content = "¡¿Cómo puedes seguir tan ciego a mi amor por ti?!",
  ui_story_5045_50450501_56_dialog_content = "No puedo soportar más tu amor, Farrell...",
  ui_story_5045_50450501_57_dialog_content = "¡No has hecho nada más que vigilar todos mis movimientos y acosarme a cada paso!",
  ui_story_5045_50450501_58_dialog_content = "¡Solo lo hago para protegerte, Sophie!",
  ui_story_5045_50450501_59_dialog_content = "Bueno, lo siento, pero no necesito la protección de nadie.",
  ui_story_5045_50450501_60_dialog_content = "Que antiestético...",
  ui_story_5045_50450501_61_dialog_content = "No tengo la menor idea de lo que están hablando...",
  ui_story_5045_50450501_62_dialog_content = "(¿Y ahora están discutiendo? Parece que los demás también están empezando a chismear entre ellos).",
  ui_story_5045_50450501_63_dialog_content = "(A juzgar por el suspiro de Leyn hace un momento, parece que todo esto le está haciendo doler la cabeza...)",
  ui_story_5045_50450501_64_dialog_content = "¿Ves por qué nadie quiere unirse a la División Romance ahora, PlayerName?",
  ui_story_5045_50450501_65_dialog_content = "Cuando se trata de casos como este, rara vez existen leyes o precedentes en los que confiar.",
  ui_story_5045_50450501_66_dialog_content = "Ambas partes tienen argumentos perfectamente razonables, lo que dificulta que un juez emita un veredicto justo e imparcial.",
  ui_story_5045_50450501_67_dialog_content = "Pero está bien, porque me sirve como una especie de entrenamiento. ¡Juro que defenderé la justicia hasta el final!",
  ui_story_5045_50450501_68_dialog_content = "Ahora bien, ¿tiene alguna idea para compartir sobre este caso?",
  ui_story_5045_50450501_69_dialog_content = "Ahora mismo no, no...",
  ui_story_5045_50450501_70_dialog_content = "¡E-Espera, lo tengo!",
  ui_story_5045_50450501_71_dialog_content = "Creo que deberíamos echar un vistazo más de cerca a las cosas.",
  ui_story_5045_50450501_72_dialog_content = "Bien...",
  ui_story_5045_50450501_73_dialog_content = "Mira esto, Leyn...",
  ui_story_5045_50450501_74_dialog_content = "Bueno, ¿mirarías eso? tengo que decir, viendo eso <color=#1875ad>computadora portátil</color> realmente me trae recuerdos.",
  ui_story_5045_50450501_75_dialog_content = "Cuando era juez de prueba, lo llevaba conmigo todos los días.",
  ui_story_5045_50450501_76_dialog_content = "Sin embargo, no creo que este sea un buen momento para compartir historias.",
  ui_story_5045_50450501_77_dialog_content = "¿Por qué no nos centramos en el caso que nos ocupa?",
  ui_story_5045_50450501_78_dialog_content = "Bueno...",
  ui_story_5045_50450501_79_dialog_content = "Tal vez deberíamos empezar con eso <color=#1875ad>contrato</color>?",
  ui_story_5045_50450501_80_dialog_content = "Una sabia elección.",
  ui_story_5045_50450501_81_dialog_content = "Puede que nunca entendamos los sentimientos entre las dos partes.",
  ui_story_5045_50450501_82_dialog_content = "¡Pero un acuerdo escrito está sujeto a la protección total de la ley de Lumopolis!",
  ui_story_5045_50450501_83_dialog_content = "Gracias por tu sugerencia. Creo que ya tengo mi respuesta.",
  ui_story_5045_50450501_84_dialog_content = "¿Qué respuesta sería esa?",
  ui_story_5045_50450501_85_dialog_content = "Lo sabrás muy pronto.",
  ui_story_5045_50450501_86_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450501_87_dialog_content = "Noche Blanca en lo alto. ¡Es hora del veredicto!",
  ui_story_5045_50450501_88_dialog_content = "Ambas partes eran mayores de edad a la firma de este contrato y deben asumir la responsabilidad de sus decisiones.",
  ui_story_5045_50450501_89_dialog_content = "De acuerdo con las leyes pertinentes de Lumopolis...",
  ui_story_5045_50450501_90_dialog_content = "Por la presente, el tribunal ordena a la acusada, Sophie, que respete las condiciones del acuerdo y se case con la demandante, Farrell.",
  ui_story_5045_50450501_91_dialog_content = "Si no acepta esta sentencia, podrá recurrir de conformidad con lo dispuesto por la Sala de Justicia.",
  ui_story_5045_50450501_92_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450501_93_dialog_content = "¡El juicio ha terminado!",
  ui_story_5045_50450501_94_dialog_content = "¿No deberíamos preguntarle a Sophie si Farrell ha roto alguna parte de su acuerdo?",
  ui_story_5045_50450501_95_dialog_content = "Creo que acaba de tocar un aspecto crucial de este caso, PlayerName!",
  ui_story_5045_50450501_96_dialog_content = "Sophie, afirmas que el demandante ha estado monitoreando tus movimientos, además de acosarte. ¿Es eso correcto?",
  ui_story_5045_50450501_97_dialog_content = "¡Absolutamente!",
  ui_story_5045_50450501_98_dialog_content = "Farrell a menudo se aprovecha de su condición de caballero para merodear fuera de mi casa.",
  ui_story_5045_50450501_99_dialog_content = "A pesar de haberlo rechazado claramente varias veces, se niega a dejarme en paz, ¡e incluso me ha llevado a juicio por eso!",
  ui_story_5045_50450501_100_dialog_content = "Señoría, a pesar de que mi familia carece tanto de estatus como de riqueza.",
  ui_story_5045_50450501_101_dialog_content = "¡Eso no significa que pueda ser explotado por otros!",
  ui_story_5045_50450501_102_dialog_content = "¡Tengo derecho a amar o rechazar a quien yo elija, al igual que cualquier otra persona!",
  ui_story_5045_50450501_103_dialog_content = "¿No es por eso que se estableció la División de Romance del Salón de Justicia? ¿Para proteger estos mismos derechos?",
  ui_story_5045_50450501_104_dialog_content = "(¡El acusado hace un punto extremadamente válido!)",
  ui_story_5045_50450501_105_dialog_content = "(Cuando lo piensas, ese caballero la estaba forzando).",
  ui_story_5045_50450501_106_dialog_content = "Debo decir, Sophie, que tu comprensión del amor es única. He aprendido mucho escuchándote.",
  ui_story_5045_50450501_107_dialog_content = "¡Tienes toda la razón! ¡La División de Romance del Salón de Justicia tiene el deber de defender el amor en toda la extensión de la ley!",
  ui_story_5045_50450501_108_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450501_109_dialog_content = "Noche Blanca en lo alto. ¡Es hora del veredicto!",
  ui_story_5045_50450501_110_dialog_content = "El contrato firmado entre las dos partes es perfectamente válido.",
  ui_story_5045_50450501_111_dialog_content = "Sin embargo, el comportamiento del demandante ha hecho que el demandado no esté dispuesto a casarse con él, violando así las condiciones de su acuerdo.",
  ui_story_5045_50450501_112_dialog_content = "El tribunal no tiene más remedio que imponer una multa de 100 Nightium al demandado, que debe pagarse en su totalidad dentro del período de tiempo asignado.",
  ui_story_5045_50450501_113_dialog_content = "Después de recibir la sanción por incumplimiento de contrato, el demandante ya no acosará a la demandada, Sophie.",
  ui_story_5045_50450501_114_dialog_content = "Si no acepta esta sentencia, podrá recurrir de conformidad con lo dispuesto por la Sala de Justicia.",
  ui_story_5045_50450501_115_dialog_content = "¡El descaro de ese plebeyo! ¡Cómo se atreve a empañar el honor de un caballero!",
  ui_story_5045_50450501_116_dialog_content = "Independientemente, esta es la decisión del juez Leyn, lo que la hace justa y justa.",
  ui_story_5045_50450501_117_dialog_content = "Juez Leyn! ¡También tienes el deber de proteger nuestro derecho a amar!",
  ui_story_5045_50450501_118_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450501_119_dialog_content = "¡El juicio ha terminado!",
  ui_story_5045_50450601_1_dialog_content = "<color=#737378>Hora: 12:00 p. m.</color>",
  ui_story_5045_50450601_2_dialog_content = "<color=#737378>Ubicación: Sala principal de la Sala de Justicia de Lumo</color>",
  ui_story_5045_50450601_3_dialog_content = "¡Sophie! ¡Esperar!",
  ui_story_5045_50450601_4_dialog_content = "Por favor mantente alejado de mi.",
  ui_story_5045_50450601_5_dialog_content = "Sabía que no estarías dispuesto a casarte conmigo, incluso si hubiera ganado en la corte hoy.",
  ui_story_5045_50450601_6_dialog_content = "¡Pero por favor, solo danos la oportunidad de hablar sobre las cosas!",
  ui_story_5045_50450601_7_dialog_content = "Guárdalo en la corte.",
  ui_story_5045_50450601_8_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50450601_9_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50450601_10_dialog_content = "¿Eh? ¿Por qué sigues revisando ese acuerdo? Leyn?",
  ui_story_5045_50450601_11_dialog_content = "Dime... ¿Crees que tomé la decisión correcta en el caso de hoy?",
  ui_story_5045_50450601_12_dialog_content = "Bueno, realmente no sé mucho acerca de sus leyes y reglamentos.",
  ui_story_5045_50450601_13_dialog_content = "Lo sé. Cuando te pedí que me ayudaras, mi única expectativa era que me recordaras que debía emitir un juicio justo a toda costa.",
  ui_story_5045_50450601_14_dialog_content = "Por eso te pido que compartas tus pensamientos conmigo, si es posible.",
  ui_story_5045_50450601_15_dialog_content = "Creo que tu veredicto fue...",
  ui_story_5045_50450601_16_option_content = "Una justa.",
  ui_story_5045_50450601_17_dialog_content = "Gracias por la tranquilidad, pero no puedo evitar sentir que algo anda mal.",
  ui_story_5045_50450601_18_dialog_content = "Los casos de la División de Romance nunca son tan simples.",
  ui_story_5045_50450601_19_option_content = "Un poco duro.",
  ui_story_5045_50450601_20_dialog_content = "La ley puede tener un efecto vinculante en cosas como los contratos, pero definitivamente no puede decirle a la gente cómo debe sentirse.",
  ui_story_5045_50450601_21_dialog_content = "Incluso si Sophie termina casándose con Farrell, no puedo imaginar que su vida sea feliz.",
  ui_story_5045_50450601_22_dialog_content = "¡Ay! Lo siento, Leyn! No estaba tratando de desafiar tu veredicto ni nada...",
  ui_story_5045_50450601_23_dialog_content = "No hay razón para disculparse. En todo caso, debería agradecerle su disposición a guiarme en casos como este.",
  ui_story_5045_50450601_24_option_content = "Realmente no tengo una opinión.",
  ui_story_5045_50450601_25_dialog_content = "¿A qué te refieres con eso?",
  ui_story_5045_50450601_26_dialog_content = "No tener una opinión sobre algo es la peor opinión que se puede tener.",
  ui_story_5045_50450601_27_dialog_content = "Suspiro, por otra parte, no debería seguir depositando todas mis esperanzas en ti. Lo siento.",
  ui_story_5045_50450601_28_dialog_content = "(Leyn parece bastante decepcionado de mí...)",
  ui_story_5045_50450601_29_dialog_content = "(¿Tal vez debería decirle lo que realmente pienso sobre su veredicto?)",
  ui_story_5045_50450601_30_dialog_content = "Parece que tendremos que esforzarnos aún más en este caso.",
  ui_story_5045_50450601_31_dialog_content = "Vamos.",
  ui_story_5045_50450601_32_dialog_content = "¿Eh? ¿A donde?",
  ui_story_5045_50450601_33_dialog_content = "Sophie presentó una apelación.",
  ui_story_5045_50450601_34_dialog_content = "Ella dijo que tenía más evidencia para proporcionar su caso.",
  ui_story_5045_50450601_35_dialog_content = "<color=#737378>Hora: 15:00</color>",
  ui_story_5045_50450601_36_dialog_content = "<color=#737378>Ubicación: Bajo Lumopolis</color>",
  ui_story_5045_50450601_37_dialog_content = "Buenas tardes. Perdón, ¿pero la casa de Sophie está cerca?",
  ui_story_5045_50450601_38_dialog_content = "Lo siento, pero ¿quién eres tú otra vez?",
  ui_story_5045_50450601_39_dialog_content = "(Esta persona parece un poco familiar...)",
  ui_story_5045_50450601_40_dialog_content = "Estamos, eh...",
  ui_story_5045_50450601_41_dialog_content = "Oh, no, PlayerName! ¿Tiene algo que mostrarle que pruebe nuestra <color=#1875ad>identidad</color>?",
  ui_story_5045_50450601_42_dialog_content = "¿Con esto bastará?",
  ui_story_5045_50450601_43_dialog_content = "No creo que eso sirva de mucho para probar quiénes somos.",
  ui_story_5045_50450601_44_dialog_content = "Oh, ¿en serio? En ese caso...",
  ui_story_5045_50450601_45_dialog_content = "Somos jueces del Salón de Justicia de Lumopolis.",
  ui_story_5045_50450601_46_dialog_content = "Estamos aquí por invitación de Sophie. Ella dijo que tenía más información para proporcionar su caso.",
  ui_story_5045_50450601_47_dialog_content = "¡N-no tenía idea de que estaba en presencia de dos jueces! ¡Por favor, tienes que ayudar a nuestra pobre y pequeña Sophie!",
  ui_story_5045_50450601_48_dialog_content = "¿Usted la conoce?",
  ui_story_5045_50450601_49_dialog_content = "¡Sí, señor! Mi nombre es <color=#1875ad>Carlos</color>. Soy uno de sus vecinos.",
  ui_story_5045_50450601_50_dialog_content = "No es ningún secreto que un caballero llamado Farrell la ha estado acosando desde hace algún tiempo. Ella es positivamente miserable por eso.",
  ui_story_5045_50450601_51_dialog_content = "Por eso, como sus vecinos, nos hemos encargado de ahuyentar a cualquier visitante sospechoso.",
  ui_story_5045_50450601_52_dialog_content = "Veo. Eso explica por qué querías una prueba de quiénes somos.",
  ui_story_5045_50450601_53_dialog_content = "Dijiste que Farrell ha estado acosando a Sophie durante mucho tiempo, ¿no?",
  ui_story_5045_50450601_54_dialog_content = "Sé que es impropio de mi parte decir esto sobre un caballero.",
  ui_story_5045_50450601_55_dialog_content = "Pero el hombre prácticamente ha estado vigilando su casa todos los días.",
  ui_story_5045_50450601_56_dialog_content = "Incluso después de que Sophie aclara que no quiere tener nada que ver con él, Farrell se niega a aceptarlo.",
  ui_story_5045_50450601_57_dialog_content = "Por cómo van las cosas, no puedo evitar temer por su seguridad, ¿sabes?",
  ui_story_5045_50450601_58_dialog_content = "¿Parece que la acusación de Sophie durante el juicio era cierta después de todo?",
  ui_story_5045_50450601_59_dialog_content = "¿Significa eso que mi veredicto fue...",
  ui_story_5045_50450601_60_dialog_content = "La casa de Sophie está más adelante. Déjame mostrarte el camino.",
  ui_story_5045_50450601_61_dialog_content = "<color=#737378>Hora: 15:20</color>",
  ui_story_5045_50450601_62_dialog_content = "<color=#737378>Ubicación: Bajo Lumopolis, Hogar de Sophie</color>",
  ui_story_5045_50450601_63_dialog_content = "Por favor, perdóneme, Su Señoría. Estoy seguro de que mi humilde hogar les parece ridículo a jueces como ustedes.",
  ui_story_5045_50450601_64_dialog_content = "No soñaríamos con eso, Sophie. Su hogar es muy cálido y acogedor, otra cosa que podría aprender de usted.",
  ui_story_5045_50450601_65_dialog_content = "Uno de tus vecinos nos dijo que Farrell te ha estado acosando todos los días. ¿Es eso cierto?",
  ui_story_5045_50450601_66_dialog_content = "Suspiro.",
  ui_story_5045_50450601_67_dialog_content = "Al principio, solo me seguía y merodeaba fuera de mi casa.",
  ui_story_5045_50450601_68_dialog_content = "Pero solo <color=#1875ad>esta mañana</color>, noté un conjunto extraño de <color=#1875ad>huellas</color> en mi casa. Estoy empezando a asustarme mucho...",
  ui_story_5045_50450601_69_dialog_content = "¿Te refieres a estas huellas aquí? Se ven un poco raros.",
  ui_story_5045_50450601_70_dialog_content = "Parece que quienquiera que los dejó realmente quería que los vieras. Incluso pisaron un papel y lo dejaron tirado en el suelo.",
  ui_story_5045_50450601_71_dialog_content = "Las marcas de los talones de estas huellas son especialmente claras. El estampado se parece mucho a los que dejan las botas que suelen llevar los caballeros.",
  ui_story_5045_50450601_72_dialog_content = "Las huellas parecen empezar cerca de la ventana...",
  ui_story_5045_50450601_73_dialog_content = "¿Es posible que Farrell se haya colado mientras Sophie no miraba?",
  ui_story_5045_50450601_74_dialog_content = "No puedo decir con seguridad. ¿Falta alguna de tus pertenencias, Sophie?",
  ui_story_5045_50450601_75_dialog_content = "Ninguno en absoluto. ¡Que es lo que hace que las cosas sean aún más aterradoras!",
  ui_story_5045_50450601_76_dialog_content = "Farrell debe estar tratando de intimidarme... y está funcionando. Oh, ¿qué se supone que debo hacer?",
  ui_story_5045_50450601_77_dialog_content = "Si tan solo te hubiera pedido más información durante el juicio.",
  ui_story_5045_50450601_78_dialog_content = "No lo culpo en absoluto, Su Señoría.",
  ui_story_5045_50450601_79_dialog_content = "No se puede negar que infringí la ley al romper mi contrato con Farrell. Así que, por favor, ¡envíame a prisión!",
  ui_story_5045_50450601_80_dialog_content = "Por lo menos, no tendría que casarme con un acosador manipulador allí...",
  ui_story_5045_50450601_81_dialog_content = "Tranquilízate, Sophie.",
  ui_story_5045_50450601_82_dialog_content = "Ahora que tenemos motivos más que suficientes para sospechar que Farrell cometió un delito, volveremos a examinar el caso de hoy con la debida diligencia.",
  ui_story_5045_50450601_83_dialog_content = "¿Te parece bien que echemos un vistazo, Sophie?",
  ui_story_5045_50450601_84_dialog_content = "Por todos los medios, solo espero que no te importe el lío...",
  ui_story_5045_50450601_85_dialog_content = "Ejem, creo que investigar la casa de Sophie le causaría una incomodidad innecesaria, ¿no crees?",
  ui_story_5045_50450601_86_dialog_content = "¡Lo siento! Eso ni siquiera se me ocurrió... Eres bastante bueno para saber cómo se sienten otras personas, Leyn!",
  ui_story_5045_50450601_87_dialog_content = "Pero aun así, llegamos hasta aquí... Farrell podría haber dejado más pistas por ahí.",
  ui_story_5045_50450601_88_dialog_content = "Si alguien pregunta, solo diles que fue idea mía, ¿de acuerdo?",
  ui_story_5045_50450601_89_dialog_content = "¿Cómo podría dejarte cargar con toda la culpa?",
  ui_story_5045_50450601_90_dialog_content = "Cuando terminemos aquí, me aseguraré de disculparme con Sophie en tu nombre.",
  ui_story_5045_50450601_91_dialog_content = "Jaja...",
  ui_story_5045_50450601_92_dialog_content = "¡Ay! ¡Lo siento, no quise escuchar a escondidas!",
  ui_story_5045_50450601_93_dialog_content = "Pero la forma en que ustedes dos siguen tratando de culparse el uno al otro. Deben ser muy buenos amigos.",
  ui_story_5045_50450601_94_dialog_content = "Por favor, investigue como mejor le parezca. Nunca podría ofenderme, cuando ustedes dos están trabajando tan duro para ayudarme.",
  ui_story_5045_50450601_95_dialog_content = "... Gracias por su comprensión.",
  ui_story_5045_50450601_96_dialog_content = "Ahora bien, ¿por dónde deberíamos empezar nuestra <color=#1875ad>investigación</color>?",
  ui_story_5045_50450601_97_dialog_content = "Déjame pensar.",
  ui_story_5045_50450601_98_option_content = "revisa los cajones",
  ui_story_5045_50450601_99_dialog_content = "Hay un montón de letras de aspecto elegante aquí.",
  ui_story_5045_50450601_100_dialog_content = "Esas no son cartas ordinarias.",
  ui_story_5045_50450601_101_dialog_content = "¿Qué te hace decir eso?",
  ui_story_5045_50450601_102_dialog_content = "Porque tengo un montón de ellos yo mismo...",
  ui_story_5045_50450601_103_dialog_content = "¿Tú también? Espera... ¡Lo entiendo ahora! Estas son cartas de amor, ¿no?",
  ui_story_5045_50450601_104_dialog_content = "Sin embargo, la letra y la firma de cada uno son diferentes.",
  ui_story_5045_50450601_105_dialog_content = "Parece que Sophie también es bastante popular. Pero no tenemos por qué leer sus cartas privadas.",
  ui_story_5045_50450601_106_dialog_content = "Intentemos buscar en otro lugar.",
  ui_story_5045_50450601_106X1_dialog_content = "¿Dónde más debería investigar?",
  ui_story_5045_50450601_107_option_content = "revisa el suelo",
  ui_story_5045_50450601_108_dialog_content = "No veo ninguna otra huella aparte de las que están cerca de la ventana.",
  ui_story_5045_50450601_109_dialog_content = "Espera, ¿qué es esto?",
  ui_story_5045_50450601_110_dialog_content = "es una tarjeta? Parece una especie de <color=#1875ad>tarjeta de asistencia</color>.",
  ui_story_5045_50450601_111_dialog_content = "Oh sí. Empecé a tomar algunas lecciones de limpieza recientemente.",
  ui_story_5045_50450601_112_dialog_content = "Esa es mi tarjeta de asistencia al curso.",
  ui_story_5045_50450601_113_dialog_content = "Con la muerte de mis padres, no tengo forma de reconstruir nuestro negocio familiar. ¡Pero eso no significa que quiera quedarme de brazos cruzados y no hacer nada al respecto!",
  ui_story_5045_50450601_114_dialog_content = "Quiero trabajar duro y confiar en mis propias habilidades para ganarme la vida.",
  ui_story_5045_50450601_115_dialog_content = "Yo... ¡Estoy seguro de que tendrás éxito!",
  ui_story_5045_50450601_116_option_content = "Envuélvelo",
  ui_story_5045_50450601_117_dialog_content = "No parece haber nada más aquí, además de esas huellas.",
  ui_story_5045_50450601_118_dialog_content = "Así que no se llevó nada con él, ni dejó nada atrás.",
  ui_story_5045_50450601_119_dialog_content = "¿Qué está tramando exactamente Farrell?",
  ui_story_5045_50450601_120_dialog_content = "<color=#737378>Hora: 17:00</color>",
  ui_story_5045_50450601_121_dialog_content = "<color=#737378>Ubicación: estación de guardia de Lumopolis</color>",
  ui_story_5045_50450601_122_dialog_content = "E-Este lugar es aterrador... ¿Es aquí realmente donde trabaja Farrell?",
  ui_story_5045_50450601_123_dialog_content = "Por supuesto que es aterrador. Solo los nobles más intrépidos son dignos de trabajar aquí.",
  ui_story_5045_50450601_124_dialog_content = "B-Beverly?!",
  ui_story_5045_50450601_125_dialog_content = "Farrell está de servicio ahora mismo. Si desea verlo, tendrá que volver otro día.",
  ui_story_5045_50450601_126_dialog_content = "Perdone la intrusión, Lady Duquesa, pero estamos aquí por una investigación.",
  ui_story_5045_50450601_127_dialog_content = "Por lo que entiendo, Farrell es uno de sus colegas aquí, ¿sí?",
  ui_story_5045_50450601_128_dialog_content = "De hecho, lo es. ¿Pero pensé que su caso ya había sido resuelto?",
  ui_story_5045_50450601_129_dialog_content = "El demandado presentó una apelación, que nos obliga a volver a examinar el caso.",
  ui_story_5045_50450601_130_dialog_content = "Hmph. ¿Es eso así?",
  ui_story_5045_50450601_131_dialog_content = "Entonces harías bien en examinar las cosas con más cuidado esta vez. Desde que conoció a Sophie, Farrell se ha convertido en un hombre completamente diferente.",
  ui_story_5045_50450601_132_dialog_content = "Sigue balbuceando sobre perder su honor como caballero si no logra rescatar a su princesa.",
  ui_story_5045_50450601_133_dialog_content = "Si bien no ha presentado ninguna complicación en su trabajo, encuentro todo esto insoportablemente molesto.",
  ui_story_5045_50450601_134_dialog_content = "Un verdadero caballero debe servir al pueblo con todo su corazón. Pero me temo que ya se ha hablado por su corazón.",
  ui_story_5045_50450601_135_dialog_content = "Escuché que se mudó a estos barracones recientemente. ¿Es eso cierto?",
  ui_story_5045_50450601_136_dialog_content = "Es. No hace mucho, donó toda su riqueza y bienes a los empobrecidos de Umbraton.",
  ui_story_5045_50450601_137_dialog_content = "Ha estado viviendo aquí desde entonces.",
  ui_story_5045_50450601_138_dialog_content = "Su desinterés es algo digno de elogio, sin duda. Pero, ¿qué tiene que ver esto con su caso?",
  ui_story_5045_50450601_139_dialog_content = "¡¿A-Todos sus activos?!",
  ui_story_5045_50450601_140_dialog_content = "¿Podría por favor mostrarnos los aposentos de Farrell?",
  ui_story_5045_50450601_141_dialog_content = "Sus habitaciones están justo a la izquierda de aquí. Puede que se vean dentro.",
  ui_story_5045_50450601_142_dialog_content = "<color=#737378>Algún tiempo después</color>",
  ui_story_5045_50450601_143_dialog_content = "¿Bien? ¿Ya has encontrado algo?",
  ui_story_5045_50450601_144_dialog_content = "El tamaño y la forma de las huellas combinan perfectamente con la huella de la bota que Farrell dejó en la casa.",
  ui_story_5045_50450601_145_dialog_content = "Así que la persona que irrumpió en la casa de Sophie en realidad fue Farrell...",
  ui_story_5045_50450601_146_dialog_content = "Qué pasa contigo, PlayerName? ¿Algún descubrimiento?",
  ui_story_5045_50450601_147_dialog_content = "Aparte de esto, no veo nada particularmente fuera de lugar en su habitación.",
  ui_story_5045_50450601_148_dialog_content = "Esto es un<color=#1875ad> cometa</color>?",
  ui_story_5045_50450601_149_dialog_content = "¡Y mira, tiene escrito el nombre de Sophie!",
  ui_story_5045_50450601_150_dialog_content = "¿Significa esto que Farrell se llevó algo de su casa? ¿Por qué no nos lo contó?",
  ui_story_5045_50450601_151_dialog_content = "¿Quizás no vale mucho?",
  ui_story_5045_50450601_152_dialog_content = "Toda la evidencia que hemos reunido hasta ahora parece señalar a Farrell como la persona culpable.",
  ui_story_5045_50450601_153_dialog_content = "Si este es el caso, Farrell no solo perderá el caso. Se enfrentará a un castigo aún más severo.",
  ui_story_5045_50450601_154_dialog_content = "¿Qué tipo de castigo?",
  ui_story_5045_50450601_155_dialog_content = "Perderá su condición de caballero y se verá obligado a vivir como un plebeyo.",
  ui_story_5045_50450601_156_dialog_content = "Para la nobleza, este es uno de los peores castigos que se le puede dar a una persona de su estatus.",
  ui_story_5045_50450601_157_dialog_content = "Ya veo... Pero algo me dice que hay más en este caso de lo que nos damos cuenta.",
  ui_story_5045_50450601_158_dialog_content = "Mis pensamientos exactamente.",
  ui_story_5045_50450601_159_dialog_content = "No podemos permitirnos pasar por alto un solo detalle del juicio de mañana.",
  ui_story_5045_50450701_1_dialog_content = "<color=#737378>Hora: 9:00 a.m.</color>",
  ui_story_5045_50450701_2_dialog_content = "<color=#737378>Ubicación: Salón de Justicia Lumo, Sala del Tribunal</color>",
  ui_story_5045_50450701_3_dialog_content = "¡Guau! Leyn se ve tan guapo como siempre hoy, ¿no crees?",
  ui_story_5045_50450701_4_dialog_content = "(Parece que el club de fans de Leyn está de regreso...)",
  ui_story_5045_50450701_5_dialog_content = "Qué tienes en mente, PlayerName?",
  ui_story_5045_50450701_6_dialog_content = "Nada, solo...",
  ui_story_5045_50450701_7_option_content = "Te ves tan guapo como siempre hoy, Leyn!",
  ui_story_5045_50450701_8_dialog_content = "(Mierda, repetí las palabras de esa chica sin pensar...)",
  ui_story_5045_50450701_9_dialog_content = "A-Ejem... La corte estará en sesión pronto, así que trate de concentrarse.",
  ui_story_5045_50450701_10_option_content = "¡Recuerde hacer un juicio justo!",
  ui_story_5045_50450701_11_dialog_content = "Lo haré. Gracias por recordarme.",
  ui_story_5045_50450701_12_dialog_content = "Aprendí mi lección de la última prueba. No mostraré ninguna indecisión hoy.",
  ui_story_5045_50450701_13_option_content = "Ojalá fuera tan popular como tú...",
  ui_story_5045_50450701_14_dialog_content = "¿En realidad? Siempre pensé que tenías mayores ambiciones que esa...",
  ui_story_5045_50450701_15_dialog_content = "¡Pero ahora no es el momento para ese tipo de conversación! ¡La corte estará en sesión pronto!",
  ui_story_5045_50450701_16_dialog_content = "(Y aquí pensé Leyn se sentiría mejor si le diera un pequeño cumplido...)",
  ui_story_5045_50450701_17_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450701_18_dialog_content = "<size=45>Noche Blanca en lo alto. ¡La corte está ahora en sesión!</size>",
  ui_story_5045_50450701_19_dialog_content = "Para empezar, ¿podría la recurrente, Sophie, exponer su caso?",
  ui_story_5045_50450701_20_dialog_content = "Buen día, Su Señoría. No puedo aceptar el veredicto de primera instancia.",
  ui_story_5045_50450701_21_dialog_content = "Hago un llamamiento para rescindir el acuerdo entre Farrell y yo.",
  ui_story_5045_50450701_22_dialog_content = "Como caballero, usó su posición para acecharme y acosarme.",
  ui_story_5045_50450701_23_dialog_content = "Incluso irrumpió en mi casa. <color=#1875ad>después del primer juicio</color> y dejó sus huellas allí!",
  ui_story_5045_50450701_24_dialog_content = "¡Algo está mal con la declaración de Sophie!",
  ui_story_5045_50450701_25_dialog_content = "¿Cuál es el problema?",
  ui_story_5045_50450701_26_dialog_content = "¿Eh? ¿Ningún problema?",
  ui_story_5045_50450701_26X1_dialog_content = "¿Estás seguro de que no me escuchaste mal? Déjame decirlo una vez más...",
  ui_story_5045_50450701_27_dialog_content = "Mira esto, Leyn...",
  ui_story_5045_50450701_28_dialog_content = "Bueno, ¿mirarías eso? Tengo que decir que ver ese cuaderno realmente me trae recuerdos.",
  ui_story_5045_50450701_29_dialog_content = "Cuando era juez de prueba, lo llevaba conmigo todos los días.",
  ui_story_5045_50450701_30_dialog_content = "¿Por qué esta conversación parece tan familiar?",
  ui_story_5045_50450701_31_dialog_content = "¿Qué tratas de decir?",
  ui_story_5045_50450701_32_dialog_content = "Estoy pensando...",
  ui_story_5045_50450701_33_dialog_content = "Sophie, dijiste que encontraste estas huellas en <color=#1875ad>la mañana del primer juicio</color>?",
  ui_story_5045_50450701_34_dialog_content = "Oh... Debo haberme equivocado.",
  ui_story_5045_50450701_35_dialog_content = "Su Señoría, estaba realmente nervioso hace un momento... ¡Permítame decirlo de nuevo!",
  ui_story_5045_50450701_36_dialog_content = "En la mañana del primer juicio, encontré estas huellas en mi casa.",
  ui_story_5045_50450701_37_dialog_content = "Pero nada fue robado... ¡Sabía que debía haber sido un intento deliberado de irrumpir en mi casa y asustarme!",
  ui_story_5045_50450701_38_dialog_content = "¿No se robó nada? Pero...",
  ui_story_5045_50450701_39_dialog_content = "Creo recordar que Farrell tenía <color=#1875ad>algo que era tuyo</color>!",
  ui_story_5045_50450701_40_dialog_content = "¿Hay algo malo aquí?",
  ui_story_5045_50450701_41_dialog_content = "¡Ay, no es eso! Lo que quería decir era...",
  ui_story_5045_50450701_42_dialog_content = "Este <color=#1875ad>cometa</color> tiene la firma de Sophie. Debe ser tuyo, ¿verdad?",
  ui_story_5045_50450701_43_dialog_content = "Esto es-!",
  ui_story_5045_50450701_44_dialog_content = "¡Su Señoría, esta es una muestra de nuestro amor!",
  ui_story_5045_50450701_45_dialog_content = "En ese momento, acababa de terminar de patrullar...",
  ui_story_5045_50450701_46_dialog_content = "(Erm, ¿se va a volver a enamorar aquí mismo en el Salón de la Justicia?)",
  ui_story_5045_50450701_47_dialog_content = "Señor...",
  ui_story_5045_50450701_48_dialog_content = "Sí, ¿qué puedo hacer para ayudar?",
  ui_story_5045_50450701_49_dialog_content = "M-Mi cometa está atascada en ese árbol de allá. Sé que no debo molestarte...",
  ui_story_5045_50450701_50_dialog_content = "Pero esa cometa es muy importante para mí. Lo hizo mi padre...",
  ui_story_5045_50450701_51_dialog_content = "No es ningún problema en absoluto. Por favor, espere un momento.",
  ui_story_5045_50450701_52_dialog_content = "¡Muchas gracias! Realmente no sé qué hacer si no fuera por ti...",
  ui_story_5045_50450701_53_dialog_content = "Todo está en un día de trabajo. Por favor, no lo menciones.",
  ui_story_5045_50450701_54_dialog_content = "Erm... ¿Te gusta volar cometas?",
  ui_story_5045_50450701_55_dialog_content = "Y así, nos reuníamos de vez en cuando para volar cometas juntos, y poco a poco nos fuimos conociendo más de cerca.",
  ui_story_5045_50450701_56_dialog_content = "Fue en ese momento que mi familia quiso elegir una esposa adecuada para mí.",
  ui_story_5045_50450701_57_dialog_content = "Pero yo creo que el amor nace de la libertad, y yo no quería ser controlado por mi familia.",
  ui_story_5045_50450701_58_dialog_content = "Así que le di la espalda a mi familia y le propuse matrimonio a Sophie.",
  ui_story_5045_50450701_59_dialog_content = "Farrell, ¡nuestras cometas vuelan tan alto!",
  ui_story_5045_50450701_60_dialog_content = "No importa qué tan alto vuele una cometa, debe regresar al suelo después de que el viento cesa.",
  ui_story_5045_50450701_61_dialog_content = "No importa cuán lejos viajemos en el ancho mundo, finalmente debemos regresar a una familia cálida y amorosa.",
  ui_story_5045_50450701_62_dialog_content = "No estoy seguro de entender.",
  ui_story_5045_50450701_63_dialog_content = "Sophie, ¿te gustaría construir una familia feliz conmigo?",
  ui_story_5045_50450701_64_dialog_content = "Yo... aprecio tus amables sentimientos.",
  ui_story_5045_50450701_65_dialog_content = "Pero, ¿su familia aceptará a alguien en una posición tan baja como la mía?",
  ui_story_5045_50450701_66_dialog_content = "Sofía, no te preocupes. Haré que te acepten.",
  ui_story_5045_50450701_67_dialog_content = "Si te peleas con tu familia por mi culpa, no podré perdonarme...",
  ui_story_5045_50450701_68_dialog_content = "Prometo casarme contigo, pero espera hasta que llegue el momento.",
  ui_story_5045_50450701_69_dialog_content = "Quiero restaurar el honor de mi familia...",
  ui_story_5045_50450701_70_dialog_content = "Su familia puede aceptarme una vez que recupere la propiedad de mi familia.",
  ui_story_5045_50450701_71_dialog_content = "¡Es por eso que firmaste el acuerdo de compromiso!",
  ui_story_5045_50450701_72_dialog_content = "¡Objeción! Estos eventos pasados no tienen nada que ver con el caso de hoy.",
  ui_story_5045_50450701_73_dialog_content = "Aunque es un poco vergonzoso, tener que soportar la historia de amor de otra persona...",
  ui_story_5045_50450701_74_dialog_content = "¡Te aseguro que todo esto está relacionado con el caso!",
  ui_story_5045_50450701_75_dialog_content = "¡Anulado!",
  ui_story_5045_50450701_76_dialog_content = "Señoría, admito que teníamos una buena relación, pero eso ya terminó.",
  ui_story_5045_50450701_77_dialog_content = "Rompí con él hace mucho tiempo.",
  ui_story_5045_50450701_78_dialog_content = "Tenemos la libertad de amar y la libertad de no amar.",
  ui_story_5045_50450701_79_dialog_content = "¡No puedes obligar a alguien a renunciar a la felicidad de su vida por lo que dice en un papel!",
  ui_story_5045_50450701_80_dialog_content = "Sí, lo que dice el recurrente es bastante razonable.",
  ui_story_5045_50450701_81_dialog_content = "Pero después de que rompimos, Farrell todavía me acosaba y a menudo me seguía...",
  ui_story_5045_50450701_82_dialog_content = "¡Incluso irrumpió en mi casa!",
  ui_story_5045_50450701_83_dialog_content = "Hmm... ¿Por qué Sophie está tan segura de que esas huellas son de Farrell?",
  ui_story_5045_50450701_84_dialog_content = "Es porque Farrell acosó a Sophie que ella inconscientemente cree que son suyos, ¿verdad?",
  ui_story_5045_50450701_85_dialog_content = "Pero esto es sólo una conjetura. Preguntemos al cliente.",
  ui_story_5045_50450701_86_dialog_content = "Farrell, ¿admites la acusación de Sophie?",
  ui_story_5045_50450701_87_dialog_content = "Yo...",
  ui_story_5045_50450701_88_dialog_content = "Admito que a veces buscaba a Sophie después de mi patrulla, pero solo quería pedirle que me diera otra oportunidad.",
  ui_story_5045_50450701_89_dialog_content = "Noche Blanca en lo alto. Juro por mi honor como caballero que no le hice nada malo a Sophie.",
  ui_story_5045_50450701_90_dialog_content = "Sophie, ¿alguien entró en tu habitación?",
  ui_story_5045_50450701_91_dialog_content = "Todo es mi culpa. Debería haber estado allí para protegerte...",
  ui_story_5045_50450701_92_dialog_content = "Parece que no admitirá que las huellas son suyas.",
  ui_story_5045_50450701_93_dialog_content = "Si hubiera alguna forma de identificar las huellas...",
  ui_story_5045_50450701_94_dialog_content = "... ¡Eso es todo! ¡Comparemos las huellas en la corte!",
  ui_story_5045_50450701_95_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450701_96_dialog_content = "Farrell, haz una huella en este papel.",
  ui_story_5045_50450701_97_dialog_content = "E-Está bien...",
  ui_story_5045_50450701_98_dialog_content = "¿Puedes ver alguna diferencia? PlayerName?",
  ui_story_5045_50450701_99_dialog_content = "Las marcas dejadas por las suelas duras y los tacones tienen aproximadamente la misma profundidad.",
  ui_story_5045_50450701_100_dialog_content = "Y hay muchas lágrimas a lo largo de los bordes de las suelas. Parece que estas botas se han usado durante muchos años.",
  ui_story_5045_50450701_101_dialog_content = "Pero el <color=#1875ad>huellas</color> encontramos ese día eran...",
  ui_story_5045_50450701_102_dialog_content = "hay algun problema con esto?",
  ui_story_5045_50450701_103_dialog_content = "¡Tos, tos, me he equivocado!",
  ui_story_5045_50450701_104_dialog_content = "Las huellas de la casa de Sophie tenían un patrón muy claro, un patrón obviamente hecho por zapatos nuevos, pero los zapatos de Farrell son viejos y andrajosos.",
  ui_story_5045_50450701_105_dialog_content = "Las dos huellas son descaradamente diferentes.",
  ui_story_5045_50450701_106_dialog_content = "¿¡Qué!?",
  ui_story_5045_50450701_107_dialog_content = "¡No! Tal vez estaba usando un par de zapatos nuevos ese día.",
  ui_story_5045_50450701_108_dialog_content = "Bueno, eso no es un imposible.",
  ui_story_5045_50450701_109_dialog_content = "Señoría, ahora solo tengo estas botas...",
  ui_story_5045_50450701_110_dialog_content = "¿Quién sabe? ¿Quizás escondiste las botas de ese día en algún lugar donde nadie las encontrará?",
  ui_story_5045_50450701_111_dialog_content = "No... ¡La persona que irrumpió en la casa de Sophie no fue Farrell!",
  ui_story_5045_50450701_112_dialog_content = "Y lo que te lleva tan firmemente a esa conclusión, PlayerName?",
  ui_story_5045_50450701_113_dialog_content = "Las huellas encontradas en la casa de Sophie... Las huellas dejadas por el talón son muy distintas.",
  ui_story_5045_50450701_114_dialog_content = "Tales huellas solo ocurren cuando usa zapatos que son mucho más grandes que sus propios pies.",
  ui_story_5045_50450701_115_dialog_content = "Por lo tanto, las huellas en la casa de Sophie no podrían haber pertenecido a Farrell.",
  ui_story_5045_50450701_116_dialog_content = "¡Tus poderes de observación son inquietantemente astutos!",
  ui_story_5045_50450701_117_dialog_content = "Entonces, ¿quién usaría deliberadamente botas más grandes que sus propios pies para dejar huellas en la casa de Sophie?",
  ui_story_5045_50450701_118_dialog_content = "Bueno...",
  ui_story_5045_50450701_119_dialog_content = "Sophie, ¿hiciste tú misma esta evidencia?",
  ui_story_5045_50450701_120_dialog_content = "eh, yo...",
  ui_story_5045_50450701_121_dialog_content = "¡Noche Blanca en lo alto! ¡Este es el Salón de la Justicia, estás obligado a decir la verdad!",
  ui_story_5045_50450701_122_dialog_content = "Tenía miedo de que aún mantuvieras la sentencia original, así que tomé una decisión por mi cuenta.",
  ui_story_5045_50450701_123_dialog_content = "Cometí un error, Su Señoría, ¡pero realmente no quiero casarme con Farrell!",
  ui_story_5045_50450701_124_dialog_content = "¿Es porque Farrell no tiene ni un centavo a su nombre?",
  ui_story_5045_50450701_125_dialog_content = "...",
  ui_story_5045_50450701_126_dialog_content = "Aunque no se dijo explícitamente, su acuerdo mencionaba que si tenía suficiente dinero, se casaría.",
  ui_story_5045_50450701_127_dialog_content = "Pero ahora...",
  ui_story_5045_50450701_128_dialog_content = "<color=#1875ad>El estado de la propiedad de Farrell</color> ha sufrido un cambio significativo.",
  ui_story_5045_50450701_129_dialog_content = "¿Qué es eso?",
  ui_story_5045_50450701_130_dialog_content = "Oh, lo que realmente quería decir era...",
  ui_story_5045_50450701_131_dialog_content = "Farrell, ¿puede decirnos por qué quería regalar todas sus propiedades?",
  ui_story_5045_50450701_132_dialog_content = "E-Esta es mi responsabilidad como caballero.",
  ui_story_5045_50450701_133_dialog_content = "¿Es eso realmente cierto?",
  ui_story_5045_50450701_134_dialog_content = "¡Noche Blanca en lo alto! Farrell, debes saber que la honestidad es la cualidad más básica de cualquier caballero.",
  ui_story_5045_50450701_135_dialog_content = "Bueno...",
  ui_story_5045_50450701_136_dialog_content = "Está bien, hablaré.",
  ui_story_5045_50450701_137_dialog_content = "Lo siento, esa última inversión fue otro pato cojo...",
  ui_story_5045_50450701_138_dialog_content = "¡Pero esta vez será diferente!",
  ui_story_5045_50450701_139_dialog_content = "Farrell, ¿puedes prestarme algo más de dinero? ¡Sé que elegiré un ganador esta vez!",
  ui_story_5045_50450701_140_dialog_content = "Sofía, tengo buenas noticias.",
  ui_story_5045_50450701_141_dialog_content = "He regalado todas mis propiedades.",
  ui_story_5045_50450701_142_dialog_content = "Pero... ¿por qué harías algo así?",
  ui_story_5045_50450701_143_dialog_content = "De esta manera, seremos económicamente iguales.",
  ui_story_5045_50450701_144_dialog_content = "Podemos casarnos.",
  ui_story_5045_50450701_145_dialog_content = "Sophie lo intentó durante mucho tiempo, pero no pudo recuperar la propiedad de su familia.",
  ui_story_5045_50450701_146_dialog_content = "No quería que trabajara tan duro.",
  ui_story_5045_50450701_147_dialog_content = "El dinero y la propiedad son cosas superficiales. ¡El amor entre nosotros dos es más importante que nada en el mundo!",
  ui_story_5045_50450701_148_dialog_content = "Obviamente, Sophie no está de acuerdo contigo en eso.",
  ui_story_5045_50450701_149_dialog_content = "... Cierto, no creo que lo haga.",
  ui_story_5045_50450701_150_dialog_content = "Creo que el dinero es el requisito previo para construir una familia.",
  ui_story_5045_50450701_151_dialog_content = "Nunca pude estar de acuerdo con el enfoque de Farrell, que demuestra que somos claramente incompatibles, así que rompí con él.",
  ui_story_5045_50450701_152_dialog_content = "Hay algo malo con eso?",
  ui_story_5045_50450701_153_dialog_content = "¡Después de casarnos, podemos trabajar duro juntos y acumular lentamente nuestra propia riqueza!",
  ui_story_5045_50450701_154_dialog_content = "Pero ya no te amo.",
  ui_story_5045_50450701_155_dialog_content = "O más bien, no te amé desde el principio.",
  ui_story_5045_50450701_156_dialog_content = "¿Estás satisfecho ahora?",
  ui_story_5045_50450701_157_dialog_content = "Sophie... No... ¡No es verdad!",
  ui_story_5045_50450701_158_dialog_content = "Pobre Farrell...",
  ui_story_5045_50450701_159_dialog_content = "Leyn, ¿Cómo nos enfrentamos a esto?",
  ui_story_5045_50450701_160_dialog_content = "Siempre pensé que los casos podían juzgarse basándose únicamente en la ley.",
  ui_story_5045_50450701_161_dialog_content = "Pero las cosas son diferentes en Romance Division...",
  ui_story_5045_50450701_162_dialog_content = "Después de todo, las emociones no se pueden explicar ni comprender tan fácilmente.",
  ui_story_5045_50450701_163_dialog_content = "Si sigue así, ambos terminarán con nada más que miseria y arrepentimiento.",
  ui_story_5045_50450701_164_dialog_content = "Espero que nuestro juicio pueda protegerlos a ambos al mismo tiempo.",
  ui_story_5045_50450701_165_dialog_content = "¿Eso significa que tienes una idea?",
  ui_story_5045_50450701_166_dialog_content = "En seguida.",
  ui_story_5045_50450701_167_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450701_168_dialog_content = "Noche Blanca en lo alto. ¡Es hora del veredicto!",
  ui_story_5045_50450701_169_dialog_content = "En primer lugar, aunque el acuerdo de esponsales entre Farrell y Sophie es legal y efectivo...",
  ui_story_5045_50450701_170_dialog_content = "Sin embargo, el nuevo juicio encuentra que las diferencias entre Sophie y Farrell son irreconciliables.",
  ui_story_5045_50450701_171_dialog_content = "En segundo lugar, la acusación de Sophie contra Farrell es falsa. Específicamente, Farrell no siguió a Sophie a su casa y entró ilegalmente en su propiedad.",
  ui_story_5045_50450701_172_dialog_content = "Pero su amor nostálgico y unilateral no constituye un matrimonio.",
  ui_story_5045_50450701_173_dialog_content = "¡Por lo tanto, hemos llegado al siguiente juicio!",
  ui_story_5045_50450701_174_dialog_content = "Sophie debe ofrecerle a Farrell una disculpa pública...",
  ui_story_5045_50450701_175_dialog_content = "... aclarando los motivos de la cancelación del compromiso y las falsas acusaciones de intrusión ilegal de Farrell.",
  ui_story_5045_50450701_176_dialog_content = "Después del juicio, Farrell no debe comunicarse con Sophie en privado; la Guardia implementará su propio control interno a tal efecto.",
  ui_story_5045_50450701_177_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50450701_178_dialog_content = "¡El juicio ha terminado!",
  ui_story_5045_50450801_1_dialog_content = "<color=#737378>Hora: 12:00 p. m.</color>",
  ui_story_5045_50450801_2_dialog_content = "<color=#737378>Ubicación: Salón de Justicia Lumo, Sala del Tribunal</color>",
  ui_story_5045_50450801_3_dialog_content = "Señoría, ¿puede ayudarme a darle esto a Sophie?",
  ui_story_5045_50450801_4_dialog_content = "Pensé que Sophie y yo volveríamos a volar cometas juntos...",
  ui_story_5045_50450801_5_dialog_content = "Ahora parece que nunca sucederá... No en esta vida.",
  ui_story_5045_50450801_6_dialog_content = "Aunque estoy tentado a quedármelo como recuerdo...",
  ui_story_5045_50450801_7_dialog_content = "Lo hizo el difunto padre de Sophie, así que creo que ella podría necesitarlo más que yo.",
  ui_story_5045_50450801_8_dialog_content = "Tenga la seguridad de que se lo entregaremos a Sophie.",
  ui_story_5045_50450801_9_dialog_content = "¡Conocerás a alguien que realmente te ama algún día!",
  ui_story_5045_50450801_10_dialog_content = "Por favor, dile a Sophie que la esperaré.",
  ui_story_5045_50450801_11_dialog_content = "... Creo que te mereces un buen descanso.",
  ui_story_5045_50450801_12_dialog_content = "Suspiro...",
  ui_story_5045_50450801_13_dialog_content = "¡Sophie, por favor espera!",
  ui_story_5045_50450801_14_dialog_content = "¿Pasa algo?",
  ui_story_5045_50450801_15_dialog_content = "Farrell nos pidió que te devolviéramos esta cometa.",
  ui_story_5045_50450801_16_dialog_content = "Ya no lo necesito. Solo tíralo.",
  ui_story_5045_50450801_17_dialog_content = "¿No lo hizo tu padre?",
  ui_story_5045_50450801_18_dialog_content = "... Ese viejo hizo muchas cometas. Ya no quiero este.",
  ui_story_5045_50450801_19_dialog_content = "¿Realmente debe preocuparse por un asunto tan insignificante, Su Señoría?",
  ui_story_5045_50450801_20_dialog_content = "Bueno...",
  ui_story_5045_50450801_21_dialog_content = "Tengo una última pregunta que hacerte, Sophie.",
  ui_story_5045_50450801_22_dialog_content = "No tengo nada que decir sobre esto.",
  ui_story_5045_50450801_23_dialog_content = "¿Alguna vez has engañado a otros emocionalmente?",
  ui_story_5045_50450801_24_dialog_content = "¿Cómo puedes usar la palabra \"engañado\" para describir las relaciones que tuve con ellos?",
  ui_story_5045_50450801_25_dialog_content = "Si le pedimos a la Sala de Justicia que investigue más a fondo sus relaciones interpersonales...",
  ui_story_5045_50450801_26_dialog_content = "Es posible que descubramos que no eres tan inofensivo como pareces.",
  ui_story_5045_50450801_27_dialog_content = "... Nadie está presentando cargos en mi contra, ¡no tienes derecho a hacer eso!",
  ui_story_5045_50450801_28_dialog_content = "De hecho, nadie está presentando cargos en su contra.",
  ui_story_5045_50450801_29_dialog_content = "Porque tus objetivos son los nobles.",
  ui_story_5045_50450801_30_dialog_content = "Incluso si son engañados, no querrían que nadie más lo supiera.",
  ui_story_5045_50450801_31_dialog_content = "Esta vez, te encontraste con muchas molestias inesperadas, es decir, él fue totalmente genuino contigo.",
  ui_story_5045_50450801_32_dialog_content = "Y de alguna manera no querías decirle la verdad.",
  ui_story_5045_50450801_33_dialog_content = "Y luego, cuando Farrell literalmente renunció a todo por ti...",
  ui_story_5045_50450801_34_dialog_content = "¡Basta!",
  ui_story_5045_50450801_35_dialog_content = "Ya he perdido demasiado tiempo aquí. Lo siento, tengo que irme.",
  ui_story_5045_50450801_36_dialog_content = "Se escapó... así como así.",
  ui_story_5045_50450801_37_dialog_content = "Le prometimos a Farrell que le entregaríamos la cometa...",
  ui_story_5045_50450801_38_dialog_content = "Los casos aquí ciertamente no son exactamente claros...",
  ui_story_5045_50450801_39_dialog_content = "Aunque se ha dictado sentencia, mi alma se afana en un tormento inquieto.",
  ui_story_5045_50450801_40_dialog_content = "Sí, siento que... hay un peso indescriptible arrastrando mi corazón.",
  ui_story_5045_50450801_41_option_content = "Espero que a Farrell no le importe demasiado.",
  ui_story_5045_50450801_42_dialog_content = "Hicimos todo lo que pudimos, y la ley no tiene respuestas a las preguntas que quedan.",
  ui_story_5045_50450801_43_dialog_content = "Argh, solo olvídalo. ¡Démonos prisa en volver!",
  ui_story_5045_50450801_44_dialog_content = "Tienes razón. ¡Será mejor que nos apresuremos y empecemos el próximo caso!",
  ui_story_5045_50450801_45_dialog_content = "Tal vez podamos resolver cualquier caso sin problemas si tenemos una mayor <color=#1875ad>Compenetración</color>!",
  ui_story_5045_50450801_46_dialog_content = "¿¡Qué!?",
  ui_story_5045_50450801_47_dialog_content = "Yo solo...",
  ui_story_5045_50450801_48_dialog_content = "¡Solo quería volver y descansar!",
  ui_story_5045_50450801_49_option_content = "¡Hiciste lo mejor que pudiste!",
  ui_story_5045_50450801_50_dialog_content = "Creo que este es el mejor resultado que podíamos esperar.",
  ui_story_5045_50450801_51_dialog_content = "Ojala.",
  ui_story_5045_50450801_52_dialog_content = "De todos modos, aprovechemos esta oportunidad para dar una vuelta.",
  ui_story_5045_50450801_53_dialog_content = "Un poco de ejercicio podría hacerte sentir mejor.",
  ui_story_5045_50450801_54_dialog_content = "Si tú lo dices.",
  ui_story_5045_50450801_55_dialog_content = "El tiempo de hoy es realmente...",
  ui_story_5045_50450801_56_dialog_content = "<color=#737378>Whoosh</color>",
  ui_story_5045_50450801_57_dialog_content = "¡El viento es tan fuerte! Casi me dejó alucinado.",
  ui_story_5045_50450801_58_dialog_content = "La cometa que sostenía hace un momento... ¿Adónde fue esa cometa?",
  ui_story_5045_50450801_59_dialog_content = "Por ahí!",
  ui_story_5045_50450801_60_dialog_content = "<color=#737378>Whoosh</color>",
  ui_story_5045_50450801_61_dialog_content = "(Leyn?)",
  ui_story_5045_50450801_62_dialog_content = "(¿¡Cómo voló hacia el cielo y agarró esa cometa!?)",
  ui_story_5045_50450801_63_dialog_content = "(Esperar...)",
  ui_story_5045_50450801_64_dialog_content = "(¿Por qué siento que he visto todo este escenario antes?)",
  ui_story_5045_50450801_65_dialog_content = "(¡Ahora recuerdo!)",
  ui_story_5045_50450801_66_dialog_content = "(Es por Farrell, conoció a Sophie porque él...)",
  ui_story_5045_50450801_67_dialog_content = "Parece que a esta cometa le gusta mucho huir de sus amos.",
  ui_story_5045_50450801_68_dialog_content = "¿O todas las cometas simplemente desean buscar la libertad en el viento?",
  ui_story_5045_50450801_69_dialog_content = "(Es cierto que una cometa puede volar hacia el cielo azul debido al viento que la levanta).",
  ui_story_5045_50450801_70_dialog_content = "(¿Pero por qué tenemos que restringir su libertad con un hilo de seda?)",
  ui_story_5045_50450801_71_dialog_content = "PlayerName, Sé lo que estás pensando.",
  ui_story_5045_50450801_72_dialog_content = "Pero creo que la libertad sin restricciones no es libertad real en absoluto.",
  ui_story_5045_50450801_73_dialog_content = "Si a la cometa le falta el apoyo del hilo, pronto será arrastrada por el viento despiadado hacia el desierto árido.",
  ui_story_5045_50450801_74_dialog_content = "El reciente aumento del amor libre en Lumopolis es como el deseo de la cometa por el cielo.",
  ui_story_5045_50450801_75_dialog_content = "Si no hay hilo, el hilo de la justicia...",
  ui_story_5045_50450801_76_dialog_content = "Ni la libertad de amar ni la libertad de no amar pueden ser garantizadas.",
  ui_story_5045_50450801_77_dialog_content = "te lo tengo que dar...",
  ui_story_5045_50450801_78_dialog_content = "Desde una simple cometa rebelde que vuela por el cielo, has logrado desentrañar los misterios de la vida, el amor y la libertad.",
  ui_story_5045_50450801_79_dialog_content = "¡Ay! Mis disculpas.",
  ui_story_5045_50450801_80_dialog_content = "¡Por favor, no prestes atención a mis tonterías!",
  ui_story_5045_50450801_81_dialog_content = "Es solo que, después de este juicio reciente, creo que entiendo cómo seguir adelante con otros casos de la División de Romance.",
  ui_story_5045_50450801_82_dialog_content = "Por supuesto, se lo debo todo a su ayuda.",
  ui_story_5045_50450801_83_option_content = "¡No lo menciones!",
  ui_story_5045_50450801_84_dialog_content = "De hecho, usted mismo hizo la mayor parte del trabajo.",
  ui_story_5045_50450801_85_dialog_content = "Acabo de presentar algunas sugerencias poco profesionales de la periferia.",
  ui_story_5045_50450801_86_dialog_content = "Eres demasiado modesto.",
  ui_story_5045_50450801_87_dialog_content = "Si no fuera por tu sugerencia, quién sabe cuándo habría terminado ese primer caso.",
  ui_story_5045_50450801_88_option_content = "¿Parece que hay algo en tu mente?",
  ui_story_5045_50450801_89_dialog_content = "No hace falta decir que nada se te escapa, PlayerName.",
  ui_story_5045_50450801_90_dialog_content = "Para ser honesto, he estado pensando... si tan solo no hubiera amor en el mundo.",
  ui_story_5045_50450801_91_dialog_content = "¿Eh? ¿No quieres trabajar en la División de Romance?",
  ui_story_5045_50450801_92_dialog_content = "No, no, aprecio mi puesto actual.",
  ui_story_5045_50450801_93_dialog_content = "Siento cada vez más que el amor es como un veneno.",
  ui_story_5045_50450801_94_dialog_content = "Puede hacer que un caballero íntegro de repente se vuelva tan humilde...",
  ui_story_5045_50450801_95_dialog_content = "El amor es realmente difícil de entender, pero no podemos dejar que estos casos nos afecten.",
  ui_story_5045_50450801_96_dialog_content = "Debe haber muchos casos de amor verdaderamente maravilloso en el mundo.",
  ui_story_5045_50450801_97_dialog_content = "La razón por la que no los has visto es que todos estos amantes felices nunca terminarían en el Salón de la Justicia.",
  ui_story_5045_50450801_98_dialog_content = "¿Verdaderamente maravilloso amor? Me pregunto cómo se sentiría eso.",
  ui_story_5045_50450801_99_dialog_content = "Dos personas se aprecian, confían el uno en el otro y se superan mutuamente.",
  ui_story_5045_50450801_100_dialog_content = "Eso es lo que considero un amor verdaderamente maravilloso.",
  ui_story_5045_50450801_101_dialog_content = "Cierto...",
  ui_story_5045_50450801_102_dialog_content = "¿Qué te tiene en este estado de ánimo filosófico, de repente?",
  ui_story_5045_50450801_103_dialog_content = "Tus palabras me recordaron a alguien.",
  ui_story_5045_50450801_104_dialog_content = "¿OMS? ¿Los conozco?",
  ui_story_5045_50450801_105_dialog_content = "Eres tu, PlayerName.",
  ui_story_5045_50450801_106_dialog_content = "¿¡Qué!?",
  ui_story_5045_50450801_107_dialog_content = "¿Resulta que el amor entre amantes es tan similar a la amistad entre aliados?",
  ui_story_5045_50450801_108_dialog_content = "Eso es bastante cierto... jajaja...",
  ui_story_5045_50450801_109_dialog_content = "En tal caso, deseo a todos lo mejor en los asuntos del corazón.",
  ui_story_5045_50450801_110_dialog_content = "Noche Blanca en lo alto, espero que el amor de todos pueda permanecer feliz por mucho, mucho tiempo.",
  ui_story_5045_50450801_111_dialog_content = "Pero, ¿qué vamos a hacer ahora con esta cometa?",
  ui_story_5045_50450801_112_dialog_content = "Por ahora, ocupémonos de ello en su nombre.",
  ui_story_5045_50450801_113_dialog_content = "<color=#737378>Whoosh</color>",
  ui_story_5045_50450801_114_dialog_content = "Ah, el viento se está levantando de nuevo. Esta vez, voy a cuidar bien esta cometa.",
  ui_story_5045_50450801_115_dialog_content = "May ser deberíamos dejar volar la cometa una vez más.",
  ui_story_5045_50450801_116_dialog_content = "¿Eh?",
  ui_story_5045_50450801_117_dialog_content = "PlayerName, has volado una cometa antes?",
  ui_story_5045_50450901_1_dialog_content = "<color=#737378>Hora: 15:00</color>",
  ui_story_5045_50450901_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50450901_3_dialog_content = "(Nunca pensé que terminaría un caso tan pronto).",
  ui_story_5045_50450901_4_dialog_content = "(Mis habilidades legales no pueden ser mejores que mis habilidades psíquicas, ¿o sí?)",
  ui_story_5045_50450901_5_dialog_content = "(Si Irridon vio nuestro juicio, podría pensar en pagarme más).",
  ui_story_5045_50450901_6_dialog_content = "(Cuando llegue el momento, je, le daré Vice y los demás una sorpresa!)",
  ui_story_5045_50450901_7_dialog_content = "(Pero entonces de nuevo...)",
  ui_story_5045_50450901_8_dialog_content = "¿¡Por qué tanta gente presenta hoy!?",
  ui_story_5045_50450901_9_dialog_content = "¿Eh? ¿Perdió interés en el trabajo de prueba tan pronto?",
  ui_story_5045_50450901_10_dialog_content = "¡N-De ninguna manera!",
  ui_story_5045_50450901_11_dialog_content = "Ah, ¿qué trae a nuestra siempre ocupada Señora Irridon ¿aquí?",
  ui_story_5045_50450901_12_dialog_content = "Zzz...",
  ui_story_5045_50450901_13_dialog_content = "Tina, ¡despertar!",
  ui_story_5045_50450901_14_dialog_content = "Cierto...",
  ui_story_5045_50450901_15_dialog_content = "Angel, ¿Que estas esperando? ¡Ve y prepara un poco de té para nuestro estimado juez principal!",
  ui_story_5045_50450901_16_dialog_content = "... Vaya.",
  ui_story_5045_50450901_17_dialog_content = "No hay necesidad.",
  ui_story_5045_50450901_18_dialog_content = "Escuché que juzgaste un caso esta mañana, así que vine a evaluar las consecuencias.",
  ui_story_5045_50450901_19_dialog_content = "El caso fue llevado por el libro.",
  ui_story_5045_50450901_20_dialog_content = "Por el contrario, mi juicio mañana inspirará al mundo y se convertirá en un precedente para que las generaciones futuras aprendan e imiten.",
  ui_story_5045_50450901_21_dialog_content = "Cuando llegue el momento, siéntete libre de volver y atestiguarlo por ti mismo.",
  ui_story_5045_50450901_22_dialog_content = "Ya veremos. Tal vez, si tengo tiempo.",
  ui_story_5045_50450901_23_dialog_content = "Acabo de enterarme de que el caso de esta mañana causó un gran revuelo. Quiero saber los detalles.",
  ui_story_5045_50450901_24_dialog_content = "Dama Irridon, PlayerName y probé el caso de esta mañana.",
  ui_story_5045_50450901_25_dialog_content = "Anoté los detalles y el proceso del juicio en este cuaderno. Por favor échale un vistazo.",
  ui_story_5045_50450901_26_dialog_content = "Impresionante. Has formado algunos buenos hábitos desde que llegaste aquí, PlayerName.",
  ui_story_5045_50450901_27_dialog_content = "¿Acabas de decir que este caso causó revuelo?",
  ui_story_5045_50450901_28_dialog_content = "En seguida.",
  ui_story_5045_50450901_29_dialog_content = "Entonces, ¿cómo se encuentra actualmente la opinión pública con respecto a este caso?",
  ui_story_5045_50450901_30_dialog_content = "¿Qué piensas?",
  ui_story_5045_50450901_31_dialog_content = "Bueno... Supongo que debe ser bastante positivo, ¿no?",
  ui_story_5045_50450901_32_dialog_content = "PlayerName ha demostrado ser digno de ser elegido personalmente por usted, Juez Presidente, para ayudarnos aquí.",
  ui_story_5045_50450901_33_dialog_content = "Con la ayuda de PlayerName, es natural que Leyn debe hacer algunos progresos también.",
  ui_story_5045_50450901_34_dialog_content = "¡Tal vez no pase mucho tiempo antes de que se convierta en el segundo mejor juez en la División de Romance!",
  ui_story_5045_50450901_35_dialog_content = "Leyn, son PlayerName¿Los registros están completos?",
  ui_story_5045_50450901_36_dialog_content = "Sí, sus registros son muy completos, por cierto.",
  ui_story_5045_50450901_37_dialog_content = "La investigación solo rascó la superficie, y no se permitió que las partes se explicaran completamente en la corte...",
  ui_story_5045_50450901_38_dialog_content = "Recuerdo que tus pruebas anteriores no fueron tan descuidadas.",
  ui_story_5045_50450901_39_dialog_content = "Los casos de la División Romance son diferentes a todo lo que hemos encontrado antes.",
  ui_story_5045_50450901_40_dialog_content = "También estoy tratando de averiguar cuál es la mejor manera de manejar estos casos.",
  ui_story_5045_50450901_41_dialog_content = "La División de Romance se acaba de establecer y no hay casos de los que podamos aprender.",
  ui_story_5045_50450901_42_dialog_content = "Entiendo la presión.",
  ui_story_5045_50450901_43_dialog_content = "Pero recuerde que incluso un caso pequeño a nuestros ojos puede afectar la vida de las partes involucradas.",
  ui_story_5045_50450901_44_dialog_content = "La forma en que trates cada caso afectará la actitud de la gente de Lumopolis hacia las relaciones románticas en el futuro.",
  ui_story_5045_50450901_45_dialog_content = "Parece que la opinión pública como resultado de tomar el caso esta mañana no es muy buena...",
  ui_story_5045_50450901_46_dialog_content = "El caso de esta mañana nos muestra que el costo de violar un acuerdo de compromiso es insignificante.",
  ui_story_5045_50450901_47_dialog_content = "Es posible que veamos más casos relacionados con la disolución de compromisos.",
  ui_story_5045_50450901_48_dialog_content = "Prepárense.",
  ui_story_5045_50450901_49_dialog_content = "¿El juicio de Leyn aumentó nuestra carga de trabajo?",
  ui_story_5045_50450901_50_dialog_content = "Dado que todos nuestros casos son del mismo tipo, deberíamos poder manejarlos mucho más rápido.",
  ui_story_5045_50450901_51_dialog_content = "Si eso es cierto, tales casos serán entregados a Leyn y PlayerName en el futuro.",
  ui_story_5045_50450901_52_dialog_content = "¿Eh? Pero con todos estos casos...",
  ui_story_5045_50450901_53_dialog_content = "¿Cuántas sesiones se necesitarán para completar cada ensayo?",
  ui_story_5045_50451001_1_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50451001_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50451001_3_dialog_content = "Bostezo-",
  ui_story_5045_50451001_4_dialog_content = "¿Eh? PlayerName, ¿por qué me miras tan serio?",
  ui_story_5045_50451001_5_dialog_content = "¿Te quedaste dormido hace un momento?",
  ui_story_5045_50451001_6_dialog_content = "Claro, me quedé dormido...",
  ui_story_5045_50451001_7_dialog_content = "Pero estabas tan feliz hace un momento...",
  ui_story_5045_50451001_8_dialog_content = "Ahora que lo pienso, tuve un sueño tan hermoso hace un momento... ¡Jejejeje!",
  ui_story_5045_50451001_9_dialog_content = "Ejem... De todos modos, mientras estés despierto ahora.",
  ui_story_5045_50451001_10_dialog_content = "No estoy seguro exactamente de cómo se supone que debo ayudarte.",
  ui_story_5045_50451001_11_dialog_content = "Entonces, cuando estabas dormido, solo ayudé a hablar con algunas de las personas que presentaban casos.",
  ui_story_5045_50451001_12_dialog_content = "¿Nuevos casos?",
  ui_story_5045_50451001_13_dialog_content = "Déjame ver...",
  ui_story_5045_50451001_14_dialog_content = "Bueno, gracias, PlayerName, pero estas denuncias no son responsabilidad de la División de Romance.",
  ui_story_5045_50451001_15_dialog_content = "R-¿En serio? Lo siento. Supongo que he hecho más mal que bien...",
  ui_story_5045_50451001_16_dialog_content = "No te lo tomes a pecho.",
  ui_story_5045_50451001_17_dialog_content = "No te lo dije antes de quedarme dormido, así que es mi culpa.",
  ui_story_5045_50451001_18_dialog_content = "Sin embargo, puede estar seguro de que, aunque mis horas de trabajo son cortas, mi eficiencia es muy alta.",
  ui_story_5045_50451001_19_dialog_content = "Te enseñaré mi secreto de trabajo único en un momento.",
  ui_story_5045_50451001_20_dialog_content = "¡Wow eso es impresionante! ¡Empecemos!",
  ui_story_5045_50451001_21_dialog_content = "No hay prisa. Primero respóndeme una pregunta.",
  ui_story_5045_50451001_22_dialog_content = "Si un día te enamoraras de alguien, ¿se lo harías saber?",
  ui_story_5045_50451001_23_option_content = "En seguida.",
  ui_story_5045_50451001_24_dialog_content = "Si supiera que fue realmente amor, querría hacérselo saber.",
  ui_story_5045_50451001_25_dialog_content = "Incluso si me rechazaran, no importaría. Lo haría por respeto al sentimiento.",
  ui_story_5045_50451001_26_dialog_content = "Nunca esperé que fueras tan perspicaz a este respecto, PlayerName.",
  ui_story_5045_50451001_27_dialog_content = "Espero que la persona que me gusta piense igual que tú, jejeje.",
  ui_story_5045_50451001_28_option_content = "No.",
  ui_story_5045_50451001_29_dialog_content = "Si no les caía bien, confesarles mi amor solo les causaría problemas.",
  ui_story_5045_50451001_30_dialog_content = "Por lo tanto, no creo que les diría demasiado apresuradamente.",
  ui_story_5045_50451001_31_dialog_content = "Jejeje, eres tan tímido como pensaba, PlayerName.",
  ui_story_5045_50451001_32_option_content = "No lo sé.",
  ui_story_5045_50451001_33_dialog_content = "No puedo predecir cómo me sentiré en el futuro.",
  ui_story_5045_50451001_34_dialog_content = "Podría saber qué hacer entonces.",
  ui_story_5045_50451001_35_dialog_content = "Hmph, qué respuesta tan aburrida.",
  ui_story_5045_50451001_36_dialog_content = "No entiendo lo que quieres decir. ¿Por qué lo preguntas?",
  ui_story_5045_50451001_37_dialog_content = "Parece que esto no tiene nada que ver con nuestro trabajo.",
  ui_story_5045_50451001_38_dialog_content = "Tiene todo que ver con nuestro trabajo.",
  ui_story_5045_50451001_39_dialog_content = "¿En qué división estamos trabajando?",
  ui_story_5045_50451001_40_dialog_content = "La División Romántica.",
  ui_story_5045_50451001_41_dialog_content = "Entonces, por supuesto, deberíamos discutir temas relacionados con el amor.",
  ui_story_5045_50451001_42_dialog_content = "Y discutir el tema del amor puede resultar rápidamente en una relación de trabajo más estrecha.",
  ui_story_5045_50451001_43_dialog_content = "Espero que podamos cooperar felizmente.",
  ui_story_5045_50451001_44_dialog_content = "En ese caso.",
  ui_story_5045_50451001_45_dialog_content = "¿Cómo responderías esa pregunta ahora mismo? Tina?",
  ui_story_5045_50451001_46_dialog_content = "Jaja, no esperaba que me cambiaras las tornas de esta manera. Bueno, déjame decirte.",
  ui_story_5045_50451001_47_dialog_content = "Yo nunca tomaría la iniciativa. Después de todo, soy una dama.",
  ui_story_5045_50451001_48_dialog_content = "A lo sumo... En secreto, aumentaría activamente las posibilidades de que nos encontremos.",
  ui_story_5045_50451001_49_dialog_content = "Pero si no se ven, ¿cómo puedes saber si realmente te gustan?",
  ui_story_5045_50451001_50_dialog_content = "¿Qué harás si la otra persona resulta ser mala para ti?",
  ui_story_5045_50451001_51_dialog_content = "Nunca había considerado las cosas desde esa perspectiva...",
  ui_story_5045_50451001_52_dialog_content = "Eso es como tú, PlayerName. entiendes mas que Leyn!",
  ui_story_5045_50451001_53_dialog_content = "De hecho, eres un buen asistente. Me aseguraré de molestarte con tales asuntos a partir de ahora.",
  ui_story_5045_50451001_54_dialog_content = "Ayúdenme a recibir todos los casos, verificar si las declaraciones son verdaderas y determinar las leyes y regulaciones relevantes...",
  ui_story_5045_50451001_55_dialog_content = "¡Entonces resúmeme los detalles del caso!",
  ui_story_5045_50451001_56_dialog_content = "¿Quieres decir que básicamente quieres que haga todo por ti?",
  ui_story_5045_50451001_57_dialog_content = "Me sentaré en la silla del juez y finalmente llevaré a cabo el juicio. Esta es la parte más crucial y agotadora.",
  ui_story_5045_50451001_58_dialog_content = "Pero pareces bastante interesado en el juicio... ¿Por qué no te unes a mí en la corte?",
  ui_story_5045_50451001_59_dialog_content = "<size=32>Menos mal que prometió pagarme extra...</size>",
  ui_story_5045_50451001_60_dialog_content = "¿Mmm? ¿Dijiste algo?",
  ui_story_5045_50451001_61_dialog_content = "Dije... con tantos casos por procesar, ¿por cuál deberíamos empezar?",
  ui_story_5045_50451001_62_dialog_content = "No pierdas tu tiempo en cosas tan insignificantes... Bostezo—",
  ui_story_5045_50451001_63_dialog_content = "Simplemente elija el que tiene en sus manos ahora mismo.",
  ui_story_5045_50451001_64_dialog_content = "\"Solicitud de que la demandada Fanny y el demandante Bacon sean <color=#1875ad>divorciado</color> conforme a la ley...\"?",
  ui_story_5045_50451001_65_dialog_content = "¡Bien! ¡Empecemos!",
  ui_story_5045_50451001_66_dialog_content = "Zzz...",
  ui_story_5045_50451001_67_dialog_content = "¿Quería empezar a trabajar o empezar a dormir...",
  ui_story_5045_50451101_1_dialog_content = "<color=#737378>Hora: 9:00 a.m.</color>",
  ui_story_5045_50451101_2_dialog_content = "<color=#737378>Ubicación: Salón de Justicia Lumo, Sala del Tribunal</color>",
  ui_story_5045_50451101_3_dialog_content = "PlayerName, ¿recuerdas qué caso estamos juzgando hoy?",
  ui_story_5045_50451101_4_dialog_content = "¡Recuerdo! El demandante, <color=#1875ad>Tocino</color> y el acusado, <color=#1875ad>Coño</color>'s...",
  ui_story_5045_50451101_5_option_content = "Disputa de divorcio",
  ui_story_5045_50451101_6_dialog_content = "Así es. Parece que la lección antes del juicio está funcionando en ti.",
  ui_story_5045_50451101_7_dialog_content = "Quizás algún día, pronto, puedas terminar una prueba por tu cuenta.",
  ui_story_5045_50451101_8_option_content = "anulación de compromiso",
  ui_story_5045_50451101_9_dialog_content = "¡Guau! Parece que la lección antes del juicio no te está funcionando.",
  ui_story_5045_50451101_10_dialog_content = "Su responsabilidad más básica es recordar la información en estos archivos de casos antes de la sesión del tribunal.",
  ui_story_5045_50451101_11_dialog_content = "En la próxima prueba, debe intentar mirar, escuchar y aprender más.",
  ui_story_5045_50451101_12_dialog_content = "¡Ah, el archivo del caso dice \"disputa de divorcio\"!",
  ui_story_5045_50451101_13_dialog_content = "Nunca pensé que tropezaría en el primer obstáculo como este...",
  ui_story_5045_50451101_14_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451101_15_dialog_content = "<size=45>Noche Blanca en lo alto. ¡La corte está ahora en sesión!</size>",
  ui_story_5045_50451101_16_dialog_content = "¡Noche Blanca en lo alto!",
  ui_story_5045_50451101_17_dialog_content = "(¡Hay tanta gente escuchando hoy! Supongo que todos están prestando mucha atención a los casos de la División de Romance en estos días...)",
  ui_story_5045_50451101_18_dialog_content = "En primer lugar, escuchemos lo que tiene que decir el demandante.",
  ui_story_5045_50451101_19_dialog_content = "S-Su Señoría, mi nombre es Bacon.",
  ui_story_5045_50451101_20_dialog_content = "¿Por qué el demandante se ve tan asustado?",
  ui_story_5045_50451101_21_dialog_content = "Bacon, por favor no te sientas nervioso o asustado.",
  ui_story_5045_50451101_22_dialog_content = "El Salón de la Justicia es el lugar más justo y seguro de Lumopolis.",
  ui_story_5045_50451101_23_dialog_content = "Puede exponer su solicitud con confianza aquí.",
  ui_story_5045_50451101_24_dialog_content = "Quiero divorciarme de mi esposa, Fanny...",
  ui_story_5045_50451101_25_dialog_content = "Bacon, ¿de verdad tienes que hacer esto?",
  ui_story_5045_50451101_26_dialog_content = "¿Puedes... puedes dejarme terminar?",
  ui_story_5045_50451101_27_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451101_28_dialog_content = "El demandado se abstendrá de interrumpir al demandante.",
  ui_story_5045_50451101_29_dialog_content = "...",
  ui_story_5045_50451101_30_dialog_content = "Bacon, ¿por qué quiere divorciarse de su esposa Fanny?",
  ui_story_5045_50451101_31_dialog_content = "¡Porque nosotros... somos tan diferentes!",
  ui_story_5045_50451101_32_dialog_content = "¿Cuánto tiempo has estado casado?",
  ui_story_5045_50451101_33_dialog_content = "Siete años.",
  ui_story_5045_50451101_34_dialog_content = "Hace unos años, tenía un trabajo que era lo suficientemente bueno para mantenernos, por lo que la vida era tolerable.",
  ui_story_5045_50451101_35_dialog_content = "Pero el año pasado, de repente me despidieron y perdí mi fuente de ingresos.",
  ui_story_5045_50451101_36_dialog_content = "Desde entonces, Fanny me ha regañado todos los días en casa y se ha resentido conmigo por no tener trabajo.",
  ui_story_5045_50451101_37_dialog_content = "Ahora me acabo de dar cuenta de que el amor entre nosotros ha sido erosionado por el tiempo.",
  ui_story_5045_50451101_38_dialog_content = "Todo lo que vemos ahora son las deficiencias de los demás.",
  ui_story_5045_50451101_39_dialog_content = "No quiero perder más tiempo en un matrimonio así... Quiero divorciarme, para poder volver a ser libre.",
  ui_story_5045_50451101_40_dialog_content = "En otras palabras, ¿su relación se ha roto?",
  ui_story_5045_50451101_41_dialog_content = "Acusado, ¿está de acuerdo con el demandante?",
  ui_story_5045_50451101_42_dialog_content = "Señoría, no estoy de acuerdo.",
  ui_story_5045_50451101_43_dialog_content = "Bacon se deprimió mucho después de que su empleador lo dejara ir.",
  ui_story_5045_50451101_44_dialog_content = "Solo quería animar a Bacon, así que constantemente le pedía que hablara y caminara conmigo.",
  ui_story_5045_50451101_45_dialog_content = "Nunca pensé en dejar a Bacon.",
  ui_story_5045_50451101_46_dialog_content = "Desde que perdió su trabajo, he estado trabajando a tiempo parcial para complementar nuestros ahorros. Solo me he quejado quizás una o dos veces.",
  ui_story_5045_50451101_47_dialog_content = "Pero desde...",
  ui_story_5045_50451101_48_dialog_content = "Pero, al final del día, si he hecho algo mal, ¡cambiaré!",
  ui_story_5045_50451101_49_dialog_content = "(Parece que Fanny quería decir algo justo ahora, pero de repente <color=#1875ad>cambió su opinión</color>...)",
  ui_story_5045_50451101_50_dialog_content = "Así es como es.",
  ui_story_5045_50451101_51_dialog_content = "¿Está bien?",
  ui_story_5045_50451101_52_dialog_content = "Creo que Bacon puede haber estado sin trabajo por mucho tiempo... Se altera tan fácilmente.",
  ui_story_5045_50451101_53_dialog_content = "Por eso quiere divorciarse de mí, ¡está tan estresado!",
  ui_story_5045_50451101_54_dialog_content = "Pero quiero creer que Bacon mejorará eventualmente.",
  ui_story_5045_50451101_55_dialog_content = "¡Y, pase lo que pase, no me divorciaré de él!",
  ui_story_5045_50451101_56_dialog_content = "Comprendo.",
  ui_story_5045_50451101_57_dialog_content = "Así que... bostezo—",
  ui_story_5045_50451101_58_dialog_content = "Tina¡Estamos en medio de un juicio! ¡No te duermas!",
  ui_story_5045_50451101_59_dialog_content = "Eh...? ¡Ay!",
  ui_story_5045_50451101_60_dialog_content = "Gracias por despertarme, PlayerName. Casi hago el ridículo hace un momento...",
  ui_story_5045_50451101_61_dialog_content = "Bueno, confía en ti para elegir un caso como este. No es fácil de intentar.",
  ui_story_5045_50451101_62_dialog_content = "Después de que esta ola de amor libre se extendió por Lumopolis, el número de casos de divorcio ha aumentado.",
  ui_story_5045_50451101_63_dialog_content = "Pero otorgar o no el divorcio es el problema que Romance Division ha estado investigando durante bastante tiempo.",
  ui_story_5045_50451101_64_dialog_content = "En cuanto al caso actual, PlayerName...",
  ui_story_5045_50451101_65_dialog_content = "¿Tienes alguna otra idea?",
  ui_story_5045_50451101_66_dialog_content = "Parece que tampoco has encontrado ninguna pista útil.",
  ui_story_5045_50451101_67_dialog_content = "¿E-Esta pista es inútil?",
  ui_story_5045_50451101_67X1_dialog_content = "Además de eso...",
  ui_story_5045_50451101_68_dialog_content = "¡Oh, lo sé!",
  ui_story_5045_50451101_69_dialog_content = "Tina, ¡mira esto!",
  ui_story_5045_50451101_70_dialog_content = "¿Ahora eres capaz de grabar las declaraciones de ambos lados de la corte sin mí? Nada mal.",
  ui_story_5045_50451101_71_dialog_content = "Realmente eres una alegría de asistente.",
  ui_story_5045_50451101_72_dialog_content = "¡Pero no se limite a prestar atención a los registros!",
  ui_story_5045_50451101_73_dialog_content = "En cuanto al caso actual...",
  ui_story_5045_50451101_74_dialog_content = "No creo que las causales de divorcio de Bacon sean completamente arbitrarias.",
  ui_story_5045_50451101_75_dialog_content = "¿No dijo Bacon que sentía que no había amor entre ellos?",
  ui_story_5045_50451101_76_dialog_content = "Matrimonio sin amor... Es difícil de imaginar.",
  ui_story_5045_50451101_77_dialog_content = "Pero Fanny también explicó que solo quería animar a Bacon.",
  ui_story_5045_50451101_78_dialog_content = "Y me pareció claro que Fanny había tomado la decisión de ayudar a Bacon a superar este momento difícil, sin importar qué.",
  ui_story_5045_50451101_79_dialog_content = "Eso tiene sentido, Bacon está desempleado y deprimido...",
  ui_story_5045_50451101_80_dialog_content = "Pero a Fanny no solo no le importó, sino que también prometió quedarse con Bacon y ayudarlo a recuperarse.",
  ui_story_5045_50451101_81_dialog_content = "¡Este tipo de relación entre marido y mujer es simplemente una historia de Lumopolis!",
  ui_story_5045_50451101_82_dialog_content = "Si Bacon simplemente está enojado en este momento, y el juez decide concederle el divorcio...",
  ui_story_5045_50451101_83_dialog_content = "¿No me robará el Dios de la Luz la oportunidad de encontrar mi verdadero amor?",
  ui_story_5045_50451101_84_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451101_85_dialog_content = "Noche Blanca en lo alto. ¡Es hora del veredicto!",
  ui_story_5045_50451101_86_dialog_content = "El Salón de Justicia finalmente decidió que la relación entre el demandante Bacon y la demandada Fanny no debe disolverse.",
  ui_story_5045_50451101_87_dialog_content = "Una unión formada ante los ojos del Dios de la Luz no debe descartarse tan apresuradamente.",
  ui_story_5045_50451101_88_dialog_content = "Continúen amándose y trabajando en su matrimonio.",
  ui_story_5045_50451101_89_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451101_90_dialog_content = "¡El juicio ha terminado!",
  ui_story_5045_50451101_91_dialog_content = "El lado de la historia de Fanny es muy conmovedor.",
  ui_story_5045_50451101_92_dialog_content = "¿Pero no sientes que ella ha estado escondiendo algo deliberadamente?",
  ui_story_5045_50451101_93_dialog_content = "PlayerName, tu poder de observación es bastante impresionante.",
  ui_story_5045_50451101_94_dialog_content = "Preguntémosle a Fanny qué esconde.",
  ui_story_5045_50451101_95_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451101_96_dialog_content = "Noche blanca en lo alto, Fanny, ¿estás segura de que nos has contado toda la historia?",
  ui_story_5045_50451101_97_dialog_content = "Yo creo que sí...",
  ui_story_5045_50451101_98_dialog_content = "Si no lo dices... ¡entonces permíteme!",
  ui_story_5045_50451101_99_dialog_content = "Su Señoría, Fanny sabe que no tenemos mucho dinero, pero aun así pidió prestada una gran cantidad y ahora estamos endeudados.",
  ui_story_5045_50451101_100_dialog_content = "Bacon, como te dije, fue todo para ti.",
  ui_story_5045_50451101_101_dialog_content = "¿Para mí?",
  ui_story_5045_50451101_102_dialog_content = "Tú... ¡Lo tomaste prestado sin ni siquiera preguntarme!",
  ui_story_5045_50451101_103_dialog_content = "Yo solo... yo solo...",
  ui_story_5045_50451101_104_dialog_content = "Fanny, ¿es verdad que pediste dinero prestado sin el conocimiento de Bacon?",
  ui_story_5045_50451101_105_dialog_content = "... Es cierto.",
  ui_story_5045_50451101_106_dialog_content = "Señoría, no puedo vivir con alguien que me mintió así.",
  ui_story_5045_50451101_107_dialog_content = "Por favor, permítame divorciarme de Fanny.",
  ui_story_5045_50451101_108_dialog_content = "Solo tengo una petición: por favor, hablemos de la división de nuestros bienes.",
  ui_story_5045_50451101_109_dialog_content = "Fanny, ¿estás de acuerdo con la petición de Bacon?",
  ui_story_5045_50451101_110_dialog_content = "Suspiro, no tengo nada más que decir...",
  ui_story_5045_50451101_111_dialog_content = "Estaré de acuerdo con lo que quiera Bacon.",
  ui_story_5045_50451101_112_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451101_113_dialog_content = "Noche Blanca en lo alto. ¡Es hora del veredicto!",
  ui_story_5045_50451101_114_dialog_content = "Debido a diferencias irreconciliables entre el demandante Bacon y la demandada Fanny, el Salón de Justicia dictamina que su matrimonio debe disolverse de inmediato.",
  ui_story_5045_50451101_115_dialog_content = "De acuerdo con la solicitud de las partes, ahora pueden negociar la división de sus bienes entre ellos.",
  ui_story_5045_50451101_116_dialog_content = "Luego de lo cual, firmarán el acuerdo correspondiente en presencia del juez.",
  ui_story_5045_50451101_117_dialog_content = "Si no acepta esta sentencia, podrá recurrir de conformidad con lo dispuesto por la Sala de Justicia.",
  ui_story_5045_50451101_118_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451101_119_dialog_content = "¡El juicio ha terminado!",
  ui_story_5045_50451201_1_dialog_content = "<color=#737378>Hora: 11:00 a.m.</color>",
  ui_story_5045_50451201_2_dialog_content = "<color=#737378>Ubicación: Salón de Justicia Lumo, Sala del Tribunal</color>",
  ui_story_5045_50451201_3_dialog_content = "Suspiro, ¿Tina realmente me va a dejar hacer esto por mi cuenta...?",
  ui_story_5045_50451201_4_dialog_content = "Pase lo que pase, no me despiertes antes de las dos de la tarde.",
  ui_story_5045_50451201_5_dialog_content = "Pero el acuerdo de liquidación de la propiedad entre Bacon y Fanny...",
  ui_story_5045_50451201_6_dialog_content = "Siempre que nadie se oponga al acuerdo, puede dejar que lo firmen.",
  ui_story_5045_50451201_7_dialog_content = "Sé que puedes manejarlo... Bostezo—",
  ui_story_5045_50451201_8_dialog_content = "Zzz...",
  ui_story_5045_50451201_9_dialog_content = "¡Oye, no hay forma de que te duermas tan rápido!",
  ui_story_5045_50451201_10_dialog_content = "Bacon y Fanny firmaron el acuerdo al final. Afortunadamente, no apareció nada fuera de lo común.",
  ui_story_5045_50451201_11_dialog_content = "¡Eh!",
  ui_story_5045_50451201_12_dialog_content = "Su Señoría...",
  ui_story_5045_50451201_13_dialog_content = "Fanny, ¿qué haces aquí atrás?",
  ui_story_5045_50451201_14_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50451201_15_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50451201_16_dialog_content = "Bostezo.",
  ui_story_5045_50451201_17_dialog_content = "Que estas comiendo, PlayerName?",
  ui_story_5045_50451201_18_dialog_content = "Finalmente despertaste.",
  ui_story_5045_50451201_19_dialog_content = "Bacon y Fanny firmaron el acuerdo esta mañana.",
  ui_story_5045_50451201_20_dialog_content = "Pero Fanny presentó una apelación poco después.",
  ui_story_5045_50451201_21_dialog_content = "¿Eh? ¿No está contenta con la forma en que se dividió su propiedad?",
  ui_story_5045_50451201_22_dialog_content = "Podrías decir eso, pero no es lo que podrías pensar.",
  ui_story_5045_50451201_23_dialog_content = "Mira su acuerdo.",
  ui_story_5045_50451201_24_dialog_content = "\"Todas las propiedades de la pareja ahora pertenecen a Fanny, y todas sus deudas pertenecen a Bacon\"?",
  ui_story_5045_50451201_25_dialog_content = "¿Fanny obligó a Bacon a escribir esto?",
  ui_story_5045_50451201_26_dialog_content = "Por el contrario, el acuerdo fue escrito por Bacon. Fanny no quería pelear por su propiedad porque estaba demasiado angustiada por toda la prueba.",
  ui_story_5045_50451201_27_dialog_content = "Ella firmó el acuerdo sin leerlo, luego descubrió que estos eran los términos después del hecho.",
  ui_story_5045_50451201_28_dialog_content = "Bacon nos mostró claramente que estaba resentido con Fanny en el juicio. ¿Por qué él haría eso?",
  ui_story_5045_50451201_29_dialog_content = "Fanny siente que esto demuestra que Bacon todavía la ama, por lo que apela al fallo.",
  ui_story_5045_50451201_30_dialog_content = "Nos ha pedido que retiremos la sentencia de divorcio.",
  ui_story_5045_50451201_31_dialog_content = "Mi juicio fue... ¿equivocado?",
  ui_story_5045_50451201_32_option_content = "No se apresure a culparse a sí mismo.",
  ui_story_5045_50451201_33_dialog_content = "Es posible que las partes interesadas no hayan declarado todos los hechos en el tribunal.",
  ui_story_5045_50451201_34_dialog_content = "Hizo el juicio que mejor se adaptaba a la situación en ese momento.",
  ui_story_5045_50451201_35_dialog_content = "¡Ahora, solo tenemos que encontrar una manera de extraer los hechos de todo esto y prepararnos para la apelación!",
  ui_story_5045_50451201_36_dialog_content = "... Nunca pensé que serías tú quien me consolara.",
  ui_story_5045_50451201_37_dialog_content = "Pero aun así, gracias, PlayerName.",
  ui_story_5045_50451201_38_dialog_content = "Soy un verdadero juez después de todo, nunca dejaría que una cosa tan pequeña como esta me inquietara.",
  ui_story_5045_50451201_39_option_content = "No podemos estar seguros todavía.",
  ui_story_5045_50451201_40_dialog_content = "El acuerdo de resolución de bienes de Bacon contradice claramente su declaración anterior sobre sus diferencias irreconciliables.",
  ui_story_5045_50451201_41_dialog_content = "¿Cómo podemos soportar el juicio cuando no sabemos lo que realmente sucedió entre ellos?",
  ui_story_5045_50451201_42_dialog_content = "Tienes razón. Para juzgar este caso correctamente, es crucial que averigüemos qué sucedió realmente.",
  ui_story_5045_50451201_43_option_content = "entonces esta mal",
  ui_story_5045_50451201_44_dialog_content = "No hay otra explicación para lo que está pasando ahora.",
  ui_story_5045_50451201_45_dialog_content = "¿En realidad...?",
  ui_story_5045_50451201_46_dialog_content = "Sin embargo, como jueces, todavía tenemos que hacer nuestros juicios basados en hechos.",
  ui_story_5045_50451201_47_dialog_content = "¿Pero qué pasó entre ellos?",
  ui_story_5045_50451201_48_dialog_content = "¡Vamos!",
  ui_story_5045_50451201_49_dialog_content = "¿Eh? ¿A donde?",
  ui_story_5045_50451201_50_dialog_content = "A su casa para investigar qué pasó realmente, por supuesto.",
  ui_story_5045_50451201_51_dialog_content = "Y será mejor que nos apresuremos, si no terminamos de investigar en las próximas dos horas...",
  ui_story_5045_50451201_52_dialog_content = "Tendrás que llevarme en tu espalda cuando me duerma.",
  ui_story_5045_50451201_53_dialog_content = "A-Muy bien, ¡vamos entonces!",
  ui_story_5045_50451201_54_dialog_content = "<color=#737378>Hora: 14:30</color>",
  ui_story_5045_50451201_55_dialog_content = "<color=#737378>Ubicación: Bajo Lumopolis</color>",
  ui_story_5045_50451201_56_dialog_content = "La casa de Bacon y Fanny está más adelante.",
  ui_story_5045_50451201_57_dialog_content = "Oye, ¿quién es ese tipo que está parado en su puerta?",
  ui_story_5045_50451201_58_dialog_content = "(¿Por qué se ve tan familiar...?)",
  ui_story_5045_50451201_59_dialog_content = "...",
  ui_story_5045_50451201_60_dialog_content = "Hola. ¿Conoces a Bacon y Fanny?",
  ui_story_5045_50451201_61_dialog_content = "Lo siento, pero... ¿quién eres?",
  ui_story_5045_50451201_62_dialog_content = "Somos del Salón de la Justicia.",
  ui_story_5045_50451201_63_dialog_content = "PlayerName, muéstrale esa cosa y podrás probar nuestra <color=#1875ad>identidad</color>.",
  ui_story_5045_50451201_64_dialog_content = "¿Esta?",
  ui_story_5045_50451201_65_dialog_content = "Eso no es lo que quise decir.",
  ui_story_5045_50451201_66_dialog_content = "Oh, ¿lo es? En ese caso...",
  ui_story_5045_50451201_67_dialog_content = "¿Ustedes son jueces? Por favor, perdone mi rudeza en este momento.",
  ui_story_5045_50451201_68_dialog_content = "Soy amigo de Bacon. Los nombres <color=#1875ad>Carlos</color>.",
  ui_story_5045_50451201_69_dialog_content = "Solo vine aquí buscando a Bacon, pero parece que solo Fanny está en casa ahora.",
  ui_story_5045_50451201_70_dialog_content = "(¿No sabe que Bacon y Fanny se están divorciando?)",
  ui_story_5045_50451201_71_dialog_content = "Entonces, ¿cuál es su opinión sobre la relación de Bacon con su esposa?",
  ui_story_5045_50451201_72_dialog_content = "... ¿Han hecho algo ilegal?",
  ui_story_5045_50451201_73_dialog_content = "Ellos van a-",
  ui_story_5045_50451201_74_dialog_content = "...",
  ui_story_5045_50451201_75_dialog_content = "<size=32>Ejem... ¡No dejes que los detalles del caso afecten la opinión del testigo!</size>",
  ui_story_5045_50451201_76_dialog_content = "De hecho, solo estamos investigando la felicidad de la vida matrimonial en Lumopolis.",
  ui_story_5045_50451201_77_dialog_content = "Le agradeceríamos que pudiera respondernos algunas preguntas.",
  ui_story_5045_50451201_78_dialog_content = "Bueno, siempre han sido una pareja muy amorosa, un brillante ejemplo para todos los que los conocen.",
  ui_story_5045_50451201_79_dialog_content = "¿Está al tanto de cualquier tema sobre el cual los dos puedan haber discutido?",
  ui_story_5045_50451201_80_dialog_content = "¡Ja ja! ¿Argumentar? Incluso si Lumopolis cayera del cielo, no lucharían.",
  ui_story_5045_50451201_81_dialog_content = "Entiendo...",
  ui_story_5045_50451201_82_dialog_content = "<color=#737378>Hora: 15:00</color>",
  ui_story_5045_50451201_83_dialog_content = "<color=#737378>Ubicación: Lower Lumopolis, Bacon y Fanny's House</color>",
  ui_story_5045_50451201_84_dialog_content = "¿Hola? ¿Hay alguien en casa?",
  ui_story_5045_50451201_85_dialog_content = "Señorías, ¿qué los trae por aquí?",
  ui_story_5045_50451201_86_dialog_content = "Hemos recibido su solicitud de apelación y nos hemos dado cuenta de que es posible que se hayan cometido errores durante el primer juicio.",
  ui_story_5045_50451201_87_dialog_content = "Entonces, estamos aquí para encontrarlos a ustedes dos para determinar todos los detalles de la situación.",
  ui_story_5045_50451201_88_dialog_content = "Bacon... dijo que volvería a casa más tarde para hacer las maletas.",
  ui_story_5045_50451201_89_dialog_content = "Pero, por favor, ¡entra!",
  ui_story_5045_50451201_90_dialog_content = "¿Qué es esto en el suelo...?",
  ui_story_5045_50451201_91_dialog_content = "Lo siento mucho. No he tenido tiempo de limpiar las cosas...",
  ui_story_5045_50451201_92_dialog_content = "Este <color=#1875ad>lámina</color> es...",
  ui_story_5045_50451201_93_dialog_content = "¡Soy yo! Lo rompí sin querer...",
  ui_story_5045_50451201_94_dialog_content = "Pero este plato no parece que se haya roto accidentalmente.",
  ui_story_5045_50451201_95_dialog_content = "Fanny, vinimos aquí por una razón: deseamos encontrar la verdad.",
  ui_story_5045_50451201_96_dialog_content = "Si todavía está ocultando algo, me temo que la verdad de este caso nunca saldrá a la luz.",
  ui_story_5045_50451201_97_dialog_content = "... Bien.",
  ui_story_5045_50451201_98_dialog_content = "Bacon rompió este plato anoche.",
  ui_story_5045_50451201_99_dialog_content = "Pero podía sentir que estaba tratando deliberadamente de hacerme enojar para que aceptara el hecho de que pronto nos divorciaríamos.",
  ui_story_5045_50451201_100_dialog_content = "No entiendo. Si así es como te trata Bacon... ¿por qué querrías seguir con él?",
  ui_story_5045_50451201_101_dialog_content = "Obviamente, nunca has conocido el amor verdadero.",
  ui_story_5045_50451201_102_dialog_content = "Un día, formarás una familia propia con la persona que amas...",
  ui_story_5045_50451201_103_dialog_content = "Cuando llegue ese día, harás todo lo que esté a tu alcance para mantener a esa familia.",
  ui_story_5045_50451201_104_dialog_content = "¿Incluso si Bacon quiere separar a tu familia?",
  ui_story_5045_50451201_105_dialog_content = "Señorías, hay algunas cosas que no pude decir en la corte. Tenía miedo de que se rieran de Bacon.",
  ui_story_5045_50451201_106_dialog_content = "Tenga la seguridad de que mantendremos su secreto a salvo.",
  ui_story_5045_50451201_107_dialog_content = "Sería lo mejor para todos si nos dijera lo que tiene que decir.",
  ui_story_5045_50451201_108_dialog_content = "Un día, arrastré a Bacon a dar un paseo y nos topamos con un evento de consulta gratuita que estaba organizando cierta clínica.",
  ui_story_5045_50451201_109_dialog_content = "Fue entonces cuando a Bacon le diagnosticaron <color=#1875ad>depresión</color>.",
  ui_story_5045_50451201_110_dialog_content = "El médico dijo que había algo en su corazón que estaba convirtiendo a Bacon en un letárgico, deprimido, insomne...",
  ui_story_5045_50451201_111_dialog_content = "Fue entonces cuando descubrí por primera vez que Bacon estaba enfermo y que no estaba holgazaneando por el simple hecho de hacerlo.",
  ui_story_5045_50451201_112_dialog_content = "Así que después de eso, no lo regaño nunca más.",
  ui_story_5045_50451201_113_dialog_content = "Solo esperaba que Bacon pudiera recibir el tratamiento que necesitaba y mejorar gradualmente.",
  ui_story_5045_50451201_114_dialog_content = "Pero realmente no esperaba que Bacon fuera repentinamente al Salón de la Justicia y solicitara el divorcio.",
  ui_story_5045_50451201_115_dialog_content = "Algo debe haberle pasado... pero se negó a decirme nada.",
  ui_story_5045_50451201_116_dialog_content = "¿Qué le pudo haber pasado a Bacon?",
  ui_story_5045_50451201_117_dialog_content = "Probablemente no nos dirá si le preguntamos directamente. ¿Por qué no buscamos pistas alrededor de su casa primero?",
  ui_story_5045_50451201_118_dialog_content = "¿Hay algún lugar en particular que te gustaría investigar?",
  ui_story_5045_50451201_119_dialog_content = "Déjame pensar.",
  ui_story_5045_50451201_120_option_content = "revisa las paredes",
  ui_story_5045_50451201_121_dialog_content = "¿Puedo echar un vistazo a eso? <color=#1875ad>foto</color> colgado en la pared?",
  ui_story_5045_50451201_122_dialog_content = "Claro, te lo anoto.",
  ui_story_5045_50451201_123_dialog_content = "Es una foto de Fanny y Bacon.",
  ui_story_5045_50451201_124_dialog_content = "Sí, pero eso fue hace siete años.",
  ui_story_5045_50451201_125_dialog_content = "En ese momento, nos acabábamos de casar y no teníamos nada.",
  ui_story_5045_50451201_126_dialog_content = "No sé cómo, pero Bacon de alguna manera persuadió a un fotógrafo para que nos tomara esta foto gratis...",
  ui_story_5045_50451201_127_dialog_content = "Ahora que lo pienso, esta fue la primera y única foto que nos tomamos juntos.",
  ui_story_5045_50451201_128_dialog_content = "Es el <color=#1875ad>DIRECCIÓN</color> escrito en la parte de atrás donde te lo llevaron?",
  ui_story_5045_50451201_129_dialog_content = "Mmm, eso es extraño. No recuerdo que haya nada escrito en la parte de atrás...",
  ui_story_5045_50451201_130_dialog_content = "Pero esta es la letra de Bacon.",
  ui_story_5045_50451201_131_dialog_content = "Parece algo sospechoso, ¿no? Vamos a escribirlo.",
  ui_story_5045_50451201_132_dialog_content = "Además de eso...",
  ui_story_5045_50451201_133_option_content = "revisa la tabla",
  ui_story_5045_50451201_134_dialog_content = "¿Eh? Qué es esto <color=#1875ad>tarjeta</color>?",
  ui_story_5045_50451201_135_dialog_content = "... Eso es de la <color=#1875ad>curso de autoayuda</color>. Se trata de un <color=#1875ad>tarjeta de asistencia</color>.",
  ui_story_5045_50451201_136_dialog_content = "Nuestro amigo Karl me dijo que este curso fue particularmente bueno.",
  ui_story_5045_50451201_137_dialog_content = "Ayudan a las personas a desarrollar su fuerza de voluntad para que ya no teman enfrentar las dificultades de la vida.",
  ui_story_5045_50451201_138_dialog_content = "Dijo que muchas de las personas que tomaron este curso tuvieron una vida mejor.",
  ui_story_5045_50451201_139_dialog_content = "¿Realmente ofrecen cursos como este en Lumopolis?",
  ui_story_5045_50451201_140_dialog_content = "Yo no he tomado ningún curso como este, pero sé que son bastante caros.",
  ui_story_5045_50451201_141_dialog_content = "... Quería que Bacon obtuviera ayuda, así que pedí dinero prestado para inscribirlo.",
  ui_story_5045_50451201_142_dialog_content = "Pero Bacon dijo que no iría... Sin embargo, no hay reembolsos por el curso de autoayuda.",
  ui_story_5045_50451201_143_dialog_content = "Entonces, espero que Bacon pueda volver, aunque sea solo para probarlo una vez...",
  ui_story_5045_50451201_144_dialog_content = "Así que Fanny pidió prestado el dinero para Bacon...",
  ui_story_5045_50451201_145_dialog_content = "Además de eso...",
  ui_story_5045_50451201_146_option_content = "Envuélvelo",
  ui_story_5045_50451201_147_dialog_content = "En efecto. No parece que haya pistas más valiosas aquí.",
  ui_story_5045_50451201_148_dialog_content = "Pero esto <color=#1875ad>botella</color> parece bastante intrigante.",
  ui_story_5045_50451201_149_dialog_content = "<color=#737378>Crujido-</color>",
  ui_story_5045_50451201_150_dialog_content = "¿Qué tipo de condimento guardas en esta botella?",
  ui_story_5045_50451201_151_dialog_content = "Oh, eso es de Bacon <color=#1875ad>frasco de medicina</color>!",
  ui_story_5045_50451201_152_dialog_content = "Bacon ha estado recibiendo tratamiento de un médico de la clínica gratuita desde entonces y tiene que tomar medicamentos todos los días.",
  ui_story_5045_50451201_153_dialog_content = "No sé si incluso ha tomado su medicina hoy.",
  ui_story_5045_50451201_154_dialog_content = "Erm, a Bacon realmente no le importa que la gente se preocupe por él.",
  ui_story_5045_50451201_155_dialog_content = "<color=#737378>Hora: 16:00</color>",
  ui_story_5045_50451201_156_dialog_content = "<color=#737378>Ubicación: Bajo Lumopolis, Fuera de la Clínica Gratuita</color>",
  ui_story_5045_50451201_157_dialog_content = "Entonces, fuimos a la casa de Bacon a investigar, pero ahora me siento aún más confundido que nunca.",
  ui_story_5045_50451201_158_dialog_content = "Espero que podamos encontrar alguna información útil aquí.",
  ui_story_5045_50451201_159_dialog_content = "Ey, PlayerName y juez Tina!",
  ui_story_5045_50451201_160_dialog_content = "Raphael, ¿qué estás haciendo aquí?",
  ui_story_5045_50451201_161_dialog_content = "Yo podría preguntarte lo mismo... ¡Aquí es donde trabajo!",
  ui_story_5045_50451201_162_dialog_content = "Creemos que una de las partes de nuestro caso podría ser un paciente aquí, así que vinimos aquí para investigar la situación.",
  ui_story_5045_50451201_163_dialog_content = "Aparte de los alimentos para el desayuno, ¿el nombre Bacon significa algo para ti?",
  ui_story_5045_50451201_164_dialog_content = "¿Tocino? El es mi <color=#1875ad>paciente</color>!",
  ui_story_5045_50451201_165_dialog_content = "¿En realidad? Qué casualidad...",
  ui_story_5045_50451201_166_dialog_content = "Seguro que lo es. Bacon es un paciente al que atendí durante un evento gratuito de divulgación en una clínica.",
  ui_story_5045_50451201_167_dialog_content = "Su condición no ha mostrado ningún signo de mejora. Es realmente muy desconcertante.",
  ui_story_5045_50451201_168_dialog_content = "Pero él no ha venido de visita en tanto tiempo, ahora. Estoy preocupado...",
  ui_story_5045_50451201_169_dialog_content = "¡Esperar! ¿Dijiste que Bacon es tu cliente? ¿Qué le ha pasado? No está en la cárcel, ¿verdad?",
  ui_story_5045_50451201_170_dialog_content = "No te preocupes, no es nada tan grave.",
  ui_story_5045_50451201_171_dialog_content = "¿En realidad? Entonces debe recordarle que venga a mí lo antes posible para una consulta adicional y para recoger su medicamento.",
  ui_story_5045_50451201_172_dialog_content = "Ya debe haber terminado la medicina que le di la última vez.",
  ui_story_5045_50451201_173_dialog_content = "¿Eh? Pero encontramos un frasco de medicina en su casa, y estaba lleno de pastillas...",
  ui_story_5045_50451201_174_dialog_content = "¡De ninguna manera!",
  ui_story_5045_50451201_175_dialog_content = "El medicamento que le di a Bacon solo se administra en pequeñas dosis. Se supone que volverá a mí después de terminarlo todo.",
  ui_story_5045_50451201_176_dialog_content = "¿Podría Fanny haber cometido un error?",
  ui_story_5045_50451201_177_dialog_content = "<color=#737378>Hora: 17:00</color>",
  ui_story_5045_50451201_178_dialog_content = "<color=#737378>Ubicación: Lower Lumopolis, Bacon y Fanny's House</color>",
  ui_story_5045_50451201_179_dialog_content = "<size=45>¡Cielos!</size>",
  ui_story_5045_50451201_180_dialog_content = "¡Shh! Si Fanny ve al médico de Bacon aquí, se preocupará.",
  ui_story_5045_50451201_181_dialog_content = "Que encontraste, Raphael?",
  ui_story_5045_50451201_182_dialog_content = "Estas son las pastillas para dormir que le di a Bacon hace un tiempo.",
  ui_story_5045_50451201_183_dialog_content = "¿Por qué no se llevó a ninguno de ellos?",
  ui_story_5045_50451201_184_dialog_content = "¿Quieres decir que Bacon ha estado acumulando estas pastillas deliberadamente?",
  ui_story_5045_50451201_185_dialog_content = "Realmente no entiendo lo que Bacon podría estar pensando...",
  ui_story_5045_50451201_186_dialog_content = "Raphael, supuestamente, solo supón por un segundo...",
  ui_story_5045_50451201_187_dialog_content = "Supongamos que alguien se tragara todas estas pastillas a la vez... ¿Qué les pasaría?",
  ui_story_5045_50451201_188_dialog_content = "<size=45>¡Guau!</size>",
  ui_story_5045_50451201_189_dialog_content = "¡Todavía tienes mucho por lo que vivir!",
  ui_story_5045_50451201_190_dialog_content = "PlayerName, tengo un mal presentimiento con todo esto...",
  ui_story_5045_50451201_191_dialog_content = "Yo también.",
  ui_story_5045_50451201_192_dialog_content = "Parece que deberíamos comenzar el juicio más temprano que tarde.",
  ui_story_5045_50451201_193_dialog_content = "Pero antes de eso, debo pedirte una cosa, PlayerName.",
  ui_story_5045_50451201_194_dialog_content = "¡Adelante entonces, dilo!",
  ui_story_5045_50451201_195_dialog_content = "Voy... a... dormir... llévame de vuelta...",
  ui_story_5045_50451201_196_dialog_content = "Zzz...",
  ui_story_5045_50451201_197_dialog_content = "...",
  ui_story_5045_50451301_1_dialog_content = "<color=#737378>Hora: 9:00 a.m.</color>",
  ui_story_5045_50451301_2_dialog_content = "<color=#737378>Ubicación: Salón de Justicia Lumo, Sala del Tribunal</color>",
  ui_story_5045_50451301_3_dialog_content = "¿Mmm? Parece que hoy no tenemos público...",
  ui_story_5045_50451301_4_dialog_content = "Después de pensarlo durante mucho tiempo, creo que la audiencia presente puede tener un efecto en las partes involucradas en este caso.",
  ui_story_5045_50451301_5_dialog_content = "Por lo tanto, el caso de hoy no estará abierto al público.",
  ui_story_5045_50451301_6_dialog_content = "¿Eh? ¿Cuándo empezaste a pensar en esto?",
  ui_story_5045_50451301_7_dialog_content = "Tal vez fue anoche cuando volviste conmigo durmiendo boca arriba.",
  ui_story_5045_50451301_8_dialog_content = "Tú significas tú...",
  ui_story_5045_50451301_9_option_content = "¿¡Todavía estabas trabajando mientras dormías!?",
  ui_story_5045_50451301_10_dialog_content = "Sí, sueño mucho.",
  ui_story_5045_50451301_11_dialog_content = "A veces incluso puedo pensar en soluciones en mis sueños para problemas que nunca podría manejar en mi vida de vigilia.",
  ui_story_5045_50451301_12_dialog_content = "Comparado con tu vida de vigilia, tus sueños suenan agotadores...",
  ui_story_5045_50451301_13_dialog_content = "Jejeje, sabía que lo entenderías, PlayerName.",
  ui_story_5045_50451301_14_dialog_content = "Leyn nunca ha sido tan amable conmigo como tú.",
  ui_story_5045_50451301_15_dialog_content = "¿D-De verdad...?",
  ui_story_5045_50451301_16_option_content = "En realidad eres bastante confiable.",
  ui_story_5045_50451301_17_dialog_content = "Ajá, naturalmente.",
  ui_story_5045_50451301_18_dialog_content = "La confiabilidad es el requisito mínimo en esta profesión.",
  ui_story_5045_50451301_19_dialog_content = "¡Esperar! Entonces, en tu mente, ¿siempre me has visto como poco confiable?",
  ui_story_5045_50451301_20_dialog_content = "Yo...",
  ui_story_5045_50451301_21_option_content = "¿Estabas fingiendo estar dormido?",
  ui_story_5045_50451301_22_dialog_content = "Hmm... Parece que todavía estás muy atrasado. Leyn cuando se trata de ser considerado con tu pareja, PlayerName.",
  ui_story_5045_50451301_23_dialog_content = "(¿Estoy imaginando cosas, o es Tina mirándome de repente con un aire de disgusto?)",
  ui_story_5045_50451301_24_dialog_content = "(Parece que mi respuesta ha hecho temblar la confianza entre nosotros...)",
  ui_story_5045_50451301_25_dialog_content = "Pero no importa eso, tenemos que empezar el juicio pronto.",
  ui_story_5045_50451301_26_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451301_27_dialog_content = "<size=45>Noche Blanca en lo alto. ¡La corte está ahora en sesión!</size>",
  ui_story_5045_50451301_28_dialog_content = "En primer lugar llamo a la recurrente Fanny para que rinda su declaración.",
  ui_story_5045_50451301_29_dialog_content = "Gracias, Su Señoría. No puedo aceptar la sentencia de divorcio del primer juicio.",
  ui_story_5045_50451301_30_dialog_content = "No estoy de acuerdo con que mi relación con Bacon se haya roto, por lo que no quiero el divorcio.",
  ui_story_5045_50451301_31_dialog_content = "Fanny, detén esto...",
  ui_story_5045_50451301_32_dialog_content = "Sólo déjame ir, por favor.",
  ui_story_5045_50451301_33_dialog_content = "Bacon, todavía insistes en que tu relación se ha roto, ¿correcto?",
  ui_story_5045_50451301_34_dialog_content = "Correcto, Su Señoría.",
  ui_story_5045_50451301_35_dialog_content = "Pero...",
  ui_story_5045_50451301_36_dialog_content = "Tus acciones prueban que has estado <color=#1875ad>protegiendo los mejores intereses de Fanny</color> ¡todo el tiempo!",
  ui_story_5045_50451301_37_dialog_content = "PlayerName, ¿qué te hace decir esto de repente?",
  ui_story_5045_50451301_38_dialog_content = "M-Mi error!",
  ui_story_5045_50451301_39_dialog_content = "Lo que en realidad quería decir era...",
  ui_story_5045_50451301_40_dialog_content = "Tina, ¡mira esto!",
  ui_story_5045_50451301_41_dialog_content = "Hmm, tus registros son realmente muy detallados.",
  ui_story_5045_50451301_42_dialog_content = "Pero, ¿por qué esta escena parece tan familiar? ¿No vi todo esto en un sueño?",
  ui_story_5045_50451301_43_dialog_content = "No he tenido pesadillas últimamente... ¡así que la prueba de hoy debería ser un éxito!",
  ui_story_5045_50451301_44_dialog_content = "Por otra parte, ¿sacaste esto de repente solo para complacer tu ego?",
  ui_story_5045_50451301_45_dialog_content = "Eso no es todo. Lo que en realidad quería decir era...",
  ui_story_5045_50451301_46_dialog_content = "¡Le estás dejando toda tu propiedad a Fanny y asumiendo todas tus deudas tú mismo! ¿Qué más necesito decir?",
  ui_story_5045_50451301_47_dialog_content = "E-Esto no tiene nada que ver con la ruptura de nuestro matrimonio.",
  ui_story_5045_50451301_48_dialog_content = "Voy a entregarle toda nuestra propiedad a Fanny como compensación por su arduo trabajo en casa durante los últimos siete años.",
  ui_story_5045_50451301_49_dialog_content = "Simplemente deseo cambiar esto por mi libertad... eso es todo.",
  ui_story_5045_50451301_50_dialog_content = "¿Eso es todo?",
  ui_story_5045_50451301_51_dialog_content = "Realmente ya no me amas, ¿verdad...?",
  ui_story_5045_50451301_52_dialog_content = "Así es, ahora por favor deja de molestarme.",
  ui_story_5045_50451301_53_dialog_content = "Boo-hoo... ¿Por qué? ¿¡Por que me estas haciendo esto!?",
  ui_story_5045_50451301_54_dialog_content = "Fanny, todavía tenemos que llevar este caso a un grado satisfactorio de claridad. No te preocupes por eso todavía.",
  ui_story_5045_50451301_55_dialog_content = "Su Señoría, si así es como se siente Bacon, realmente no quiero molestarlo más.",
  ui_story_5045_50451301_56_dialog_content = "¿Tiene algún sentido alargar más este juicio?",
  ui_story_5045_50451301_57_dialog_content = "¡Sí! ¡Por supuesto que lo hay!",
  ui_story_5045_50451301_58_dialog_content = "¿Mmm? ¿Por qué de repente pareces tan emocionado, PlayerName?",
  ui_story_5045_50451301_59_dialog_content = "Creo que las dos partes aún se aman...",
  ui_story_5045_50451301_60_dialog_content = "Bueno, ¿qué planeas hacer a continuación?",
  ui_story_5045_50451301_61_dialog_content = "Yo... no sé...",
  ui_story_5045_50451301_62_dialog_content = "Jaja, solo mira y aprende entonces.",
  ui_story_5045_50451301_63_dialog_content = "Ejem, encontramos algunas cosas peculiares durante nuestra investigación.",
  ui_story_5045_50451301_64_dialog_content = "Si no puede explicarlos claramente, es posible que se enfrente a algo más que un juicio en la División de Romance.",
  ui_story_5045_50451301_65_dialog_content = "Una de las cosas extrañas mencionadas es <color=#1875ad>la cosa Raphael comprobado ayer</color>. Ella debe querer decir...",
  ui_story_5045_50451301_66_dialog_content = "Eso no es todo. Piensa otra vez, PlayerName.",
  ui_story_5045_50451301_67_dialog_content = "¡Entendido!",
  ui_story_5045_50451301_68_dialog_content = "Bacon, ¿reconoces esto?",
  ui_story_5045_50451301_69_dialog_content = "Bueno...",
  ui_story_5045_50451301_70_dialog_content = "¿Puede decirnos qué tipo de medicamento hay en este frasco?",
  ui_story_5045_50451301_71_dialog_content = "E-Esta es la medicina para dormir que me recetó mi médico.",
  ui_story_5045_50451301_72_dialog_content = "Conocimos a tu médico de la clínica gratuita Raphael ayer.",
  ui_story_5045_50451301_73_dialog_content = "Según ella, solo te da una pequeña dosis de pastillas para dormir cada vez que la ves.",
  ui_story_5045_50451301_74_dialog_content = "Parece que ha estado almacenando las píldoras en secreto sin decirle a su médico.",
  ui_story_5045_50451301_75_dialog_content = "Con una dosis tan grande de pastillas para dormir a tu disposición... ¿podría ser que planeas envenenar a tu esposa?",
  ui_story_5045_50451301_76_dialog_content = "<size=45>¿¡Qué!?</size>",
  ui_story_5045_50451301_77_dialog_content = "Fanny, no, eso no es! No quería envenenar a nadie...",
  ui_story_5045_50451301_78_dialog_content = "Entonces, ¿por qué guardaste deliberadamente estas pastillas para dormir?",
  ui_story_5045_50451301_79_dialog_content = "...",
  ui_story_5045_50451301_80_dialog_content = "No tiene nada que ver con el divorcio.",
  ui_story_5045_50451301_81_dialog_content = "Bacon, realmente has cambiado. ya no se quien eres...",
  ui_story_5045_50451301_82_dialog_content = "Coño...",
  ui_story_5045_50451301_83_dialog_content = "Tina, ¿qué debemos hacer ahora?",
  ui_story_5045_50451301_84_dialog_content = "Si Bacon no derrama los frijoles, no hay nada que podamos hacer.",
  ui_story_5045_50451301_85_dialog_content = "¿Puedes pensar en algún punto cuestionable que aún no hayamos aclarado?",
  ui_story_5045_50451301_86_dialog_content = "¡Todo el caso es un gran punto cuestionable!",
  ui_story_5045_50451301_87_dialog_content = "Mmm, ahora que lo pienso...",
  ui_story_5045_50451301_88_dialog_content = "El <color=#1875ad>DIRECCIÓN</color>!",
  ui_story_5045_50451301_89_dialog_content = "¿Que direccion?",
  ui_story_5045_50451301_90_dialog_content = "No... Cierto, ¡esto es todo!",
  ui_story_5045_50451301_91_dialog_content = "Hay una dirección en el reverso de esta foto que aún no hemos investigado por completo.",
  ui_story_5045_50451301_92_dialog_content = "¡Oh! Así es, me acabas de recordar. ¡Invité a un testigo!",
  ui_story_5045_50451301_93_dialog_content = "¿Cuándo invitaste a un testigo? ¿Fue también durante tu sueño?",
  ui_story_5045_50451301_94_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451301_95_dialog_content = "Ahora, me gustaría pedirle a un testigo <color=#1875ad>Michenny</color> para tomar el estrado.",
  ui_story_5045_50451301_96_dialog_content = "Buenos días a todos. soy el recaudador de impuestos, Michenny.",
  ui_story_5045_50451301_97_dialog_content = "¿Reconoces la dirección escrita a mano en el reverso de esta foto?",
  ui_story_5045_50451301_98_dialog_content = "Se trata de un nuevo tipo de organización que proporciona <color=#1875ad>servicios de seguros</color>.",
  ui_story_5045_50451301_99_dialog_content = "Bacon, el demandante en este caso, compró <color=#1875ad>seguro de vida</color> por sí mismo de esta agencia de seguros.",
  ui_story_5045_50451301_100_dialog_content = "Si Bacon es víctima de muerte o lesiones accidentales, un <color=#1875ad>gran reclamo</color> se puede hacer a la agencia de seguros.",
  ui_story_5045_50451301_101_dialog_content = "Si eso sucede, ¿quién recibirá el pago?",
  ui_story_5045_50451301_102_dialog_content = "Según la agencia, esta información es confidencial.",
  ui_story_5045_50451301_103_dialog_content = "Pero si esta información es vital para el caso, la ley establece que tenemos derecho a esta información.",
  ui_story_5045_50451301_104_dialog_content = "Muy bien... ¡Muchas gracias!",
  ui_story_5045_50451301_105_dialog_content = "Bueno, me despediré entonces.",
  ui_story_5045_50451301_106_dialog_content = "Señoría, ¿qué quiere decir con esto?",
  ui_story_5045_50451301_107_dialog_content = "¿Podría ser realmente que... Bacon preparó todas estas pastillas para sí mismo?",
  ui_story_5045_50451301_108_dialog_content = "¿Planeaba dejarle un gran pago de seguro a alguien?",
  ui_story_5045_50451301_109_dialog_content = "Bacon, ¿te das cuenta de que este tipo de comportamiento podría llevarte a prisión?",
  ui_story_5045_50451301_110_dialog_content = "Dicen que ser enviado a la prisión de Lumopolis es un destino peor que la muerte.",
  ui_story_5045_50451301_111_dialog_content = "...",
  ui_story_5045_50451301_112_dialog_content = "Yo...",
  ui_story_5045_50451301_113_dialog_content = "No te preocupes. Si confiesa ahora, lo trataremos con indulgencia.",
  ui_story_5045_50451301_114_dialog_content = "Bacon, ¿qué estabas planeando?",
  ui_story_5045_50451301_115_dialog_content = "Dígale al juez rápidamente. Esto es lo último que te pediré como esposa.",
  ui_story_5045_50451301_116_dialog_content = "Fany, lo siento.",
  ui_story_5045_50451301_117_dialog_content = "Lo planeé durante tanto tiempo, me engañé a mí mismo e incluso te engañé a ti, pero al final... todavía fallé.",
  ui_story_5045_50451301_118_dialog_content = "Qué has hecho...?",
  ui_story_5045_50451301_119_dialog_content = "Señoría, yo era jardinero y trabajaba para una casa noble.",
  ui_story_5045_50451301_120_dialog_content = "Fue porque accidentalmente rompí el amado plato de porcelana del maestro que me despidieron.",
  ui_story_5045_50451301_121_dialog_content = "Debido a esto, me convertí en el hazmerreír de los sirvientes, y nadie pensaría siquiera en contratarme...",
  ui_story_5045_50451301_122_dialog_content = "Me escondí en casa, cada vez con más miedo de salir de casa y sin esperanza para el futuro.",
  ui_story_5045_50451301_123_dialog_content = "Después de esto, a medida que se acumulaban nuestras deudas, Fanny comenzó a trabajar más y más.",
  ui_story_5045_50451301_124_dialog_content = "Debería ser yo quien protegiera a Fanny, protegiera nuestro hogar, pero no pude hacer nada...",
  ui_story_5045_50451301_125_dialog_content = "Fue entonces cuando me encontré con esa nueva agencia de seguros.",
  ui_story_5045_50451301_126_dialog_content = "Estaba pensando que en lugar de ser una carga para Fanny, sería mejor si...",
  ui_story_5045_50451301_127_dialog_content = "¡Tonto! ¡Nunca he pensado en ti como una carga! ¡Nunca!",
  ui_story_5045_50451301_128_dialog_content = "Es todo porque yo era demasiado codicioso.",
  ui_story_5045_50451301_129_dialog_content = "Pensé que si me divorciaba de Fanny, podría asumir toda nuestra deuda.",
  ui_story_5045_50451301_130_dialog_content = "Luego, después de mi muerte, la deuda también sería cancelada.",
  ui_story_5045_50451301_131_dialog_content = "Al final, resulta que soy demasiado inútil para hacer tanto.",
  ui_story_5045_50451301_132_dialog_content = "Tocino, déjame decirte algo.",
  ui_story_5045_50451301_133_dialog_content = "Si tuviera que terminar con su propia vida, la compañía de seguros negaría el reclamo.",
  ui_story_5045_50451301_134_dialog_content = "¿¡R-En serio!?",
  ui_story_5045_50451301_135_dialog_content = "Si hicieras tal cosa, solo dejarías a Fanny con una tonelada de deudas y un dolor sin fin.",
  ui_story_5045_50451301_136_dialog_content = "Cielos, ¿qué he hecho?",
  ui_story_5045_50451301_137_dialog_content = "¡Fani, lo siento! Lo lamento...",
  ui_story_5045_50451301_138_dialog_content = "Al final, todavía no pude darte una vida feliz.",
  ui_story_5045_50451301_139_dialog_content = "Tocino, ¿de qué estás hablando?",
  ui_story_5045_50451301_140_dialog_content = "Siempre he sido feliz contigo.",
  ui_story_5045_50451301_141_dialog_content = "...",
  ui_story_5045_50451301_142_dialog_content = "¿Recuerdas el plato de barro que hicimos nosotros mismos?",
  ui_story_5045_50451301_143_dialog_content = "yo recuerdo eso <color=#1875ad>plato de arcilla</color>!",
  ui_story_5045_50451301_144_dialog_content = "PlayerName, no hagas esto más complicado de lo que ya es.",
  ui_story_5045_50451301_145_dialog_content = "Lo siento, pero creo...",
  ui_story_5045_50451301_146_dialog_content = "¿Es este el plato roto?",
  ui_story_5045_50451301_147_dialog_content = "Lo recuerdo, era de cuando nos casamos...",
  ui_story_5045_50451301_148_dialog_content = "¿Está Bacon a punto de recordar la alegría de todo su período de luna de miel aquí en la corte?",
  ui_story_5045_50451301_149_dialog_content = "¡Cállate!",
  ui_story_5045_50451301_150_dialog_content = "Lo siento...",
  ui_story_5045_50451301_151_dialog_content = "Fanny, ¿por qué te disculpas?",
  ui_story_5045_50451301_152_dialog_content = "Quería sorprenderte con la cena, pero accidentalmente rompí nuestros platos...",
  ui_story_5045_50451301_153_dialog_content = "¡Jajaja! ¿Por qué te disculpaste por eso?",
  ui_story_5045_50451301_154_dialog_content = "Ni siquiera puedo recordar cuánto tiempo se usaron esos platos. Ya es hora de que los reemplacemos.",
  ui_story_5045_50451301_155_dialog_content = "Pero... no tenemos dinero ahora mismo.",
  ui_story_5045_50451301_156_dialog_content = "Podemos hacer algunos nosotros mismos.",
  ui_story_5045_50451301_157_dialog_content = "¿Nosotros mismos? ¿Cómo?",
  ui_story_5045_50451301_158_dialog_content = "Sígueme!",
  ui_story_5045_50451301_159_dialog_content = "Jajaja, pensé que Bacon había conocido a un tendero que podría ayudarnos con algunos platos.",
  ui_story_5045_50451301_160_dialog_content = "Inesperadamente, me llevó al desierto.",
  ui_story_5045_50451301_161_dialog_content = "Señalando la arcilla del río, dijo que me haría algo de magia.",
  ui_story_5045_50451301_162_dialog_content = "Podemos moldear esta arcilla en la forma que queramos, luego hornearla en el fuego....",
  ui_story_5045_50451301_163_dialog_content = "... y tendremos nuestros propios platos.",
  ui_story_5045_50451301_164_dialog_content = "¡Guau, mi esposo es increíble!",
  ui_story_5045_50451301_165_dialog_content = "Je, aunque este plato es un poco feo.",
  ui_story_5045_50451301_166_dialog_content = "El mío se ve peor.",
  ui_story_5045_50451301_167_dialog_content = "¡Pero estos son nuestros exclusivos platos de arcilla! No importa cuánto los quieran esos nobles, ¡no pueden tenerlos!",
  ui_story_5045_50451301_168_dialog_content = "En ese momento, no teníamos nada, pero éramos muy felices.",
  ui_story_5045_50451301_169_dialog_content = "Ahora tenemos casa propia, aunque estamos endeudados...",
  ui_story_5045_50451301_170_dialog_content = "¡Pero aún podemos estar sanos y felices juntos, que es algo que ninguna cantidad de Nightium puede comprar!",
  ui_story_5045_50451301_171_dialog_content = "Coño...",
  ui_story_5045_50451301_172_dialog_content = "Todo va a estar bien.",
  ui_story_5045_50451301_173_dialog_content = "Esta es la verdad que me enseñaste y me hiciste creer a través de tus acciones.",
  ui_story_5045_50451301_174_dialog_content = "¿Me creerás esta vez, Bacon?",
  ui_story_5045_50451301_175_dialog_content = "...Sí.",
  ui_story_5045_50451301_176_dialog_content = "Parece que este caso ya ha llegado a su fin.",
  ui_story_5045_50451301_177_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451301_178_dialog_content = "Noche Blanca en lo alto. ¡Es hora del veredicto!",
  ui_story_5045_50451301_179_dialog_content = "En primer lugar, Bacon y Fanny, a lo largo de este juicio, demostraron el amor que existe entre ellos.",
  ui_story_5045_50451301_180_dialog_content = "En segundo lugar, aunque Bacon tuvo la intención de cometer fraude de seguros, se le impondrá una pena más leve, ya que no ejecutó su plan y mostró la sinceridad de su arrepentimiento.",
  ui_story_5045_50451301_181_dialog_content = "¡Por lo tanto, hemos llegado al siguiente juicio!",
  ui_story_5045_50451301_182_dialog_content = "El estado civil de Bacon y Fanny continuará inalterado.",
  ui_story_5045_50451301_183_dialog_content = "La medicina acumulada de Bacon será confiscada. Se le hará ver a un médico regularmente y tomar su medicina en los días siguientes a estas visitas.",
  ui_story_5045_50451301_184_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451301_185_dialog_content = "¡El juicio ha terminado!",
  ui_story_5045_50451401_1_dialog_content = "<color=#737378>Hora: 14:00</color>",
  ui_story_5045_50451401_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50451401_3_dialog_content = "Bostezo-",
  ui_story_5045_50451401_4_dialog_content = "¿Estas despierto?",
  ui_story_5045_50451401_5_dialog_content = "He seleccionado algunos resúmenes de casos. Tina, veamos qué caso debemos mirar primero.",
  ui_story_5045_50451401_6_dialog_content = "Nada mal, PlayerName.",
  ui_story_5045_50451401_7_dialog_content = "Eres muy proactivo en tu trabajo. Quizás deberías quedarte y ser mi asistente en el futuro.",
  ui_story_5045_50451401_8_dialog_content = "Erm.",
  ui_story_5045_50451401_9_dialog_content = "Su Señoría.",
  ui_story_5045_50451401_10_dialog_content = "¿¡Eh!?",
  ui_story_5045_50451401_11_dialog_content = "¿Tocino? ¿Y Fanny también? ¿Qué estás haciendo aquí atrás?",
  ui_story_5045_50451401_12_dialog_content = "¿Ha surgido otro problema?",
  ui_story_5045_50451401_13_dialog_content = "Nada de eso, Su Señoría. Estamos aquí para agradecerles a ambos.",
  ui_story_5045_50451401_14_dialog_content = "Después del juicio, fue como si acabara de despertar de un sueño...",
  ui_story_5045_50451401_15_dialog_content = "Me di cuenta de que casi cometí un gran error, y también les causé muchos problemas a ustedes dos.",
  ui_story_5045_50451401_16_dialog_content = "De nada. Fue un honor para nosotros ayudarlo.",
  ui_story_5045_50451401_17_dialog_content = "¡Y no siento que nos hayas traído ningún problema!",
  ui_story_5045_50451401_18_dialog_content = "(Porque yo hice todo el trabajo duro...)",
  ui_story_5045_50451401_19_dialog_content = "PlayerName, ¿tienes algo que quieras decirle a Bacon?",
  ui_story_5045_50451401_20_dialog_content = "Oh, cierto, yo quería <color=#1875ad>decir</color> tu algo...",
  ui_story_5045_50451401_21_dialog_content = "El caso ha terminado. ¿Por qué sigues preguntando sobre esto?",
  ui_story_5045_50451401_22_dialog_content = "Raphael ha estado preocupado por ti.",
  ui_story_5045_50451401_23_dialog_content = "A pesar de Raphael parece una niña, y sus técnicas de tratamiento pueden parecer un poco toscas...",
  ui_story_5045_50451401_24_dialog_content = "¡Pero sus habilidades médicas son excelentes!",
  ui_story_5045_50451401_25_dialog_content = "Entiendo... Me disculparé con el Dr. Raphael también.",
  ui_story_5045_50451401_26_dialog_content = "Si está dispuesta a darme otra oportunidad, aceptaré su tratamiento.",
  ui_story_5045_50451401_27_dialog_content = "Bacon, Fanny, ¿cuáles son sus planes para el futuro?",
  ui_story_5045_50451401_28_dialog_content = "No estoy seguro, pero vamos a intentar hacer un trabajo de medio tiempo juntos primero y pagar nuestras deudas poco a poco.",
  ui_story_5045_50451401_29_dialog_content = "Además, yendo a la <color=#1875ad>curso de autoayuda</color> podría ayudarme a encontrar una nueva dirección en la vida.",
  ui_story_5045_50451401_30_dialog_content = "¡Eso suena muy alentador!",
  ui_story_5045_50451401_31_dialog_content = "Pero, ¿qué pasa con todo este equipaje? ¿Te mudas de casa?",
  ui_story_5045_50451401_32_dialog_content = "Estas son nuestras herramientas de cerámica.",
  ui_story_5045_50451401_33_dialog_content = "Nos dirigimos al campo más tarde para hacer algunos platos nuevos.",
  ui_story_5045_50451401_34_dialog_content = "¡Guau! ¿Reviviendo los buenos viejos tiempos?",
  ui_story_5045_50451401_35_dialog_content = "Ejem... Podrías decir eso.",
  ui_story_5045_50451401_36_dialog_content = "Yo tengo la culpa de romper nuestro recuerdo más preciado.",
  ui_story_5045_50451401_37_dialog_content = "Es justo que lo compense.",
  ui_story_5045_50451401_38_dialog_content = "¡Eso es tan dulce!",
  ui_story_5045_50451401_39_option_content = "¿Es un indicio de envidia lo que detecto, Tina?",
  ui_story_5045_50451401_40_dialog_content = "Hmm... ¿Hay algo extraño en admirar la belleza del amor?",
  ui_story_5045_50451401_41_dialog_content = "¡Si a Sus Señorías no les importa, haremos más platos pequeños para ustedes dos!",
  ui_story_5045_50451401_42_dialog_content = "Nos encantaría, pero como jueces, no podemos aceptar regalos de nuestros clientes.",
  ui_story_5045_50451401_43_dialog_content = "Los platos de barro que hacemos son de muy poco valor...",
  ui_story_5045_50451401_44_dialog_content = "Agradecemos su amabilidad, pero en mi opinión, sus platos no tienen precio.",
  ui_story_5045_50451401_45_dialog_content = "Gracias, Su Señoría... Bueno, ya hemos tomado suficiente de su tiempo.",
  ui_story_5045_50451401_46_dialog_content = "Suspiro, realmente espero que algún día, mi novia me lleve a hacer algo igual de romántico.",
  ui_story_5045_50451401_47_dialog_content = "Pero todavía es tiempo de trabajo, PlayerName, vuelve a tu trabajo...",
  ui_story_5045_50451401_47X1_dialog_content = "Como socios, hay espacio para nuestros <color=#1875ad>Compenetración</color> ¡mejorar!",
  ui_story_5045_50451401_48_dialog_content = "¿Y tú?",
  ui_story_5045_50451401_49_dialog_content = "Necesito recuperar algo de sueño, por supuesto. ¡Podría haber algunos dulces sueños esperándome si me duermo con un corazón feliz!",
  ui_story_5045_50451401_50_dialog_content = "Qué-?!",
  ui_story_5045_50451401_51_option_content = "Vamos juntos!",
  ui_story_5045_50451401_52_dialog_content = "¿Ah?",
  ui_story_5045_50451401_53_dialog_content = "Ah, lo siento... Olvidé que todavía es hora de trabajar.",
  ui_story_5045_50451401_54_dialog_content = "Entonces, ¡vamos!",
  ui_story_5045_50451401_55_dialog_content = "Muy bien, solo voy a—",
  ui_story_5045_50451401_56_dialog_content = "¿Eh? ¿Ella se ha ido?",
  ui_story_5045_50451401_57_dialog_content = "<color=#737378>Hora: 21:00</color>",
  ui_story_5045_50451401_58_dialog_content = "<color=#737378>Ubicación: Afueras de Lumopolis</color>",
  ui_story_5045_50451401_59_dialog_content = "Una vez que esté todo listo, puedes ponerlo al fuego para hornearlo.",
  ui_story_5045_50451401_60_dialog_content = "Tina, ¿Qué estás haciendo?",
  ui_story_5045_50451401_61_dialog_content = "Espera un segundo, te lo mostraré muy pronto.",
  ui_story_5045_50451401_62_dialog_content = "No te preocupes por eso, el mío se ve horrible. Te prometo que no me reiré de los tuyos.",
  ui_story_5045_50451401_63_dialog_content = "Estoy muy satisfecho con mi obra maestra, solo que aún no la he terminado—",
  ui_story_5045_50451401_64_dialog_content = "Je... ¡Jajaja!",
  ui_story_5045_50451401_65_dialog_content = "¿Q-Qué es?",
  ui_story_5045_50451401_66_dialog_content = "PlayerName, tu plato es realmente horrible y tu cara está cubierta de arcilla.",
  ui_story_5045_50451401_67_dialog_content = "¿Estabas tratando de convertirte en una escultura de arcilla?",
  ui_story_5045_50451401_68_dialog_content = "R-¿En serio? Ni siquiera me di cuenta...",
  ui_story_5045_50451401_69_dialog_content = "Pero podría decir lo mismo de ti...",
  ui_story_5045_50451401_70_dialog_content = "¿¡Qué!?",
  ui_story_5045_50451401_71_dialog_content = "No importa. ¡La apariencia no es importante mientras sea para mi obra maestra!",
  ui_story_5045_50451401_72_dialog_content = "Esa cosa que estás sosteniendo es tu... ¿obra maestra?",
  ui_story_5045_50451401_73_dialog_content = "¡Así es, jejeje!",
  ui_story_5045_50451401_74_dialog_content = "No lo entiendo... ¿Qué se supone que es?",
  ui_story_5045_50451401_75_dialog_content = "¿Qué hay que no conseguir? Mira cuidadosamente...",
  ui_story_5045_50451401_76_dialog_content = "Este es un niño y esta es una niña.",
  ui_story_5045_50451401_77_dialog_content = "Se aman profundamente. Mirándose a los ojos con cariño, desean ofrecerse el beso más dulce el uno al otro...",
  ui_story_5045_50451401_78_dialog_content = "Ejem... Hice este pequeño adorno, especialmente para la División Romance.",
  ui_story_5045_50451401_79_dialog_content = "Entonces, se supone que son dos figuritas de arcilla...",
  ui_story_5045_50451401_80_dialog_content = "Estas dos figuritas de arcilla son tan lindas. ¿Por qué no se me ocurrió hacer unos pequeños adornos?",
  ui_story_5045_50451401_81_dialog_content = "Sabes, esta figurita de arcilla parece un poco familiar...",
  ui_story_5045_50451401_82_dialog_content = "Jaja, ¿no crees que se parecen a los dos jueces?",
  ui_story_5045_50451401_83_dialog_content = "¿Qué?",
  ui_story_5045_50451401_84_option_content = "No me parece.",
  ui_story_5045_50451401_85_dialog_content = "Así es, ¡ellos no somos nosotros!",
  ui_story_5045_50451401_86_dialog_content = "Son solo un niño y una niña al azar que junté casualmente.",
  ui_story_5045_50451401_87_dialog_content = "Espero que todos los amantes de Lumopolis sean bendecidos por el Dios de la Luz.",
  ui_story_5045_50451401_88_dialog_content = "Al menos entonces la División de Romance no estaría tan terriblemente ocupada como lo está ahora...",
  ui_story_5045_50451401_89_dialog_content = "Si estamos tan ocupados, ¿por qué me llevaste a perder el tiempo en el campo?",
  ui_story_5045_50451401_90_dialog_content = "Porque...",
  ui_story_5045_50451401_91_dialog_content = "¿Eh? ¿Porque que?",
  ui_story_5045_50451401_92_option_content = "Puedo ver el parecido.",
  ui_story_5045_50451401_93_dialog_content = "¿En serio?",
  ui_story_5045_50451401_94_dialog_content = "¿¡Dónde!? ¡Yo no lo veo!",
  ui_story_5045_50451401_95_dialog_content = "¿Quiénes se supone que son entonces?",
  ui_story_5045_50451401_96_dialog_content = "Nadie en particular.",
  ui_story_5045_50451401_97_dialog_content = "¡Estas dos figurillas de arcilla son encarnaciones abstractas de todos los amantes del mundo!",
  ui_story_5045_50451401_98_dialog_content = "Solo quiero que todos experimenten un amor verdaderamente hermoso.",
  ui_story_5045_50451401_99_dialog_content = "Espero que duren mucho, mucho tiempo.",
  ui_story_5045_50451401_100_dialog_content = "Tina, te encanta trabajar en la División de Romance, ¿verdad?",
  ui_story_5045_50451401_101_dialog_content = "A decir verdad, no importa dónde trabajo.",
  ui_story_5045_50451401_102_dialog_content = "Sin embargo, no puedo negar que mis casos recientes en la División de Romance son realmente más interesantes que cualquier cosa que haya encontrado antes.",
  ui_story_5045_50451401_103_dialog_content = "Si no fuera por tu ayuda...",
  ui_story_5045_50451401_104_dialog_content = "Puede que no supiera cómo manejar los casos de la División de Romance.",
  ui_story_5045_50451401_105_dialog_content = "¿Por qué dices eso? Eres un juez fenomenal.",
  ui_story_5045_50451401_106_dialog_content = "Pero mi comprensión del amor era muy deficiente.",
  ui_story_5045_50451401_107_dialog_content = "Siempre me gustó la gente sin razón aparente, pero al final me di cuenta de que solo me gustaba la impresión que me había formado de ellos en mi imaginación.",
  ui_story_5045_50451401_108_dialog_content = "Parece un sentimiento tan tonto ahora.",
  ui_story_5045_50451401_109_dialog_content = "Amor verdadero...",
  ui_story_5045_50451401_110_dialog_content = "Es ayudarse mutuamente en las buenas y en las malas, luchando contra la mundanidad de la vida.",
  ui_story_5045_50451401_111_dialog_content = "Es la necesidad de cuidarse unos a otros, en lugar de someterse unos a otros.",
  ui_story_5045_50451401_112_dialog_content = "Bien. Tenemos que agradecer a Fanny y Bacon por enseñarnos esto.",
  ui_story_5045_50451401_113_dialog_content = "También me gustaría agradecerte, PlayerName.",
  ui_story_5045_50451401_114_dialog_content = "me ayudaste a verlo...",
  ui_story_5045_50451401_115_dialog_content = "¿Eh? ¿Mira qué?",
  ui_story_5045_50451401_116_dialog_content = "Zzz...",
  ui_story_5045_50451401_117_dialog_content = "¿Ella está durmiendo?",
  ui_story_5045_50451401_118_dialog_content = "Lo que era Tina a punto de decir?",
  ui_story_5045_50451401_119_dialog_content = "Supongo que no recibiré ninguna respuesta hoy... Buenas noches, entonces.",
  ui_story_5045_50451401_120_dialog_content = "...",
  ui_story_5045_50451401_121_dialog_content = "Creo Tina está soñando.",
  ui_story_5045_50451401_122_dialog_content = "PlayerName, ¡recuerda ayudarme a guardar mi obra maestra!",
  ui_story_5045_50451401_123_dialog_content = "¡E-está bien!",
  ui_story_5045_50451401_124_dialog_content = "¿Eh? ¿Está hablando en sueños?",
  ui_story_5045_50451401_125_dialog_content = "Tina realmente no holgazanea cuando está soñando...",
  ui_story_5045_50451501_1_dialog_content = "<color=#737378>Hora: 15:00</color>",
  ui_story_5045_50451501_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50451501_3_dialog_content = "(Nunca pensé que terminaría un caso tan pronto).",
  ui_story_5045_50451501_4_dialog_content = "(Mis habilidades legales no pueden ser mejores que mis habilidades psíquicas, ¿o sí?)",
  ui_story_5045_50451501_5_dialog_content = "(Si Irridon vio nuestro juicio, podría pensar en pagarme más).",
  ui_story_5045_50451501_6_dialog_content = "(Cuando llegue el momento, je, le daré Vice y los demás una sorpresa!)",
  ui_story_5045_50451501_7_dialog_content = "(Pero entonces de nuevo...)",
  ui_story_5045_50451501_8_dialog_content = "¿¡Por qué tanta gente presenta hoy!?",
  ui_story_5045_50451501_9_dialog_content = "¿Eh? ¿Perdió interés en el trabajo de prueba tan pronto?",
  ui_story_5045_50451501_10_dialog_content = "¡N-De ninguna manera!",
  ui_story_5045_50451501_11_dialog_content = "Ah, ¿qué trae a nuestra siempre ocupada Señora Irridon ¿aquí?",
  ui_story_5045_50451501_12_dialog_content = "Zzz...",
  ui_story_5045_50451501_13_dialog_content = "Tina, ¡despertar!",
  ui_story_5045_50451501_14_dialog_content = "Cierto...",
  ui_story_5045_50451501_15_dialog_content = "Angel, ¿Que estas esperando? ¡Ve y prepara un poco de té para nuestro estimado juez principal!",
  ui_story_5045_50451501_16_dialog_content = "... Vaya.",
  ui_story_5045_50451501_17_dialog_content = "No hay necesidad.",
  ui_story_5045_50451501_18_dialog_content = "Escuché que juzgaste un caso esta mañana, así que vine a evaluar las consecuencias.",
  ui_story_5045_50451501_19_dialog_content = "El caso fue llevado por el libro.",
  ui_story_5045_50451501_20_dialog_content = "Por el contrario, mi juicio mañana inspirará al mundo y se convertirá en un precedente para que las generaciones futuras aprendan e imiten.",
  ui_story_5045_50451501_21_dialog_content = "Cuando llegue el momento, siéntete libre de volver y atestiguarlo por ti mismo.",
  ui_story_5045_50451501_22_dialog_content = "Ya veremos. Tal vez, si tengo tiempo.",
  ui_story_5045_50451501_23_dialog_content = "Acabo de enterarme de que el caso de esta mañana causó un gran revuelo. Quiero saber los detalles.",
  ui_story_5045_50451501_24_dialog_content = "Dama Irridon, PlayerName y probé el caso de esta mañana.",
  ui_story_5045_50451501_25_dialog_content = "Anoté los detalles y el proceso del juicio en este cuaderno. Por favor échale un vistazo.",
  ui_story_5045_50451501_26_dialog_content = "Impresionante. Has formado algunos buenos hábitos desde que llegaste aquí, PlayerName.",
  ui_story_5045_50451501_27_dialog_content = "¿Acabas de decir que este caso causó revuelo?",
  ui_story_5045_50451501_28_dialog_content = "En seguida.",
  ui_story_5045_50451501_29_dialog_content = "Entonces, ¿cómo se encuentra actualmente la opinión pública con respecto a este caso?",
  ui_story_5045_50451501_30_dialog_content = "¿Qué piensas?",
  ui_story_5045_50451501_31_dialog_content = "Bueno... Supongo que debe ser bastante positivo, ¿no?",
  ui_story_5045_50451501_32_dialog_content = "PlayerName ha demostrado ser digno de ser elegido personalmente por usted, Juez Presidente, para ayudarnos aquí.",
  ui_story_5045_50451501_33_dialog_content = "Con la ayuda de PlayerName, es natural que Tina debe hacer algunos progresos también.",
  ui_story_5045_50451501_34_dialog_content = "¡Tal vez no pase mucho tiempo antes de que se convierta en la segunda mejor jueza en la División de Romance!",
  ui_story_5045_50451501_35_dialog_content = "Tina, son PlayerName¿Los registros están completos?",
  ui_story_5045_50451501_36_dialog_content = "si, hice PlayerName escribir todo en detalle.",
  ui_story_5045_50451501_37_dialog_content = "La investigación solo rascó la superficie, y no se permitió que las partes se explicaran completamente en la corte...",
  ui_story_5045_50451501_38_dialog_content = "Tina, has estado durmiendo en la cancha?",
  ui_story_5045_50451501_39_dialog_content = "No he hecho nada por el estilo... Bostezo—",
  ui_story_5045_50451501_40_dialog_content = "Estaba luchando contra un ataque de somnolencia esta mañana, así que estuve durmiendo hasta ahora.",
  ui_story_5045_50451501_41_dialog_content = "La División de Romance se acaba de establecer y no hay casos de los que podamos aprender.",
  ui_story_5045_50451501_42_dialog_content = "Entiendo la presión.",
  ui_story_5045_50451501_43_dialog_content = "Pero recuerde que incluso un caso pequeño a nuestros ojos puede afectar la vida de las partes involucradas.",
  ui_story_5045_50451501_44_dialog_content = "La forma en que trates cada caso afectará la actitud que la gente de Lumopolis tenga hacia las relaciones románticas en el futuro.",
  ui_story_5045_50451501_45_dialog_content = "Parece que la opinión pública como resultado de tomar el caso esta mañana no es muy buena...",
  ui_story_5045_50451501_46_dialog_content = "Los que abogan por la libertad en el amor y el matrimonio están muy descontentos con el juicio de esta mañana.",
  ui_story_5045_50451501_47_dialog_content = "Es posible que veamos apelaciones de represalia contra el Salón de Justicia en un futuro próximo.",
  ui_story_5045_50451501_48_dialog_content = "Prepárense.",
  ui_story_5045_50451501_49_dialog_content = "¿Apelaciones de represalia?",
  ui_story_5045_50451501_50_dialog_content = "Incluso podemos ver personas que se casan intencionalmente y luego demandan el divorcio.",
  ui_story_5045_50451501_51_dialog_content = "Ya que Tina es la que provocó todo este problema, dejemos que Tina manejar tales apelaciones por sí misma.",
  ui_story_5045_50451501_52_dialog_content = "Zzz...",
  ui_story_5045_50451501_53_dialog_content = "Bueno, parece Tina aprueba",
  ui_story_5045_50451501_54_dialog_content = "¿Eh? E-Espera...",
  ui_story_5045_50451501_55_dialog_content = "Entonces, esencialmente, ¿tengo que lidiar con todos los casos de divorcio que pasan por aquí?",
  ui_story_5045_50451501_56_dialog_content = "¿Cuántas sesiones se necesitarán para completar cada prueba?",
  ui_story_5045_50451601_1_dialog_content = "<color=#737378>Hora: 15:00</color>",
  ui_story_5045_50451601_2_dialog_content = "<color=#737378>Ubicación: Salón de Justicia Lumo, Sala del Tribunal</color>",
  ui_story_5045_50451601_3_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451601_4_dialog_content = "<size=45>¡La corte está en sesión!</size>",
  ui_story_5045_50451601_5_dialog_content = "En primer lugar, escuchemos lo que tiene que decir el demandante.",
  ui_story_5045_50451601_6_dialog_content = "¿Mmm? ¿Y quien eres tu?",
  ui_story_5045_50451601_7_dialog_content = "¿Realmente puedes hacer un buen trabajo al tratar mi caso?",
  ui_story_5045_50451601_8_dialog_content = "¡Ordenar!",
  ui_story_5045_50451601_9_dialog_content = "Por favor, no haga preguntas irrelevantes para este caso.",
  ui_story_5045_50451601_10_dialog_content = "¡Qué descaro!",
  ui_story_5045_50451601_11_dialog_content = "¿Sabes quién soy? ¿De dónde saca derecho un patético y pequeño juez como tú a hablarme así?",
  ui_story_5045_50451601_12_dialog_content = "debería reportarte a Irridon!",
  ui_story_5045_50451601_13_dialog_content = "Soy un juez de prueba, designado personalmente por el juez principal Irridon.",
  ui_story_5045_50451601_14_dialog_content = "Por favor coopere para mantener el orden en el Salón de Justicia.",
  ui_story_5045_50451601_15_dialog_content = "¡Hmph! ¡Solo espera!",
  ui_story_5045_50451601_16_dialog_content = "¿Eh? Demandante, ¿adónde va?",
  ui_story_5045_50451601_17_dialog_content = "<color=#737378>Hora: 16:00</color>",
  ui_story_5045_50451601_18_dialog_content = "<color=#737378>Ubicación: Sala de Justicia de Lumo</color>",
  ui_story_5045_50451601_19_dialog_content = "Dama Irridon, me has estado buscando?",
  ui_story_5045_50451601_20_dialog_content = "PlayerName, ¿sabe que alguien ha presentado una denuncia en su contra?",
  ui_story_5045_50451601_21_dialog_content = "¿Eh? ¿Ese tipo realmente se quejó de mí hace un momento?",
  ui_story_5045_50451601_22_dialog_content = "Pero no creo que haya dicho nada malo. ¡Mostró una completa falta de respeto por el orden del Salón de Justicia!",
  ui_story_5045_50451601_23_dialog_content = "Él tiene sus problemas. Naturalmente, esto es algo que entiendo muy bien.",
  ui_story_5045_50451601_24_dialog_content = "Pero tu...",
  ui_story_5045_50451601_25_dialog_content = "Te pedí que fueras a la División de Romance para ayudar, pero no te di permiso para escuchar casos por ti mismo.",
  ui_story_5045_50451601_26_dialog_content = "No creo que sea tan difícil, así que tal vez, tal vez pueda...",
  ui_story_5045_50451601_27_dialog_content = "Si fuera tan fácil convertirse en un juez real, incluso Angel habría pasado el examen de juicio simulado.",
  ui_story_5045_50451601_28_dialog_content = "Admito que tienes un don.",
  ui_story_5045_50451601_29_dialog_content = "Pero esto no significa que pueda saltarse la etapa de aprendizaje y convertirse en juez de inmediato.",
  ui_story_5045_50451601_30_dialog_content = "Incluso un genio nacido en una familia de jueces debería comenzar como magistrado asistente.",
  ui_story_5045_50451601_31_dialog_content = "Lo siento...",
  ui_story_5045_50451601_32_dialog_content = "Yo entiendo. ¡Regresaré y trabajaré aún más duro como asistente ahora!",
  ui_story_5045_50451601_33_dialog_content = "...",
  ui_story_5045_50451601_34_dialog_content = "No hay necesidad de eso.",
  ui_story_5045_50451601_35_dialog_content = "¿En serio?",
  ui_story_5045_50451601_36_dialog_content = "Para evitar que este asunto se fermente hasta el punto en que el público malinterprete las intenciones de la Sala de Justicia...",
  ui_story_5045_50451601_37_dialog_content = "Lo siento mucho, PlayerName, pero ya no puedes seguir trabajando en el Salón de la Justicia.",
  ui_story_5045_50451601_38_dialog_content = "Bueno, entonces, ¿qué pasa con mi pago...?",
  ui_story_5045_50451601_39_dialog_content = "El Salón de Justicia tuvo que pagar una gran suma para apaciguar al denunciante en este momento.",
  ui_story_5045_50451601_40_dialog_content = "Su pago está lejos de ser suficiente para cubrir esta compensación.",
  ui_story_5045_50451601_41_dialog_content = "Pero como tengo mi propia responsabilidad en este asunto, no le pediré que pague ningún cargo adicional por dicha compensación.",
  ui_story_5045_50451601_42_dialog_content = "Si está dispuesto a asistir a alguno de los juicios aquí, las puertas del Salón de Justicia todavía están abiertas para usted.",
  ui_story_5045_50451601_43_dialog_content = "Mmm...",
  ui_story_5045_50451601_44_dialog_content = "M-Mi pago...",
  ui_story_5045_50451601_45_dialog_content = "¡Si hubiera sabido que esto sucedería, habría sido su asistente y nada más!",
  ui_story_5045_50451601_46_dialog_content = "Y en cuanto a este cuaderno... me temo que no podrás quedártelo.",
  ui_story_5045_50451601_47_dialog_content = "Me tomé la libertad de recogerlo, ya que estoy aquí.",
  ui_story_5045_50451601_48_dialog_content = "Dama Irridon, n-no te vayas...",
  ui_story_5045_50451601_49_dialog_content = "Esta vez...",
  ui_story_5045_50451601_50_dialog_content = "Realmente lo arruiné mucho esta vez...",
  ui_story_5045_50451701_1_dialog_content = "<color=#737378>Hora: 8:00 AM</color>",
  ui_story_5045_50451701_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50451701_3_dialog_content = "El matrimonio debe ser arreglado por la familia. ¡Esta es la responsabilidad de la nobleza!",
  ui_story_5045_50451701_4_dialog_content = "Si su familia hiciera los arreglos para que usted se case con una mujer desaliñada que se niega a bañarse, ¿aceptaría su destino?",
  ui_story_5045_50451701_5_dialog_content = "Creo que mi familia nunca encontraría una esposa así para mí.",
  ui_story_5045_50451701_6_dialog_content = "Pero no puedes estar seguro de eso.",
  ui_story_5045_50451701_7_dialog_content = "¡Al final, todos ustedes solo quieren maximizar sus intereses y propiedades y no preocuparse por los sentimientos de la parte en cuestión!",
  ui_story_5045_50451701_8_dialog_content = "¡Soy el juez que preside este caso! ¡Todos deben respetar mi juicio!",
  ui_story_5045_50451701_9_dialog_content = "Si tu juicio es incorrecto, seré yo quien sea regañado como tú...",
  ui_story_5045_50451701_10_dialog_content = "que esta pasando con Matthieu y Angel?",
  ui_story_5045_50451701_11_dialog_content = "Obviamente, no pueden ponerse de acuerdo sobre el caso que se encuentra actualmente en juicio.",
  ui_story_5045_50451701_12_dialog_content = "¿Por qué siguen peleando? Algunas personas están tratando de dormir aquí—Bostezo—",
  ui_story_5045_50451701_13_dialog_content = "A menos que alguien haga algo al respecto, seguirán luchando hasta que se ponga el sol...",
  ui_story_5045_50451701_14_dialog_content = "¿Qué tal si preguntamos qué está pasando? Tal vez podamos ayudar.",
  ui_story_5045_50451701_15_dialog_content = "Si tú lo dices, PlayerName...",
  ui_story_5045_50451701_16_dialog_content = "Bueno, no podemos quedarnos sentados y no hacer nada.",
  ui_story_5045_50451701_17_dialog_content = "Entonces... Matthieu, Angel, ¿de qué se trata el caso?",
  ui_story_5045_50451701_18_dialog_content = "Llegas justo a tiempo. Por favor escúchame y dime si mi juicio es razonable.",
  ui_story_5045_50451701_19_dialog_content = "La única hija de un gran noble está demandando a sus padres, alegando que han interferido en su libertad de amar.",
  ui_story_5045_50451701_20_dialog_content = "Sentí que el caso no era tan simple como parecía, así que traje Angel para visitarlos y reunir pruebas.",
  ui_story_5045_50451701_21_dialog_content = "Resulta que su única hija se ha enamorado de un chico pobre que ni siquiera tiene un trabajo decente.",
  ui_story_5045_50451701_22_dialog_content = "¡No, fueron esos nobles padres quienes deliberadamente le hicieron perder su trabajo! Solía ser un buen cocinero.",
  ui_story_5045_50451701_23_dialog_content = "¿No confirmamos esto a través de nuestra investigación?",
  ui_story_5045_50451701_24_dialog_content = "Pero es un plebeyo. ¡No hay forma de que se haya acercado a una chica noble sin otra intención!",
  ui_story_5045_50451701_25_dialog_content = "¡No estoy de acuerdo!",
  ui_story_5045_50451701_26_dialog_content = "Esta noble chica está dispuesta a renunciar a toda su riqueza por él...",
  ui_story_5045_50451701_27_dialog_content = "También quiere dejar de perseguirla para no poner en peligro el futuro de la noble chica.",
  ui_story_5045_50451701_28_dialog_content = "Esto es un amor puro.",
  ui_story_5045_50451701_29_dialog_content = "Como dijiste, el pobre chico finalmente se dio cuenta de la distancia entre sus circunstancias y estaba dispuesto a renunciar a esta relación.",
  ui_story_5045_50451701_30_dialog_content = "Así que juzgué que los nobles padres tenían razón. hay algun problema con esto?",
  ui_story_5045_50451701_31_dialog_content = "Suena muy complicado...",
  ui_story_5045_50451701_32_dialog_content = "¿Eh? ¿Qué es esto en el suelo?",
  ui_story_5045_50451701_33_dialog_content = "Creo que he visto esto en alguna parte antes?",
  ui_story_5045_50451701_34_dialog_content = "Oh, supongo que no. Pero recuerdo...",
  ui_story_5045_50451701_35_dialog_content = "Recuerdo que después de la investigación, definitivamente le devolví esto a Sophie...",
  ui_story_5045_50451701_36_dialog_content = "Supuse que no me di cuenta antes, pero esto <color=#1875ad>tarjeta de asistencia</color> es idéntico al de Bacon!",
  ui_story_5045_50451701_37_dialog_content = "Definitivamente le devolví esto a Bacon después de la investigación...",
  ui_story_5045_50451701_38_dialog_content = "Supuse que no me di cuenta antes, pero esto <color=#1875ad>tarjeta de asistencia</color> es idéntico al de Sophie!",
  ui_story_5045_50451701_39_dialog_content = "Pero...",
  ui_story_5045_50451701_40_dialog_content = "¡Lo siento, esta es la evidencia que acabo de encontrar! No me había fijado en uno de ellos antes...",
  ui_story_5045_50451701_41_dialog_content = "Gracias, PlayerName. Si alguien hubiera pasado a recogerlo, habría sido difícil de explicar.",
  ui_story_5045_50451701_42_dialog_content = "Angel, será mejor que termines tu trabajo y luego discutiremos cómo juzgar este caso.",
  ui_story_5045_50451701_43_dialog_content = "...",
  ui_story_5045_50451701_44_dialog_content = "Angel, ¿de quién es esta tarjeta de asistencia?",
  ui_story_5045_50451701_45_dialog_content = "¿eh? ¡Estas bien! ¿Solo una mirada y sabías que era una tarjeta de asistencia?",
  ui_story_5045_50451701_46_dialog_content = "Esto es lo que encontramos en <color=#1875ad>Carlos</color>la casa de Según él, estudió derecho en este curso de autoayuda...",
  ui_story_5045_50451701_47_dialog_content = "Parece que quiere cambiar su situación actual y aspirar a convertirse en juez.",
  ui_story_5045_50451701_48_dialog_content = "No, hay algo que no está bien aquí...",
  ui_story_5045_50451701_49_dialog_content = "Es una tarjeta... Parece una especie de tarjeta de asistencia.",
  ui_story_5045_50451701_50_dialog_content = "Oh sí. Empecé a tomar algunas lecciones de limpieza recientemente.",
  ui_story_5045_50451701_51_dialog_content = "¿Eh? ¿Qué es esta carta aquí en la mesa?",
  ui_story_5045_50451701_52_dialog_content = "... Eso es de la <color=#1875ad>curso de autoayuda</color>. Es una tarjeta de asistencia.",
  ui_story_5045_50451701_53_dialog_content = "Ayudan a las personas a desarrollar su fuerza de voluntad para que ya no teman enfrentar las dificultades de la vida.",
  ui_story_5045_50451701_54_dialog_content = "Escuché que muchos de los estudiantes que tomaron este curso se convirtieron en los nuevos millonarios de Lumopolis.",
  ui_story_5045_50451701_55_dialog_content = "¿Por qué los cursos de los que todos hablan son diferentes?",
  ui_story_5045_50451701_56_dialog_content = "¿Podría ser?",
  ui_story_5045_50451701_57_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_5045_50451701_58_dialog_content = "Matthieu, el nombre del pobre chico del que se enamoró la noble chica en tu caso...",
  ui_story_5045_50451701_59_dialog_content = "Se llama Carlos. Oh, en serio, ¿por qué debo hacerme decir el nombre de un plebeyo?",
  ui_story_5045_50451701_60_dialog_content = "creo que he conocido <color=#1875ad>Carlos</color> en algún lugar antes...",
  ui_story_5045_50451701_61_dialog_content = "Eso no es todo! Recuerdo...",
  ui_story_5045_50451701_62_dialog_content = "¡Recuerdo que el vecino de Sophie se llamaba Karl!",
  ui_story_5045_50451701_63_dialog_content = "Y el amigo de Bacon y Fanny también se llamaba Karl...",
  ui_story_5045_50451701_64_dialog_content = "¡Recuerdo! ¡Karl era el nombre del amigo de Bacon y Fanny!",
  ui_story_5045_50451701_65_dialog_content = "Y creo que el vecino de Sophie también se llamaba Karl...",
  ui_story_5045_50451701_66_dialog_content = "¿Puede ser simplemente una coincidencia?",
  ui_story_5045_50451701_67_dialog_content = "PlayerName, ¿qué estabas murmurando para ti mismo hace un momento?",
  ui_story_5045_50451701_68_dialog_content = "Realmente no podemos ayudar con el caso de Matthieu.",
  ui_story_5045_50451701_69_dialog_content = "Intentemos ocuparnos de los casos de los que somos responsables en este momento.",
  ui_story_5045_50451701_70_dialog_content = "PlayerName, ¿a quién vas a ayudar esta vez?",
  ui_story_5045_50451701_71_dialog_content = "¿Por qué no dejamos PlayerName turnarse para ayudarnos, como el otro día?",
  ui_story_5045_50451701_72_dialog_content = "Eso sería justo, ¿no?",
  ui_story_5045_50451701_73_dialog_content = "Lo siento, quiero salir un rato a investigar algo...",
  ui_story_5045_50451701_74_dialog_content = "¿Eh? Si no estás investigando el caso, ¿qué estás investigando exactamente?",
  ui_story_5045_50451701_75_dialog_content = "Se trata de ese curso de autoayuda... Probablemente no sea nada, espero que solo esté pensando demasiado.",
  ui_story_5045_50451701_76_dialog_content = "<color=#737378>Hora: 9:00 a.m.</color>",
  ui_story_5045_50451701_77_dialog_content = "<color=#737378>Ubicación: Lumopolis, Bajo Lumopolis</color>",
  ui_story_5045_50451701_78_dialog_content = "¡Karl!",
  ui_story_5045_50451701_79_dialog_content = "¿Eh? Eres...",
  ui_story_5045_50451701_80_dialog_content = "¿No te acuerdas de mí? Soy el asistente de los jueces, PlayerName.",
  ui_story_5045_50451701_81_dialog_content = "Nos hemos visto dos veces antes.",
  ui_story_5045_50451701_82_dialog_content = "¡Oh, Su Señoría! ¿Qué puedo hacer por ti?",
  ui_story_5045_50451701_83_dialog_content = "Sí, en realidad, ¿sabe dónde puedo encontrar ese curso de autoayuda?",
  ui_story_5045_50451701_84_dialog_content = "¿Cómo puedo saberlo?",
  ui_story_5045_50451701_85_dialog_content = "Porque Fanny dijo que tú le diste a conocer, así que pensé que tal vez sabrías algo al respecto.",
  ui_story_5045_50451701_86_dialog_content = "Entonces, así es como es, alguien me lo acaba de mencionar.",
  ui_story_5045_50451701_87_dialog_content = "Pensé que probablemente era solo un lugar que vendía tranquilidad a personas desesperadas.",
  ui_story_5045_50451701_88_dialog_content = "Pero para las personas que se sienten sin esperanza acerca de sus vidas, la tranquilidad es exactamente lo que les falta.",
  ui_story_5045_50451701_89_dialog_content = "... Veo. ¿Hay algo más que puedas decirme?",
  ui_story_5045_50451701_90_dialog_content = "Lo siento, eso es todo lo que sé.",
  ui_story_5045_50451701_91_dialog_content = "Muy bien, gracias por su tiempo.",
  ui_story_5045_50451701_92_dialog_content = "Me iré entonces. Mis mejores deseos.",
  ui_story_5045_50451701_93_dialog_content = "(Definitivamente hay algo raro en este Karl.)",
  ui_story_5045_50451701_94_dialog_content = "(Será mejor que lo siga y vea a dónde va. Tal vez encuentre más pistas).",
  ui_story_5045_50451701_95_dialog_content = "(Pero...)",
  ui_story_5045_50451701_96_dialog_content = "¿A dónde fue él? ¡Simplemente desapareció en un abrir y cerrar de ojos así!",
  ui_story_5045_50451701_97_dialog_content = "<color=#737378>En algún momento, en algún lugar</color>",
  ui_story_5045_50451701_98_dialog_content = "¿Por qué estás parado como un tonto? Ve a buscar tu objetivo.",
  ui_story_5045_50451701_99_dialog_content = "P-Pero yo...",
  ui_story_5045_50451701_100_dialog_content = "¡No quiero hacer esto!",
  ui_story_5045_50451701_101_dialog_content = "Lo siento, gurú de la autoayuda, ¡perdóname!",
  ui_story_5045_50451701_102_dialog_content = "Está bien, no te estoy obligando.",
  ui_story_5045_50451701_103_dialog_content = "Entonces... ¿puedo irme a casa?",
  ui_story_5045_50451701_104_dialog_content = "Esperar. No tan rapido.",
  ui_story_5045_50451701_105_dialog_content = "Aunque solo has estado aquí medio día, seguramente puedes hacer algo más por mí.",
  ui_story_5045_50451701_106_dialog_content = "De lo contrario, su esposa puede terminar enojándose.",
  ui_story_5045_50451801_1_dialog_content = "<color=#737378>Hora: 16:00</color>",
  ui_story_5045_50451801_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50451801_3_dialog_content = "Ya de vuelta, PlayerName?",
  ui_story_5045_50451801_4_dialog_content = "¿Cómo va tu investigación?",
  ui_story_5045_50451801_5_dialog_content = "El plomo era un callejón sin salida, pero todavía no puedo quitarme esta sensación de inquietud.",
  ui_story_5045_50451801_6_dialog_content = "Por cierto, ¿dónde están Matthieu y Angel?",
  ui_story_5045_50451801_7_dialog_content = "Parece Matthieu quiere poner este caso en un segundo plano.",
  ui_story_5045_50451801_8_dialog_content = "Angel fue con Matthieu para investigar otro caso. No te preocupes por ellos, será mejor que pienses en...",
  ui_story_5045_50451801_9_dialog_content = "¿A quién planeas ayudar hoy?",
  ui_story_5045_50451801_10_dialog_content = "Yo...",
  ui_story_5045_50451801_11_dialog_content = "Disculpe, es PlayerName ¿aquí?",
  ui_story_5045_50451801_12_dialog_content = "Amy? ¿Hay algo en lo que pueda ayudarte?",
  ui_story_5045_50451801_13_dialog_content = "Yo... estoy aquí para <color=#1875ad>arrestar</color> ¡tú!",
  ui_story_5045_50451801_14_dialog_content = "¿¡Arrestame!? ¿Para qué?",
  ui_story_5045_50451801_15_dialog_content = "Alguien lo denunció ante la Corte Suprema, diciendo que creó una organización ilegal en Lumopolis especializada en cometer fraude.",
  ui_story_5045_50451801_16_dialog_content = "Debido a que el alcance del presunto fraude es particularmente amplio y la naturaleza es particularmente grave...",
  ui_story_5045_50451801_17_dialog_content = "¡La Sala de Justicia ha decidido arrestarte y comenzar el juicio mañana!",
  ui_story_5045_50451801_18_dialog_content = "Esto debe ser un error, ¿no?",
  ui_story_5045_50451801_19_dialog_content = "PlayerName nos ha estado ayudando con nuestro trabajo sin parar últimamente.",
  ui_story_5045_50451801_20_dialog_content = "No hay error. El demandante dijo que el acusado era un caelestita que trabajaba en el Salón de Justicia.",
  ui_story_5045_50451801_21_dialog_content = "A menos que me equivoque, eres el único Caelestita por aquí.",
  ui_story_5045_50451801_22_dialog_content = "Em...",
  ui_story_5045_50451801_23_dialog_content = "<color=#737378>Hora: 9:00 a. m., al día siguiente</color>",
  ui_story_5045_50451801_24_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, sala principal</color>",
  ui_story_5045_50451801_25_dialog_content = "(La galería del Salón de la Justicia está llena de audiencias susurrantes).",
  ui_story_5045_50451801_26_dialog_content = "(Oleadas de ojos disgustados parecen estar a punto de destrozarme.)",
  ui_story_5045_50451801_27_dialog_content = "(Hace unos días, todavía era un juez en prácticas sentado en el banquillo, pero hoy...)",
  ui_story_5045_50451801_28_dialog_content = "(Leyn, Tina... ¿No vinieron?)",
  ui_story_5045_50451801_29_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451801_30_dialog_content = "<size=45>Noche Blanca en lo alto. ¡La corte está ahora en sesión!</size>",
  ui_story_5045_50451801_31_dialog_content = "Noche Blanca en lo alto.",
  ui_story_5045_50451801_32_option_content = "Noche Blanca en lo alto...",
  ui_story_5045_50451801_33_dialog_content = "¡No puedo creer que realmente lo haya dicho! ¡Como se atreve!",
  ui_story_5045_50451801_34_option_content = "¡Me han tendido una trampa!",
  ui_story_5045_50451801_35_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451801_36_dialog_content = "Se pide al acusado que observe las normas y reglamentos del tribunal.",
  ui_story_5045_50451801_37_dialog_content = "Tenga en cuenta que perderá la oportunidad de defenderse después de recibir tres advertencias.",
  ui_story_5045_50451801_38_dialog_content = "(Conozco las reglas... ¿¡Por qué de repente me olvidé de mí mismo justo ahora!?)",
  ui_story_5045_50451801_39_option_content = "¡Objeción!",
  ui_story_5045_50451801_40_dialog_content = "PlayerName, usted ha estado trabajando en el Salón de la Justicia desde hace algún tiempo.",
  ui_story_5045_50451801_41_dialog_content = "¿Todavía necesitas que te enseñe sobre el proceso y las medidas disciplinarias practicadas aquí en el Salón de Justicia?",
  ui_story_5045_50451801_42_dialog_content = "(Recuerdo las medidas disciplinarias, pero ser acusado de repente... ¿Quién no se pondría un poco nervioso...?)",
  ui_story_5045_50451801_43_dialog_content = "Ahora, invitemos al demandante <color=#1875ad>Tocino</color> hablar.",
  ui_story_5045_50451801_44_dialog_content = "Señoría, yo soy Bacon.",
  ui_story_5045_50451801_45_dialog_content = "(¿¡¿Es Bacon?!? ¿Estaba descontento con el juicio? Tina y llegué la última vez?)",
  ui_story_5045_50451801_46_dialog_content = "(Pero después del juicio, fuimos juntos al campo. Todo estaba bien entonces).",
  ui_story_5045_50451801_47_dialog_content = "Hoy, yo... deseo demandar PlayerName en nombre de miles de víctimas en Lumopolis.",
  ui_story_5045_50451801_48_dialog_content = "La razón de esto es...",
  ui_story_5045_50451801_49_dialog_content = "Su <color=#1875ad>curso de autoayuda</color> es supuestamente un programa de formación que enseña habilidades a las personas necesitadas.",
  ui_story_5045_50451801_50_dialog_content = "La verdad es que todo lo que enseña a sus alumnos...",
  ui_story_5045_50451801_51_dialog_content = "... es cómo manipular las emociones de las personas para extorsionar a los ricos!",
  ui_story_5045_50451801_52_dialog_content = "<size=45>¿¡Qué!?</size>",
  ui_story_5045_50451801_53_dialog_content = "¡No puedo creer que exista tanta suciedad en Lumopolis!",
  ui_story_5045_50451801_54_dialog_content = "¡Este cabrón debe haberse colado de alguna manera en Lumopolis!",
  ui_story_5045_50451801_55_dialog_content = "PlayerName, ¿admite los cargos del demandante en su contra?",
  ui_story_5045_50451801_56_dialog_content = "¡Yo no hice nada de eso, y ni siquiera sé dónde está este curso de autoayuda!",
  ui_story_5045_50451801_57_dialog_content = "Bacon, ¿alguien te dijo que vinieras aquí y hicieras esto?",
  ui_story_5045_50451801_58_dialog_content = "eh, yo...",
  ui_story_5045_50451801_59_dialog_content = "¡No!",
  ui_story_5045_50451801_60_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451801_61_dialog_content = "Se insta al demandado a no engañar al demandante.",
  ui_story_5045_50451801_62_dialog_content = "(Pero Bacon claramente parece preocupado por algo).",
  ui_story_5045_50451801_63_dialog_content = "(Me arrestaron después de buscar a Karl ayer... ¡Esto no puede ser una coincidencia!)",
  ui_story_5045_50451801_64_dialog_content = "Demandante, usted dijo que tiene dos testigos que pueden probar todo lo que ha afirmado hasta ahora.",
  ui_story_5045_50451801_65_dialog_content = "Eso es correcto, Su Señoría.",
  ui_story_5045_50451801_66_dialog_content = "pido que el primero <color=#1875ad>testigo</color> ¡subir a la tribuna de testigos!",
  ui_story_5045_50451801_67_dialog_content = "Noche Blanca en lo alto.",
  ui_story_5045_50451801_68_dialog_content = "(¿¡Sophie!?)",
  ui_story_5045_50451801_69_dialog_content = "(Bueno, bueno... Es justo como pensaba.)",
  ui_story_5045_50451801_70_option_content = "¡Objeción!",
  ui_story_5045_50451801_71_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451801_72_dialog_content = "Ahora es el momento de que Sophie hable. Se pide al acusado que observe las normas y reglamentos del tribunal.",
  ui_story_5045_50451801_73_dialog_content = "¿No te acabo de decir que perderás la oportunidad de defenderte después de recibir tres advertencias?",
  ui_story_5045_50451801_74_dialog_content = "(Oh... ¡No puedo dejar que mis nervios me superen!)",
  ui_story_5045_50451801_75_dialog_content = "(¡Una advertencia más y estoy acabado!)",
  ui_story_5045_50451801_76_option_content = "(Permanecer en silencio)",
  ui_story_5045_50451801_77_dialog_content = "(Quiero escuchar lo que ella va a decir.)",
  ui_story_5045_50451801_78_dialog_content = "Señoría, mi nombre es Sophie. Puedo probar que lo que dijo Bacon es cierto.",
  ui_story_5045_50451801_79_dialog_content = "Soy uno de los primeros estudiantes de este curso de autoayuda.",
  ui_story_5045_50451801_80_dialog_content = "PlayerName me dijo que él era el último caelestita y que sabía cómo manipular la mente de las personas.",
  ui_story_5045_50451801_81_dialog_content = "Los estudiantes lo reverenciamos como el Gurú de la Autoayuda.",
  ui_story_5045_50451801_82_dialog_content = "Pero usó la intimidación, la coerción y otros medios para hacernos salir, manipular las emociones de las personas y robarles su dinero.",
  ui_story_5045_50451801_83_dialog_content = "No se nos permitía quedarnos con el dinero que engañábamos a la gente, y teníamos que entregárselo a él.",
  ui_story_5045_50451801_84_dialog_content = "En otras palabras, ¿admite que también está involucrado en la extorsión ilegal de riqueza?",
  ui_story_5045_50451801_85_dialog_content = "En seguida.",
  ui_story_5045_50451801_86_dialog_content = "Esto significa que serás juzgado en consecuencia. ¿Lo entiendes?",
  ui_story_5045_50451801_87_dialog_content = "Lo entiendo, pero mi conciencia no puede soportarlo más. No quiero que más personas sufran.",
  ui_story_5045_50451801_88_dialog_content = "En lugar de seguir confundido por el resto de mi vida, espero defender algo que valga la pena, solo por esta vez.",
  ui_story_5045_50451801_89_dialog_content = "(Sophie suena tan sincera... ¡Si no me estuviera acusando, lo creería!)",
  ui_story_5045_50451801_90_dialog_content = "PlayerName, ¿Tienes algo que decir?",
  ui_story_5045_50451801_91_dialog_content = "(¿Hay alguna prueba que demuestre que <color=#1875ad>lo que dijo sophie es falso</color>...)",
  ui_story_5045_50451801_92_dialog_content = "¿Qué quiere decir con esto?",
  ui_story_5045_50451801_93_dialog_content = "(¡Oh, no! ¿No es eso?)",
  ui_story_5045_50451801_94_dialog_content = "Dama Irridon! ¿Este es el cuaderno del juez que me diste?",
  ui_story_5045_50451801_95_dialog_content = "¿Mmm? Aunque todavía posee un cuaderno de juez, ahora es un acusado en el Salón de Justicia.",
  ui_story_5045_50451801_96_dialog_content = "Este cuaderno no te ayudará.",
  ui_story_5045_50451801_97_dialog_content = "¡Puedo jurar en el cuaderno de este juez que no soy el gurú de la autoayuda que ella pretende que sea!",
  ui_story_5045_50451801_98_dialog_content = "Lo siento, PlayerName.",
  ui_story_5045_50451801_99_dialog_content = "Si tales juramentos fueran de alguna utilidad, no habría necesidad de la Sala de Justicia.",
  ui_story_5045_50451801_100_dialog_content = "(¿Eso tampoco funcionará?)",
  ui_story_5045_50451801_101_dialog_content = "¡Su Señoría, Sophie una vez fabricó pruebas durante un juicio!",
  ui_story_5045_50451801_102_dialog_content = "¿En realidad? ¿Es esto cierto?",
  ui_story_5045_50451801_103_dialog_content = "P-Pero esa vez, tenía que hacerlo.",
  ui_story_5045_50451801_104_dialog_content = "En ese momento, tenía miedo de que Farrell se enterara de nuestro curso de autoayuda...",
  ui_story_5045_50451801_105_dialog_content = "Si eso sucediera, Self-help Guru me castigaría.",
  ui_story_5045_50451801_106_dialog_content = "¡Ahora que lo has capturado, no tengo nada que temer!",
  ui_story_5045_50451801_107_dialog_content = "Bueno, eso sí que es excusable.",
  ui_story_5045_50451801_108_dialog_content = "Entonces llamemos al segundo testigo.",
  ui_story_5045_50451801_109_dialog_content = "Señoría, mi nombre es Karl.",
  ui_story_5045_50451801_110_dialog_content = "Ayer tenía una cita para ir a cenar con Bacon, pero nunca apareció.",
  ui_story_5045_50451801_111_dialog_content = "Afortunadamente, Bacon me dijo adónde iba. Me tomó mucho tiempo encontrarlo.",
  ui_story_5045_50451801_112_dialog_content = "Eventualmente, encontré el legendario curso de autoayuda.",
  ui_story_5045_50451801_113_dialog_content = "Cuando llegué allí, escuché a Bacon decir que no quería aceptar la tarea que le había asignado Self-help Guru, e insistió en irse conmigo.",
  ui_story_5045_50451801_114_dialog_content = "Sentí que algo andaba muy mal, así que encendí un fuego en medio del caos y escapé con Bacon.",
  ui_story_5045_50451801_115_dialog_content = "Para escapar, el legendario Gurú de Autoayuda se quitó la túnica negra y reveló su verdadero rostro.",
  ui_story_5045_50451801_116_dialog_content = "En otras palabras, ¿viste cómo era el Gurú de autoayuda?",
  ui_story_5045_50451801_117_dialog_content = "En seguida.",
  ui_story_5045_50451801_118_dialog_content = "¿Y ves a este Gurú de Autoayuda aquí en la corte hoy?",
  ui_story_5045_50451801_119_dialog_content = "Sí. El Gurú de Autoayuda es el caballero sentado en el banquillo.",
  ui_story_5045_50451801_120_dialog_content = "(¿Cómo puede ser esto? ¿Qué cree este tal Karl que está haciendo...?)",
  ui_story_5045_50451801_121_dialog_content = "(¡Oh, sí, sé algo que podría funcionar aquí!)",
  ui_story_5045_50451801_122_option_content = "¡Enlace mental!",
  ui_story_5045_50451801_123_dialog_content = "(Fue un movimiento inteligente afirmar ser Caelestita al crear ese curso de autoayuda).",
  ui_story_5045_50451801_124_dialog_content = "(Ahora todos saben que el Gurú de autoayuda es Caelestite, y nadie tiene idea de mi verdadera identidad).",
  ui_story_5045_50451801_125_dialog_content = "(Es una pena que el curso de autoayuda tenga que terminar aquí... Afortunadamente, hice más que suficiente con él).",
  ui_story_5045_50451801_126_dialog_content = "¡Maldita sea, el verdadero gurú de la autoayuda es en realidad Karl!",
  ui_story_5045_50451801_127_dialog_content = "(Cariño mío PlayerName, sé que existe la posibilidad de que estés escuchando mi voz interior en este momento).",
  ui_story_5045_50451801_128_dialog_content = "¿Qué? ¿Cómo lo supo?",
  ui_story_5045_50451801_129_dialog_content = "(Es posible que puedas escuchar los pensamientos de las personas gracias a tu talento especial...)",
  ui_story_5045_50451801_130_dialog_content = "(Pero puedo inferir tus pensamientos a través de cada uno de tus movimientos).",
  ui_story_5045_50451801_131_dialog_content = "(Entonces, ¿cuál de nosotros es más poderoso?)",
  ui_story_5045_50451801_132_dialog_content = "¡Su Señoría!",
  ui_story_5045_50451801_133_dialog_content = "¡He descubierto a través de mi habilidad psíquica que Karl es el gurú de la autoayuda!",
  ui_story_5045_50451801_134_dialog_content = "¡Este acusado realmente sabe cómo manipular a la gente!",
  ui_story_5045_50451801_135_dialog_content = "¿¡Cómo podemos creer todo lo que dice!?",
  ui_story_5045_50451801_136_dialog_content = "Parece que este método no funcionará aquí...",
  ui_story_5045_50451801_137_dialog_content = "Pero debe haber una contradicción escondida en algún lugar de <color=#1875ad>el testimonio de carlos</color>.",
  ui_story_5045_50451801_138_dialog_content = "¿Qué estás tratando de decir?",
  ui_story_5045_50451801_139_dialog_content = "Ehm, solo quería decir...",
  ui_story_5045_50451801_140_dialog_content = "Karl me dijo ayer que nunca había asistido al curso de autoayuda y que ni siquiera sabía dónde se realizaba.",
  ui_story_5045_50451801_141_dialog_content = "¡Pero justo ahora, dijo que Bacon le dijo la dirección!",
  ui_story_5045_50451801_142_dialog_content = "Eso es porque, cuando te vi, aún no había quedado para comer con Bacon.",
  ui_story_5045_50451801_143_dialog_content = "¿Ah, de verdad? Bacon, ¿a qué hora hiciste la cita con Karl?",
  ui_story_5045_50451801_144_dialog_content = "A las diez de la mañana, ambos acordamos—",
  ui_story_5045_50451801_145_dialog_content = "Te estoy preguntando, tocino. ¿Cuándo se suponía que conocerías a Karl?",
  ui_story_5045_50451801_146_dialog_content = "Hicimos una cita a las 10 AM para cenar a las 6 PM...",
  ui_story_5045_50451801_147_dialog_content = "Eso es extraño. Me arrestaron a las cuatro de la tarde de ayer.",
  ui_story_5045_50451801_148_dialog_content = "Entonces, ¿cómo podría estar allí en el curso de autoayuda con ustedes dos?",
  ui_story_5045_50451801_149_dialog_content = "¡Bacon estaba muerto de miedo ayer! ¡Simplemente no pudo recordar claramente por un momento fugaz!",
  ui_story_5045_50451801_150_dialog_content = "Teníamos una cita para almorzar a las doce, ¿no?",
  ui_story_5045_50451801_151_dialog_content = "Correcto, eso es todo... Lo recordé incorrectamente ahora porque estaba muy asustado ayer...",
  ui_story_5045_50451801_152_dialog_content = "Después de estar tan asustados, las víctimas pueden desarrollar trastornos de la memoria.",
  ui_story_5045_50451801_153_dialog_content = "Pero mas importante, PlayerName...",
  ui_story_5045_50451801_154_dialog_content = "Los Caballeros de la Justicia descubrieron muchas tarjetas de asistencia sin usar en su residencia temporal.",
  ui_story_5045_50451801_155_dialog_content = "¿Qué tienes que decir en tu favor?",
  ui_story_5045_50451801_156_option_content = "¡Alguien los plantó!",
  ui_story_5045_50451801_157_dialog_content = "Todas las pruebas apuntan a ti. Será mejor que te expliques lo más claramente posible.",
  ui_story_5045_50451801_158_dialog_content = "Pero realmente no sé de dónde vinieron estas tarjetas de asistencia.",
  ui_story_5045_50451801_159_dialog_content = "¿¡He estado sonámbulo o algo así!?",
  ui_story_5045_50451801_160_option_content = "¡Objeción!",
  ui_story_5045_50451801_161_dialog_content = "¿Qué le da derecho a registrar mi residencia a voluntad?",
  ui_story_5045_50451801_162_dialog_content = "Eres el sospechoso número uno en este caso. Con tal causa probable, registrar su residencia es legal y razonable.",
  ui_story_5045_50451801_163_dialog_content = "Bueno...",
  ui_story_5045_50451801_164_option_content = "Dónde están Tina y Leyn?",
  ui_story_5045_50451801_165_dialog_content = "¡Quiero que testifiquen por mí!",
  ui_story_5045_50451801_166_dialog_content = "Han estado ocupados investigando sus respectivos casos y no he podido encontrarlos.",
  ui_story_5045_50451801_167_dialog_content = "¿Qué debo hacer?",
  ui_story_5045_50451801_168_dialog_content = "¿Eso es todo lo que tienes que decir?",
  ui_story_5045_50451801_169_dialog_content = "eh, yo...",
  ui_story_5045_50451801_170_dialog_content = "<color=#737378>¡Ruido!</color>",
  ui_story_5045_50451801_171_dialog_content = "Noche Blanca en lo alto. Es hora de...",
  ui_story_5045_50451801_172_dialog_content = "¡Espera!",
  ui_story_5045_50451801_173_dialog_content = "¿En serio?",
  ui_story_5045_50451801_174_dialog_content = "¡Su Señoría, todavía tenemos testigos que no han comparecido ante el tribunal!",
  ui_story_5045_50451801_175_dialog_content = "Lo siento, PlayerName... No es demasiado tarde, ¿verdad?",
  ui_story_5045_50451801_176_dialog_content = "Leyn, Tina...",
  ui_story_5045_50451801_177_dialog_content = "El juicio aún no ha terminado. ¡Pido que los testigos restantes ahora den un paso al frente y testifiquen!",
  ui_story_5045_50451801_178_dialog_content = "Señoría, mi nombre es Fanny...",
  ui_story_5045_50451801_179_dialog_content = "¿F-Fanny? ¿¡Estás bien!?",
  ui_story_5045_50451801_180_dialog_content = "...!?",
  ui_story_5045_50451801_181_dialog_content = "Estoy bien, tocino. No te preocupes por mí. Podemos decirle al juez principal la verdad.",
  ui_story_5045_50451801_182_dialog_content = "No tengas miedo. El Salón de la Justicia garantizará su seguridad.",
  ui_story_5045_50451801_183_dialog_content = "Ayer estuve <color=#1875ad>secuestrado</color>.",
  ui_story_5045_50451801_184_dialog_content = "Los secuestradores me tomaron como rehén y me usaron para amenazar a Bacon, obligándolo a testificar contra una persona inocente.",
  ui_story_5045_50451801_185_dialog_content = "¡Sí! ¡Es cierto! ¡Todo lo que dije hace un momento fue lo que el Gurú de Autoayuda me dijo que dijera!",
  ui_story_5045_50451801_186_dialog_content = "Me moría de miedo de que le hicieran daño a Fanny...",
  ui_story_5045_50451801_187_dialog_content = "Afortunadamente, los jueces Leyn y Tina me encontró y me rescató.",
  ui_story_5045_50451801_188_dialog_content = "Ahora, puedo testificar en la corte.",
  ui_story_5045_50451801_189_dialog_content = "Está seguro PlayerName ¿es inocente?",
  ui_story_5045_50451801_190_dialog_content = "Él es, Su Señoría.",
  ui_story_5045_50451801_191_dialog_content = "En cuanto al verdadero Gurú de la Autoayuda, aunque llevaba una máscara, recuerdo su voz...",
  ui_story_5045_50451801_192_dialog_content = "Karl, te tratamos como un amigo. ¿Por qué nos hiciste esto?",
  ui_story_5045_50451801_193_dialog_content = "...",
  ui_story_5045_50451801_194_dialog_content = "¡Su Señoría, esto debe ser algún tipo de malentendido! ¡Algún tipo de malentendido grave!",
  ui_story_5045_50451801_195_dialog_content = "Dama Irridon, encontramos la entrada a un sótano secreto en su casa.",
  ui_story_5045_50451801_196_dialog_content = "Si entramos y buscamos, podemos encontrar más pruebas.",
  ui_story_5045_50451801_197_dialog_content = "Exactamente, y le pedimos a los Lumo Knights que rodearan toda la vecindad.",
  ui_story_5045_50451801_198_dialog_content = "Solo estamos esperando su confirmación, señora. Irridon.",
  ui_story_5045_50451801_199_dialog_content = "...",
  ui_story_5045_50451801_200_dialog_content = "¡Karl está tratando de escapar! ¡Cuidado!",
  ui_story_5045_50451801_201_dialog_content = "¡Alto ahí!",
  ui_story_5045_50451801_202_dialog_content = "¡No puedes escapar!",
  ui_story_5045_50451801_203_dialog_content = "Urgh...",
  ui_story_5045_50451901_1_dialog_content = "<color=#737378>Hora: 12:00 p. m.</color>",
  ui_story_5045_50451901_2_dialog_content = "<color=#737378>Ubicación: Lumo Hall of Justice, Oficina de la División Romance</color>",
  ui_story_5045_50451901_3_dialog_content = "Dama Irridon, ¡eso realmente fue un juicio difícil en este momento!",
  ui_story_5045_50451901_4_dialog_content = "Dama Irridon está hablando con PlayerName. Guarda tu aliento.",
  ui_story_5045_50451901_5_dialog_content = "... Te perdonaré esta vez, pero solo porque realmente planteas un buen punto.",
  ui_story_5045_50451901_6_dialog_content = "PlayerName, Te hice una gran injusticia hoy.",
  ui_story_5045_50451901_7_dialog_content = "Dama Irridon... No sabías que me estaban engañando todo el tiempo, ¿verdad?",
  ui_story_5045_50451901_8_dialog_content = "¿Es eso lo que dije?",
  ui_story_5045_50451901_9_dialog_content = "Mi pensamiento es, si realmente hubieras obtenido tanto dinero...",
  ui_story_5045_50451901_10_dialog_content = "No habrías estado dispuesto a venir al Salón de la Justicia para ayudarnos por tal salario.",
  ui_story_5045_50451901_11_dialog_content = "Erm... Realmente no sé si debería estar feliz o triste.",
  ui_story_5045_50451901_12_dialog_content = "Tina, Leyn, tu actuación de hoy realmente me sorprendió.",
  ui_story_5045_50451901_13_dialog_content = "¿Cómo supiste que Fanny había sido secuestrada?",
  ui_story_5045_50451901_14_dialog_content = "Encontramos a mi cliente, Farrell. No estaba dispuesto a decir nada al principio, pero gracias a Tina...",
  ui_story_5045_50451901_15_dialog_content = "Sé que no quieres testificar contra la mujer que amas, ¡pero esta es la única forma en que puedes salvarla!",
  ui_story_5045_50451901_16_dialog_content = "¡Si no lo haces, será manipulada para siempre por ese Gurú de Autoayuda y vivirá una vida de sufrimiento y humillación!",
  ui_story_5045_50451901_17_dialog_content = "¿Es esta... la única forma de salvarla?",
  ui_story_5045_50451901_18_dialog_content = "Farrell nos dijo que había notado ciertas cosas extrañas que Sophie había estado haciendo.",
  ui_story_5045_50451901_19_dialog_content = "La razón por la que deseaba desesperadamente que Sophie se casara con él era para poder salvarla de las garras del Gurú de la autoayuda.",
  ui_story_5045_50451901_20_dialog_content = "También nos contó algunos de los lugares a los que solía ir Sophie.",
  ui_story_5045_50451901_21_dialog_content = "Este lugar es tan grande. ¿Por dónde deberíamos empezar...?",
  ui_story_5045_50451901_21X1_dialog_content = "¿Eh? donde esta Leyn?",
  ui_story_5045_50451901_22_dialog_content = "Señoras, ¿han visto un grupo de personas sospechosas por aquí?",
  ui_story_5045_50451901_23_dialog_content = "¡Sí! ¡Ciertamente lo tenemos! ¡Déjame contarte todo sobre ellos, guapo!",
  ui_story_5045_50451901_24_dialog_content = "Allí encontramos no solo a Fanny, sino también a una niña.",
  ui_story_5045_50451901_25_dialog_content = "Esa niña era la hermana de Sophie...",
  ui_story_5045_50451901_26_dialog_content = "Estaba usando múltiples rehenes para someter a esta buena gente a su voluntad. ¡Karl es absolutamente incorregible!",
  ui_story_5045_50451901_27_dialog_content = "Sin embargo, Sophie tuvo la oportunidad de salvarse y ahora no puede escapar del juicio del Salón de la Justicia.",
  ui_story_5045_50451901_28_dialog_content = "Parece que has crecido mucho durante tu tiempo con la División de Romance.",
  ui_story_5045_50451901_29_dialog_content = "G-Gracias por decirlo, señora. Irridon!",
  ui_story_5045_50451901_30_dialog_content = "En realidad, debemos nuestro éxito actual a PlayerNamela intuición.",
  ui_story_5045_50451901_31_dialog_content = "¿Eh? ¿En realidad?",
  ui_story_5045_50451901_32_dialog_content = "PlayerName nos dijo antes de ser arrestado que quizás las pistas estaban ocultas en los dos casos que había juzgado anteriormente.",
  ui_story_5045_50451901_33_dialog_content = "Eso era básicamente yo hablando conmigo mismo. No estaba seguro de nada en ese momento...",
  ui_story_5045_50451901_34_dialog_content = "De todos modos, ¡resolvimos un gran caso esta vez!",
  ui_story_5045_50451901_35_dialog_content = "Dama Irridon, ¿Estás considerando darnos una recompensa?",
  ui_story_5045_50451901_36_dialog_content = "Tina...",
  ui_story_5045_50451901_37_dialog_content = "¿Cómo puedes pedir tal cosa tan descaradamente?",
  ui_story_5045_50451901_38_dialog_content = "Con respecto a una recompensa, ya he preparado algo para ti.",
  ui_story_5045_50451901_39_dialog_content = "Espera... Hazlo Angel y me sale algo tambien?",
  ui_story_5045_50451901_40_dialog_content = "PlayerName, gracias por venir a ayudarnos cuando el Salón de Justicia enfrentó una grave falta de personal.",
  ui_story_5045_50451901_41_dialog_content = "Durante este período, usted no solo ayudó a los jueces de la División de Romance a juzgar con éxito dos casos...",
  ui_story_5045_50451901_42_dialog_content = "Te encargaste de erradicar el mal...",
  ui_story_5045_50451901_43_dialog_content = "Y nos ayudó a llevar ante la justicia al gurú de la autoayuda que aterroriza a la gente de Lumopolis.",
  ui_story_5045_50451901_44_dialog_content = "Los miembros del Salón de Justicia han acordado que un <color=#1875ad>Juez Honorario</color> Se le otorgará un trofeo.",
  ui_story_5045_50451901_45_dialog_content = "¡Vaya, es una escultura! ¡Se ve tan especial!",
  ui_story_5045_50451901_46_dialog_content = "PlayerName, este trofeo tiene un peso tremendo.",
  ui_story_5045_50451901_47_dialog_content = "¿Eh? ¿Seré capaz de llevarlo?",
  ui_story_5045_50451901_48_dialog_content = "Quiero decir, el honor de recibir este trofeo no debe tomarse a la ligera.",
  ui_story_5045_50451901_49_dialog_content = "¡Jejeje! Si no puedes manejarlo, PlayerName¡Puedo usar mi Mano Divina para llevarlo por ti!",
  ui_story_5045_50451901_50_dialog_content = "¿Me estás dando un trofeo...?",
  ui_story_5045_50451901_51_dialog_content = "¿Qué? ¿No lo quieres?",
  ui_story_5045_50451901_52_dialog_content = "Me pregunto si ya no necesitas mi ayuda.",
  ui_story_5045_50451901_53_dialog_content = "Sí, puedes verlo de esa manera.",
  ui_story_5045_50451901_54_dialog_content = "Recientemente, muchos casos en Lumopolis estaban, de hecho, relacionados con el Gurú de Autoayuda.",
  ui_story_5045_50451901_55_dialog_content = "Ahora que el Gurú de Autoayuda ha sido arrestado, los casos de la División de Romance disminuirán gradualmente.",
  ui_story_5045_50451901_56_dialog_content = "Además, hay muchos jóvenes de Dawn Academia lista para venir aquí para pasantías. Pronto, ya no nos faltará personal.",
  ui_story_5045_50451901_57_dialog_content = "Por supuesto, pero si todavía quieres quedarte...",
  ui_story_5045_50451901_58_dialog_content = "Puedes entrenar junto con los jóvenes y permanecer después de pasar la revisión al final del período de prueba.",
  ui_story_5045_50451901_59_dialog_content = "Este proceso puede tomar de medio año a un año.",
  ui_story_5045_50451901_60_dialog_content = "Pero necesito volver y cuidar de Cloud Gardens, y mis amigos siempre necesitan que salga de aventuras con ellos...",
  ui_story_5045_50451901_61_dialog_content = "Tal vez sea mejor si mi tiempo en el Salón de la Justicia termina aquí.",
  ui_story_5045_50451901_62_dialog_content = "Es justo como dije: la vida en el Salón de la Justicia no es para todos.",
  ui_story_5045_50451901_63_dialog_content = "Entonces, PlayerName, ¿Ya te vas?",
  ui_story_5045_50451901_64_dialog_content = "PlayerName...",
  ui_story_5045_50451901_65_dialog_content = "(Siento que debería decir algo ahora mismo).",
  ui_story_5045_50451901_66_dialog_content = "(Pero, ¿qué debo decir?)",
  ui_story_5045_50451901_67_dialog_content = "(¡Oh! ¡Lo tengo!)",
  ui_story_5045_50451901_68_dialog_content = "Sí, sí, ya no hay necesidad de mirarlos.",
  ui_story_5045_50451901_69_dialog_content = "(¿Es eso? Siento que olvidé algo...)",
  ui_story_5045_50451901_70_dialog_content = "todavía tengo esto <color=#1875ad>cometa</color>.",
  ui_story_5045_50451901_71_dialog_content = "PlayerName, ¿qué debe hacer con esta cometa ahora?",
  ui_story_5045_50451901_72_dialog_content = "Deberíamos dárselo a Farrell, el caballero que espera que Sophie salga de prisión.",
  ui_story_5045_50451901_73_dialog_content = "Creo que después de que Sophie salga de prisión, tal vez tengan la oportunidad de volar esta cometa juntos.",
  ui_story_5045_50451901_74_dialog_content = "Está bien, me aseguraré de que lo consiga.",
  ui_story_5045_50451901_75_dialog_content = "La próxima vez que vuelvas a Lumopolis, tal vez también tengamos la oportunidad de volar cometas juntos...",
  ui_story_5045_50451901_76_dialog_content = "¡Por supuesto! ¡No es como si nunca nos volviéramos a ver!",
  ui_story_5045_50451901_77_dialog_content = "Bien. ¡Entonces haremos nuestras propias cometas cuando regreses!",
  ui_story_5045_50451901_78_dialog_content = "¡Te sostendré!",
  ui_story_5045_50451901_79_dialog_content = "de tina <color=#1875ad>figuritas de arcilla</color> todavía están aquí.",
  ui_story_5045_50451901_80_dialog_content = "PlayerName¡Quiero que tengas esto!",
  ui_story_5045_50451901_81_dialog_content = "¿En serio?",
  ui_story_5045_50451901_82_dialog_content = "Pero no me malinterpreten, solo quiero agradecerles por hacer mi trabajo mucho más fácil y divertido mientras estuvieron aquí.",
  ui_story_5045_50451901_83_dialog_content = "Ya que trabajamos en la División de Romance, por supuesto, les deseo todo lo mejor en asuntos del corazón en el futuro...",
  ui_story_5045_50451901_84_dialog_content = "Cuando conoces a alguien que te gusta, y esa persona también te quiere, ¡sé que tendrás un dulce amor que durará para siempre!",
  ui_story_5045_50451901_85_dialog_content = "Como estas dos figuritas de barro...",
  ui_story_5045_50451901_86_dialog_content = "¡La imagen del amor, extraída de la tierra y templada por el fuego, se convierte finalmente en un vínculo eterno!",
  ui_story_5045_50451901_87_dialog_content = "Muchas gracias, Tina!",
  ui_story_5045_50451901_88_dialog_content = "Aunque, creo que puede ser demasiado temprano en mi vida para recibir ese tipo de bendición...",
  ui_story_5045_50451901_89_dialog_content = "¡No es demasiado pronto para nada!",
  ui_story_5045_50451901_90_dialog_content = "Quiero decir... si no puedes encontrar a alguien que te guste, vuelve a Lumopolis, o tal vez al Salón de la Justicia.",
  ui_story_5045_50451901_91_dialog_content = "Por supuesto, prometo que volveré.",
  ui_story_5045_50451901_92_dialog_content = "¿D-De veras?",
  ui_story_5045_50451901_93_dialog_content = "¡Luego podemos ir al campo y hacer un montón de pequeñas figuritas de arcilla y luego dárselas a todos los amantes!",
  ui_story_5045_50451901_94_dialog_content = "¡Apuesta!",
  ui_story_5045_50451901_95_dialog_content = "Sin la División Romance, nunca me habrían concedido este preciado trofeo.",
  ui_story_5045_50451901_96_dialog_content = "Quiero dejar este trofeo con la División Romance.",
  ui_story_5045_50451901_97_dialog_content = "¡Esta es una gran idea!",
  ui_story_5045_50451901_98_dialog_content = "Pero donde quieres ponerlo, PlayerName?",
  ui_story_5045_50451901_99_dialog_content = "¿Realmente necesitas preguntar? ¡Solo ponlo en mi escritorio!",
  ui_story_5045_50451901_100_dialog_content = "Mire a su alrededor: ¡soy el único que tiene un escritorio lo suficientemente limpio para esa cosa!",
  ui_story_5045_50451901_101_dialog_content = "Yo creo.",
  ui_story_5045_50451901_102_dialog_content = "Todos deberían turnarse para ponerlo en sus escritorios.",
  ui_story_5045_50451901_103_dialog_content = "¡Sí, eso es justo!",
  ui_story_5045_50451901_104_dialog_content = "Entonces, ¡está decidido!",
  ui_story_5045_50451901_105_dialog_content = "¿Todos?",
  ui_story_5045_50451901_106_dialog_content = "Eso me incluye a mí, ¿verdad? Ey...",
  ui_story_5045_50451901_107_dialog_content = "En este cuaderno...",
  ui_story_5045_50451901_108_dialog_content = "Anoté todo y a todos los que encontré después de llegar a la División de Romance.",
  ui_story_5045_50451901_109_dialog_content = "Nuestra impotencia y angustia cuando nos enfrentamos juntos a grandes dificultades...",
  ui_story_5045_50451901_110_dialog_content = "¡Y la felicidad y la sensación de logro después de hacer un juicio exitoso juntos!",
  ui_story_5045_50451901_111_dialog_content = "¡Mientras tenga esto, nunca olvidaré los maravillosos días que pasé en la División de Romance!",
  ui_story_5045_50451901_112_dialog_content = "Mientras no estoy, todos, por favor escriban sus sentimientos en sus cuadernos por mí.",
  ui_story_5045_50451901_113_dialog_content = "En el futuro, cuando regrese...",
  ui_story_5045_50451901_114_dialog_content = "¡Podré escuchar todo sobre los casos extraños que me he estado perdiendo!",
  ui_story_5045_50451901_115_dialog_content = "De verdad...",
  ui_story_5045_50451901_116_dialog_content = "PlayerName, Eres tan malo...",
  ui_story_5045_50451901_117_dialog_content = "¡Deja de intentar hacernos llorar a todos!",
  ui_story_5045_50451901_118_dialog_content = "Gracias por el consejo, PlayerName...",
  ui_story_5045_50451901_119_dialog_content = "¡Grabaré todos los casos más fascinantes para ti!",
  ui_story_5045_50451901_120_dialog_content = "Ves esto, Angel? ¡Empieza a tomar notas!",
  ui_story_5045_50451901_121_dialog_content = "... ¡Bueno!",
  ui_story_5045_50451901_122_dialog_content = "Adiós a todos.",
  ui_story_5045_50451901_123_dialog_content = "Adiós, División Romance.",
  ui_story_5045_50451901_124_dialog_content = "yo se que un dia...",
  ui_story_5045_50451901_125_option_content = "¡Te veré de nuevo!"
}
return config
